        [HttpPost]
        public ActionResult DeletePhieuThu(string id, string type)
        {
            try
            {
                if (CurrentUser.ReadOnly == true)
                {
                    return Content("Bạn không có quyền xóa");
                }
                string message = _phieuThuService.DeletePhieuThu(id);
                //if(type == "TDIVU")
                //{
                //    if(message == "")
                //    {
                //        PhieuThu pt = _phieuThuService.CongNoHonDa(id);
                //        if (pt != null)
                //            DeletePhieuThu(pt.MaPhieuThu, "TKHAC");
                //    }
                //}
                if (string.IsNullOrEmpty(message))
                    return Content("success");
                else
                    return Content("Đã xóa phiếu xong. Có lỗi phát sinh:" + message);
            }
            catch (Exception ex)
            {
                TempData["Error"] = "Cập nhật thất bại" + ex;
                _logger.WriteLog("PhieuThu.DeletePhieuThu:", ex);
                return Content(ex.ToString());
            }
        }

        [HttpPost]
        public ActionResult UpdateSoHopDongTCOBX(string id, string shd)
        {
            try
            {
                if (CurrentUser.ReadOnly == true)
                {
                    return Content("Bạn không có quyền cập nhật");
                }
                string message = _phieuThuService.UpdateSHDTCOBX(id, shd);
                if (string.IsNullOrEmpty(message))
                    return Content("success");
                else
                    return Content("Không được phép cập nhật phiếu vì:" + message);
            }
            catch (Exception ex)
            {
                TempData["Error"] = "Cập nhật thất bại" + ex;
                _logger.WriteLog("PhieuThu.UpdateSoHopDongTCOBX:", ex);
                return Content(ex.ToString());
            }
        }
