        public SoThuModel GetModelCreate()
        {
            SoThuModel model = new SoThuModel();
            model.Item = new PhieuThu();
            model.Users = _userService.get();
            model.HTTT = _soThuService.GetHTTT();
            model.CTPT = new List<ChiTietPhieuThu>();
            model.CTPT.Add(new ChiTietPhieuThu());
            //model.CTBDTK = new List<ViewChiTietBaoDuongTietKiem>();
            //model.CTBDTK.Add(new ViewChiTietBaoDuongTietKiem());
            return model;
        }
        public SoThuModel GetModelEdit(string id)
        {
            SoThuModel model = new SoThuModel();
            model.Item = _phieuThuService.GetPhieuThu(id);
            if (model.Item == null)
                return null;
            model.Users = _userService.get();
            model.HTTT = _soThuService.GetHTTT();
            model.CTPT = _phieuThuService.GetCTPT(id);
            //chi xe chi tiet thanh toan khac coc
            if (model.CTPT.FindAll(x => x.HinhThucThanhToan != "DC").Count == 0)
            //if (model.CTPT.Count == 0)
            {
                // model.CTPT = new List<ChiTietPhieuThu>();
                model.CTPT.Add(new ChiTietPhieuThu());
            }
            ////neu la phieu thu phu kien thi lay coc len
            //if (model.Item.MaLoaiPhieu == "TPHKI")
            //{
            //    if (!string.IsNullOrEmpty(model.Item.BienSo))
            //        model.Coc = _phieuThuService.GetTCOC(model.Item.BienSo, true);
            //    else if (!string.IsNullOrEmpty(model.Item.SoHopDong))
            //        model.Coc = _phieuThuService.GetTCOC(model.Item.SoHopDong, true);
            //}
            return model;
        }
        public string GetTitle(string type)
        {

            switch (type)
            {
                case "TCOBX":
                    return "Thu cọc bán xe";
                case "TCODV":
                    return "Thu cọc phụ tùng - dịch vụ";
                case "TBAHI":
                    return "Thu bảo hiểm";
                case "THHHB":
                    return "Thu hoa hồng Holdback";
                case "TVAMU":
                    return "Thu vay mượn";
                case "TLADT":
                    return "Thu lãi đầu tư";
                case "TKHAC":
                    return "Thu khác";
                case "TPHKI":
                    return "Thu bán lẻ phụ tùng - phụ kiện";
                case "TKMPHKI":
                    return "Thu khuyến mãi phụ tùng - phụ kiện";
                case "TPHKITemp":
                    return "Thu phụ tùng - phụ kiện";
                case "KMTMV":
                    return "Ghi nhận khuyến mãi TMV";
                case "TBDTK":
                    return "Thu bán lẻ bảo dưỡng tiết kiệm";
                case "TBDTKKM":
                    return "Thu bảo dưỡng tiết kiệm khuyến mãi";
