                    return "";
            }
        }
        public ActionResult PhieuThu(string id = "", string type = "", string actiontype = "Create", int tab = 1, string MaXe = "", string TypeOfVote = "")
        {

            try
            {
                if (type.Contains("|"))
                {
                    string[] types = type.Split('|');
                    type = types[0];
                }
                if (type == "TPHKITemp" || type == "NKMPK")
                {
                    if (MaXe.Contains("%20"))
                    {
                        MaXe = MaXe.Replace("%20", "");
                    }
                    
                }
                ViewBag.Action = actiontype;
                ViewBag.Type = type;
                ViewBag.Alert = TempData["Alert"];
                ViewBag.Title = GetTitle(type);
                ViewBag.CurrentUser = CurrentUser.UserName;
                SoThuModel model;
                DataTable dt = new DataTable();
                if (id == "" || (type == "NKMPK" && actiontype == "Create"))
                {
                    model = GetModelCreate();
                    model.Item.MaLoaiPhieu = type;
                }
                else
                {
                    model = GetModelEdit(id);
                }
                bool isForInsert = false;
                switch (type)
                {
                    case "TCOBX":
                        model.MaLoaiXe = _soThuService.ListLoaiXe();
                        break;
                    case "TCODV":
                        model.MauXe = _categoryService.GetCategoryItem("COLOR");
                        model.MaXe = _categoryService.GetCategoryItem("MODEL");
                        break;
                    case "TBAHI"://cong ty bao hiem BH
                        model.DoiTac = _soThuService.GetDoiTac("BH");
                        //23/5/2022: thang.tran xu ly load coc ban xe + dich vu vao cac phieu
                        model.Coc = _phieuThuService.GetTCOC_V2(model.Item.MaPhieuThu, model.Item.BienSo, model.Item.SoHopDong, model.Item.HoTen, isForInsert);
                        List<DropDownListItem> listItem = new List<DropDownListItem>();

                        listItem.Add(new DropDownListItem("Chưa xác định", "CXD"));
                        listItem.Add(new DropDownListItem("Tái tục", "TT"));
                        listItem.Add(new DropDownListItem("Ký mới", "KM"));
                        model.ListItem = listItem;

                        break;
                    case "T1GHB":
                        model.DoiTac = _soThuService.GetDoiTac("BH");
                        //23/5/2022: thang.tran xu ly load coc ban xe + dich vu vao cac phieu
                        model.Coc = _phieuThuService.GetTCOC_V2(model.Item.MaPhieuThu, model.Item.BienSo, model.Item.SoHopDong, model.Item.HoTen, isForInsert);
                        break;
                    case "TKHAC":
                        //Trương Hoài Lộc: 24/08/2020
                        //Thêm loại bảo hiểm: Thu Khác 
                        model.DoiTac = _soThuService.GetDoiTac("NCC");
                        //List<DropDownListItem> listBH = new List<DropDownListItem>();
                        //listBH.Add(new DropDownListItem("Hoa hồng đăng ký xe", "HHDKX"));
                        //listBH.Add(new DropDownListItem("Hỗ trợ xe xuất", "HTXX"));
                        //listBH.Add(new DropDownListItem("Khác", "KHAC"));
                        List<DropDownListItem> listBH = new List<DropDownListItem>();
                        List<CategoryItem> ls = _categoryService.GetCategoryItem("TKHAC");
                        foreach (CategoryItem item in ls)
                        {
                            listBH.Add(new DropDownListItem(item.Name, item.Code));
                        }
                        model.LoaiBH = listBH;
                        break;
                    case "THHHB":
                        model.DoiTac = _soThuService.GetDoiTac("HHHB");
                        break;
                    case "TVAMU":
                        model.DoiTac = _soThuService.GetDoiTac("VM");
                        List<DropDownListItem> listItem_ = new List<DropDownListItem>();

                        listItem_.Add(new DropDownListItem("Dài hạn", "DH"));
                        listItem_.Add(new DropDownListItem("Ngắn hạn", "NH"));
                        model.ListItem = listItem_;
                        break;
                    case "TLADT":
                        model.DoiTac = _soThuService.GetDoiTac("DTU");
                        break;
                    case "TBHXH":
                        model.DoiTac = _soThuService.GetDoiTac("NCC");
                        break;
                    case "T2THK":
                        model.DoiTac = _soThuService.GetDoiTac("NCC");
                        model.LyDoThu = _categoryService.GetCategoryItem("LIDOTHUHO");
                        //23/5/2022: thang.tran xu ly load coc ban xe + dich vu vao cac phieu
                        model.Coc = _phieuThuService.GetTCOC_V2(model.Item.MaPhieuThu, model.Item.BienSo, model.Item.SoHopDong, model.Item.HoTen, isForInsert);
                        if (id != "")
                        {
                            ViewNoPhaiTra listNPTra = _noPhaiTraService.getNoPhaiTra(id);
                            if (listNPTra != null)
                            {
                                if (listNPTra.SoTienDaTra > 0)
                                    ViewBag.FlagT2THK = false;
                            }
                        }
                        break;
                    case "T2GTX":
                        model.DoiTac = _soThuService.GetDoiTac("NCC");
                        //23/5/2022: thang.tran xu ly load coc ban xe + dich vu vao cac phieu
                        model.Coc = _phieuThuService.GetTCOC_V2(model.Item.MaPhieuThu, model.Item.BienSo, model.Item.SoHopDong, model.Item.HoTen, isForInsert);
                        break;
                    //case "TKHAC":
                    //    model.DoiTac = _soThuService.GetDoiTac("NCC");
                    //    break;
                    case "TPHKI":
                        model.DoiTac = _soThuService.GetDoiTac("NCC");
                        model.MaXe = _categoryService.GetCategoryItem("MODEL");
                        model.LHTT = _commonService.getChuongTrinhDichVuHang();

                        ChiTietPhieuThu chiTiet = new ChiTietPhieuThu();
                        chiTiet.HinhThucThanhToan = "HA";
                        chiTiet.MaNganHang = string.Empty;
                        chiTiet.SoTienThanhToan = 0;
                        model.CTPT.Add(chiTiet);

                        //if (!string.IsNullOrEmpty(model.Item.BienSo))
                        //{
                        //    model.Coc = _phieuThuService.GetTCOC(model.Item.MaPhieuThu, model.Item.BienSo, model.Item.HoTen, true);
                        //}
                        //else if (!string.IsNullOrEmpty(model.Item.SoHopDong))
                        //{
                        //    model.Coc = _phieuThuService.GetTCOC(model.Item.MaPhieuThu, model.Item.SoHopDong, model.Item.HoTen, true);
                        //}

                        //23/5/2022: thang.tran xu ly load coc ban xe + dich vu vao cac phieu
                        model.Coc = _phieuThuService.GetTCOC_V2(model.Item.MaPhieuThu, model.Item.BienSo, model.Item.SoHopDong, model.Item.HoTen, isForInsert);

                        //else if(!string.IsNullOrEmpty(model.Item.HoTen))
                        //    model.Coc = _phieuThuService.GetTCOC(model.Item.HoTen, true);
                        if (id != "")
                        {
                            //model.CTBPK = _CTBPKService.GetByMaPhieuThu(id);
                            //ViewBag.ListPhuTung = _phieuThuService.GetListCTBPK(id);
                            dt = _phieuThuService.GetListCTBPK(id);
                            //neu chua co dong tien cong SCC thi them vao
                            if (dt.Select("MaKho='SCC'").Length == 0)
                            {
                                DataRow r = dt.NewRow();
                                r["MaKho"] = "SCC";
                                r["TenKho"] = "Tiền công";
                                r["TenHang"] = "Tiền công phụ kiện";
                                dt.Rows.Add(r);

                            }
                            ViewBag.ListPhuTung =dt;
                           
                        }
                        else
                        {
                            id = "";
                            //ViewBag.ListPhuTung = _phieuThuService.GetListCTBPK(id);
                            dt = _phieuThuService.GetListCTBPK(id);

                            //model.CTBPK = new List<ChiTietBanPhuKien>();
                            //model.CTBPK.Add(new ChiTietBanPhuKien());
                        }
                        DataRow[] dr = dt.Select("MaKho = 'KHO_DS'");
                        var s = dr[0]["TenHang"].ToString();
                        if (dr[0]["TenHang"].ToString() == "" && dr[0]["GiaBan"].ToString() == "" && dr[0]["GiamGia"].ToString() == "" && dr[0]["ThucThu"].ToString() == "")
