                        //}

                        //23/5/2022: thang.tran xu ly load coc ban xe + dich vu vao cac phieu
                        model.Coc = _phieuThuService.GetTCOC_V2(model.Item.MaPhieuThu, model.Item.BienSo, model.Item.SoHopDong, model.Item.HoTen, isForInsert);

                        //else if(!string.IsNullOrEmpty(model.Item.HoTen))
                        //    model.Coc = _phieuThuService.GetTCOC(model.Item.HoTen, true);
                        if (id != "")
                        {
                            //model.CTBPK = _CTBPKService.GetByMaPhieuThu(id);
                            var NPT = _noPhaiTraService.getNoPhaiTra(id);
                            ViewBag.CheckNKM = NPT != null ? _phieuThuService.CheckChiNoKMPK(NPT.MaPhieuNo) : false;
                            ViewBag.ListPhuTung = _phieuThuService.GetListCTBPKKM(id);
