                        }
                        else
                        {
                            id = "";
                            ViewBag.CheckNKM = false;
                            ViewBag.ListPhuTung = _phieuThuService.GetListCTBPKKM(id);
                            dt = _phieuThuService.GetListCTBPKKM(id);
                            //model.CTBPK = new List<ChiTietBanPhuKien>();
