                        TongCong += temp.SoTienThanhToan;
                    }
                    if (temp.MaNganHang == "COCDV" || temp.MaNganHang == "COCBX")
                        i -= 1;
                }
                ViewBag.CountCTPT = i;
                List<ViewHinhThucThanhToan> list = _phieuThuService.ThuHoaHongNgay();
                ViewBag.ThuHoaHong = list;
                ViewBag.Action = actiontype;
                ViewBag.Alert = TempData["Alert"];
                ViewBag.TongCong = TongCong;
                ViewBag.Title = GetTitle(type);
                ViewBag.Type = type;
                return View(model);
            }
            catch (Exception ex)
            {
                _logger.WriteLog("SoThuController:PhieuThu" + ex.ToString());
                TempData["Error"] = ex;
            }
            return View();
        }
        [HttpPost]
        public ActionResult PhieuThu(PhieuThu item, List<ChiTietPhieuThu> httt, string submit, string actiontype, string type
