                {
                    if (viewTPHKITemps != null)
                    {
                        var sohopdong = viewTPHKITemps.Where(x => x.MA_XE == MaXe).Select(x => x.SO_HOP_DONG).FirstOrDefault();
                        lstSoChungTu.Add(sohopdong == null ? item.SoHopDong : sohopdong);
                    }
                }
                else
                {
                    if (MaXe.Contains(","))
                    {
                        var ArraySCT = MaXe.Split(',');
                        if (ArraySCT.Length > 0)
                        {
                            foreach (var itemCT in ArraySCT)
                            {
                                lstSoChungTu.Add(itemCT);
                            }
                        }
                    }
                    else
