        #region Thu hộ
        public ActionResult PhieuThuHo(string id = "", string type = "", string actiontype = "Create", int tab = 1)
        {
            try
            {
                ViewBag.Action = actiontype;
                ViewBag.Type = type;
                ViewBag.Alert = TempData["Alert"];
                ViewBag.Title = GetSearchTitleThuHo(type);
                SoThuModel model;
                if (id == "")
                {
                    model = GetModelCreate();
                    model.Item.MaLoaiPhieu = type;
                }
                else
                {
                    model = GetModelEdit(id);
                }
                model.DoiTac = _soThuService.GetDoiTac("NCC");
                double TongCong = 0;
                int i = model.CTPT.Count;
                foreach (var temp in model.CTPT)
                {
                    if (type == "TPHKI" && temp.HinhThucThanhToan != "DC")
                    {
                        TongCong += temp.SoTienThanhToan;
                    }
                    if (temp.MaNganHang == "COCDV" || temp.MaNganHang == "COCBX")
                        i -= 1;
                }
                //if (model.Item.BienSo != "" || )
                //{
                    //model.Cocs = _phieuThuService.GetTCOC(model.Item.MaPhieuThu, model.Item.BienSo, model.Item.HoTen, true);
                    model.Cocs = _phieuThuService.GetTCOC_V2(model.Item.MaPhieuThu, model.Item.BienSo,model.Item.SoHopDong, model.Item.HoTen, actiontype=="Create"? true:false);
                //}
                ViewBag.CountCTPT = i;
                ViewBag.TongCong = TongCong;
                return View(model);
            }
            catch (Exception ex)
            {
                _logger.WriteLog("SoThuController:PhieuThuHo" + ex.ToString());
                TempData["Error"] = ex;
            }
            return View();
        }
        [HttpPost]
        public ActionResult PhieuThuHo(PhieuThu item, List<ChiTietPhieuThu> httt, string submit, string actiontype, string type, List<ChiTietPhieuThu> coc, List<ChiTietBanPhuKien> LPT)
        {
            if (CurrentUser.ReadOnly == true)
            {
                if (!(CurrentUser.UserName == "phuc.ngo" && (type == "T1GHB")))
                    return Redirect("/Home/NoAccess");

            }
            string xml = "<Action>PhieuThuHo</Action>";
            if (submit != null)
            {
                xml += Environment.NewLine + "<submit>" + submit + "</submit>";
            }
            if (actiontype != null)
            {
                xml += Environment.NewLine + "<actiontype>" + actiontype + "</actiontype>";
            }
            if (type != null)
            {
                xml += Environment.NewLine + "<type>" + type + "</type>";
            }
            if (item != null)
                xml += TNK.Core.Common.ConvertObjectToXMLString(item);
            if (httt != null)
            {
                xml += Environment.NewLine + "<ThanhToan>";
                foreach (ChiTietPhieuThu ct in httt)
                    xml += TNK.Core.Common.ConvertObjectToXMLString(ct);
                xml += Environment.NewLine + "</ThanhToan>";
            }
            if (coc != null)
            {
                xml += Environment.NewLine + "<Coc>";
                foreach (ChiTietPhieuThu ct in coc)
                    xml += TNK.Core.Common.ConvertObjectToXMLString(ct);
                xml += Environment.NewLine + "</Coc>";
                foreach (var i in coc)
                {
                    i.HinhThucThanhToan = "DC";
                    if (i.SoThamChieu.ToUpper().Contains("TCODV") )
                    {
                        i.Temp = "COCDV-DC";
                        i.MaNganHang = "COCDV";
                        i.MaPhieuThu = item.MaPhieuThu;
                        httt.Add(i);
                    }
                    if (i.SoThamChieu.ToUpper().Contains("TCOBX"))
                    {
                        i.Temp = "COCBX-DC";
                        i.MaNganHang = "COCBX";
                        i.MaPhieuThu = item.MaPhieuThu;
                        httt.Add(i);
                    }
                }
            }
            xml = "<formdata>" + Environment.NewLine + xml + Environment.NewLine + "</formdata>";
            try
            {
                if (actiontype == "Create")
                {
                    string message = "";
                    message = _phieuThuService.KiemTraCocTruocKhiUpdatePhieuThu(coc, "");
                    if (string.IsNullOrEmpty(message))
                    {
                        message = _phieuThuService.CreatePhieuThu(item, httt, true, xml);
                        if (string.IsNullOrEmpty(message))
                        {
                            //string result = _phieuThuService.XuLySauKhiInsertPhieuThu(item.MaPhieuThu, xml);
                            TempData["Info"] = "Tạo mới thành công";
                            if (submit.Equals("Lưu"))
                                return Redirect("/SoThu/ThuHo/" + type);
                            else
                                return Redirect("/SoThu/PhieuThuHo?type=" + type);
                        }
                        else
                        {
                            TempData["Error"] = "Lỗi tạo phiếu:" + message;
                        }
                    }
                    else
                    {
                        TempData["Error"] = "Lỗi tạo phiếu:" + message;
                    }
                }
                else
                {
                    string sessionId = "";
                    string message = "";
                    //kiem tra coc
                    message = _phieuThuService.KiemTraCocTruocKhiUpdatePhieuThu(coc, "");
                    if (string.IsNullOrEmpty(message))
                    {
                        message = _phieuThuService.UpdatePhieuThu(item, httt, ref sessionId, false);
                    if (string.IsNullOrEmpty(message))
                    {
                        string result = _phieuThuService.XuLySauKhiUpdatePhieuThu(item.MaPhieuThu, sessionId, xml);
                        if (string.IsNullOrEmpty(result))
                        {
                            TempData["Info"] = "Cập nhật thành công";
                        }
                        else
                        {
                            TempData["Info"] = result;
                        }
                    }
                    else
                    {
                        ViewBag.Error = "Cập nhật thất bại" + message;
                        TempData["Error"] = "Cập nhật thất bại" + message;
                        _logger.WriteLog("PhieuThu", message);
                    }
                    }
                    else
                    {
                        TempData["Error"] = "Lỗi tạo phiếu:" + message;
                    }
                }
                SoThuModel model = GetModelCreate();
                model.Item = item;
                model.CTPT = httt;
            }
            catch (Exception ex)
            {
                ViewBag.Error = ex.ToString();
                _logger.WriteLog("PhieuThuHo:" + ex.ToString());
                TempData["Error"] = ex.ToString();
            }

            return Redirect("/SoThu/ThuHo/" + type);
        }

        #endregion

        public void ExportExcel(string type, DateTime from, DateTime to, string query = "")
        {
            var grid = new GridView();
            int total = 0;
            string name = "";
            string fname = "";
            switch (type)
            {
                case "TCOBX":
                    grid.DataSource = _phieuThuService.GetTCOBX(from, to, query, 1, ref total, 65000);
                    name = "Báo cáo thu cọc bán xe";
                    fname = "thucocbanxe_" + DateTime.Now.ToString(DateFormat);
                    break;
                case "TCODV":
                    grid.DataSource = _phieuThuService.GetTCODV(from, to, query, 1, ref total, 65000);
                    name = "Báo cáo thu cọc phụ tùng - dịch vụ";
                    fname = "thucocphutungdichvu_" + DateTime.Now.ToString(DateFormat);
                    break;
                case "TPHKI":
                    grid.DataSource = _phieuThuService.GetTPHKI(from, to, query, 1, ref total, 65000);
                    name = "Báo cáo thu phụ kiện";
                    fname = "thuphukien_" + DateTime.Now.ToString(DateFormat);
                    break;
                case "TBAHI":
                    grid.DataSource = _phieuThuService.GetTBAHI(from, to, query, 1, ref total, 65000);
                    name = "Báo cáo thu bảo hiểm";
                    fname = "thubaohiem_" + DateTime.Now.ToString(DateFormat);
                    break;
                case "THHHB":
                    grid.DataSource = _phieuThuService.GetTHHHB(from, to, query, 1, ref total, 65000);
                    name = "Báo cáo thu hoa hồng Holdback";
                    fname = "thuhoahongholdback_" + DateTime.Now.ToString(DateFormat);
                    break;
                case "TVAMU":
                    grid.DataSource = _phieuThuService.GetTVAMU(from, to, query, 1, ref total, 65000);
                    name = "Báo cáo thu vay mượn";
                    fname = "thuvaymuon_" + DateTime.Now.ToString(DateFormat);
                    break;
                case "TLADT":
                    grid.DataSource = _phieuThuService.GetTLADT(from, to, query, 1, ref total, 65000);
                    name = "Báo cáo thu lãi đầu tư";
                    fname = "thulaidautu_" + DateTime.Now.ToString(DateFormat);
                    break;
                case "TKHAC":
                    grid.DataSource = _phieuThuService.GetTKHAC(from, to, query, 1, ref total, 65000);
                    name = "Báo cáo thu khác";
                    fname = "thukhac_" + DateTime.Now.ToString(DateFormat);
                    break;
            }
            grid.DataBind();
            Response.ClearContent();
            Response.Buffer = true;
            Response.AddHeader("content-disposition", "attachment; filename=" + fname + ".xls");
            Response.ContentType = "application/ms-excel";
            Response.ContentEncoding = System.Text.Encoding.Unicode;
            Response.BinaryWrite(System.Text.Encoding.Unicode.GetPreamble());
            StringWriter sw = new StringWriter();
            HtmlTextWriter htw = new HtmlTextWriter(sw);
            grid.RenderControl(htw);
            Response.Output.Write(sw.ToString());
            Response.Flush();
            Response.End();
        }
        public void SetSearch1(ref string from, ref string to, ref DateTime f, ref DateTime t, ref int p, ref string query, string type, ref string tinhtrang, int pageSize = 30)
        {

            var cookie = Request.Cookies.Get(type);
            try
            {
                if (from == "" && to == "" && query == "" && tinhtrang == "")
                {
                    if (cookie == null)
                    {
                        from = DateTime.Now.ToString(DateFormat);
                        to = DateTime.Now.ToString(DateFormat);
                        cookie = new HttpCookie(type);
                        cookie.Expires = DateTime.Now.AddDays(1);
                        cookie.Domain = FormsAuthentication.CookieDomain;
                        cookie.Secure = FormsAuthentication.RequireSSL;
                        cookie.Path = FormsAuthentication.FormsCookiePath;
                        cookie.Values["from"] = from;
                        cookie.Values["to"] = to;
                        cookie.Values["query"] = query;
                        cookie.Values["tinhTrang"] = query;
                        _httpContext.Response.Cookies.Set(cookie);
                    }
                    else
                    {
                        from = cookie.Values["from"];
                        to = cookie.Values["to"];
                        query = cookie.Values["query"];
                        tinhtrang = cookie.Values["tinhtrang"];
                    }
                    f = Convert.ToDateTime(from + " 00:00:00");
                    t = Convert.ToDateTime(to + " 23:59:59");
                }
                else if (from != "" && to != "")
                {
                    if (cookie == null)
                    {
                        f = Convert.ToDateTime(from + " 00:00:00");
                        t = Convert.ToDateTime(to + " 23:59:59");
                        cookie = new HttpCookie(type);
                        cookie.Expires = DateTime.Now.AddDays(1);
                        cookie.Domain = FormsAuthentication.CookieDomain;
                        cookie.Secure = FormsAuthentication.RequireSSL;
                        cookie.Path = FormsAuthentication.FormsCookiePath;
                    }
                    cookie.Values["from"] = from;
                    cookie.Values["to"] = to;
                    cookie.Values["query"] = query;
                    cookie.Values["tinhtrang"] = tinhtrang;


                    f = Convert.ToDateTime(from + " 00:00:00");
                    t = Convert.ToDateTime(to + " 23:59:59");
                    _httpContext.Response.Cookies.Set(cookie);
                }
            }
            catch (Exception ex)
            {

            }
            ViewBag.PageIndex = p;
            ViewBag.PageSize = pageSize;
            ViewBag.Warning = TempData["Warning"];
            ViewBag.Alert = TempData["Alert"];
            ViewBag.Info = TempData["Info"];
            ViewBag.Error = TempData["Error"];
            ViewBag.From = from;
            ViewBag.To = to;
            ViewBag.Query = query;
            ViewBag.Url = Request.Url.AbsolutePath + "?query=" + query + "&from=" + from + "&to=" + to + "&tinhtrang=" + tinhtrang + "&p=";
        }
