        public ActionResult DVEdit(string id, string a = "")
        {
            try
            {
                ViewBag.Title = "Thu dịch vụ";
                ViewBag.Alert = TempData["Alert"];
                DichVuEditModel model = new DichVuEditModel();
                model.obj = _phieuThuService.GetPhieuThu(id);
                model.CTPDV = _soThuService.GetCTPDV(id);
                model.DoiTac = _soThuService.GetDoiTac("NCC");

                double tongGiaBan = 0;
                double tongGiamGia = 0;
                double tongThucThu = 0;


                double tongGiaBanVAT = 0;
                double tongGiamGiaVAT = 0;
                double tongThucThuVAT = 0;

                double tongGiaBanSauVAT = 0;
                double tongGiamGiaSauVAT = 0;
                double tongThucThuSauVAT = 0;


                foreach (var i in model.CTPDV)
                {
                    var vat = i.VAT;
                    //tongGiaBan += i.COST;
                    //tongGiamGia += (double)i.DISCOUNT;

                    tongGiaBanVAT += vat * Math.Truncate(i.COST);
                    tongGiamGiaVAT += vat * Math.Truncate((double)i.DISCOUNT);

                    tongGiaBan += Math.Truncate(i.COST);
                    tongGiamGia += Math.Truncate((double)i.DISCOUNT);
                }

                tongThucThu = tongGiaBan - tongGiamGia;
                tongThucThuVAT = tongGiaBanVAT - tongGiamGiaVAT;


                tongGiaBanSauVAT = tongGiaBan + tongGiaBanVAT;
                tongGiamGiaSauVAT = tongGiamGia + tongGiamGiaVAT;
                tongThucThuSauVAT = tongThucThu + tongThucThuVAT;

                ViewBag.TongGiaBan = Math.Round(tongGiaBan);
                ViewBag.TongGiamGia = Math.Round(tongGiamGia);
                ViewBag.TongThucThu = Math.Round(tongThucThu);

                ViewBag.TongGiaBanVAT = Math.Round(tongGiaBanVAT);
                ViewBag.TongGiamGiaVAT = Math.Round(tongGiamGiaVAT);
                ViewBag.TongThucThuVAT = Math.Round(tongThucThuVAT);

                ViewBag.TongGiaBanSauVAT = Math.Round(tongGiaBanSauVAT);
                ViewBag.TongGiamGiaSauVAT = Math.Round(tongGiamGiaSauVAT);
                ViewBag.TongThucThuSauVAT = Math.Round(tongThucThuSauVAT);

                model.noPhaiThu = _noPhaiThuService.GetNoPhaiThu(id, "NDIVU");
                model.CTPT = _phieuThuService.GetCTPT(id);
                model.noPhaiTra = _noPhaiTraService.GetNoPhaiTra(id, "HHTXE");
                model.noBaoHiem = _noPhaiThuService.GetNoPhaiThu(id, "NBHDV");
                model.noGCN = _noPhaiTraService.GetNoPhaiTra(id, "NGCNG");
                
                model.CTBH = _soThuService.GetDoiTac("BH");
                model.HTTT = _soThuService.GetHTTT();
                model.Users = _userService.get();
                model.Coc = _phieuThuService.GetTCODVByBienSo(model.obj.BienSo, false, model.obj.MaPhieuThu);
                model.NBDTK = _phieuThuService.GetNBDTK(model.obj.BienSo, model.obj.SoKhung, false, model.obj.MaPhieuThu);
                ViewBag.action = a;
                return View(model);
            }
            catch (Exception ex)
            {
                _logger.WriteLog("SoThuController:DVEdit" + ex.ToString());
                TempData["Error"] = ex;
            }
            return View();
        }
        [HttpPost]
        public ActionResult DVEdit(
            List<ChiTietPhieuDichVu> ptdv
            , NoPhaiTra noPhaiTra //no phai tra hoa hong ban xe
            , List<ChiTietPhieuThu> coc
            , NoPhaiThu NPT //no phai thu dich vu khach le
            , NoPhaiThu NoBHTT
            , NoPhaiTra NoHHTX
            , NoPhaiTra NoGCN
            , ChiTietPhieuThu ctbh
            , PhieuThu obj
            , List<ChiTietPhieuThu> httt)
        {
            try
            {
                if (CurrentUser.ReadOnly == true)
                {
                    return Redirect("/Home/NoAccess");
                }
                string xml = "<Action>DVEdit</Action>";
                if (obj != null)
                {
                    obj.NgayThu = obj.NgayHachToan;
                    xml += TNK.Core.Common.ConvertObjectToXMLString(obj);
                }
                if (httt != null)
                {
                    xml += Environment.NewLine + "<ThanhToan>";
                    foreach (ChiTietPhieuThu ct in httt)
                        xml += TNK.Core.Common.ConvertObjectToXMLString(ct);
                    xml += Environment.NewLine + "</ThanhToan>";
                }
                if (coc != null)
                {
                    xml += Environment.NewLine + "<Coc>";
                    foreach (ChiTietPhieuThu ct in coc)
                        xml += TNK.Core.Common.ConvertObjectToXMLString(ct);
                    xml += Environment.NewLine + "</Coc>";
                }
                if (ptdv != null)
                {
                    xml += Environment.NewLine + "<ChiTietPhieuDichVu>";
                    foreach (ChiTietPhieuDichVu ct in ptdv)
                        xml += TNK.Core.Common.ConvertObjectToXMLString(ct);
                    xml += Environment.NewLine + "</ChiTietPhieuDichVu>";
                }
                if (ctbh != null)
                    xml += TNK.Core.Common.ConvertObjectToXMLString(ctbh);
                if (NPT != null)
                    xml += TNK.Core.Common.ConvertObjectToXMLString(NPT);
                if (NoBHTT != null)
                    xml += TNK.Core.Common.ConvertObjectToXMLString(NoBHTT);
                if (NoGCN != null)
                    xml += TNK.Core.Common.ConvertObjectToXMLString(NoGCN);
                if (NoHHTX != null)
                    xml += TNK.Core.Common.ConvertObjectToXMLString(NoHHTX);
                xml = "<formdata>" + Environment.NewLine + xml + Environment.NewLine + "</formdata>";

                string message = "";
                double tongTien = 0;
                double thanhToan = 0;
                obj.NguoiBaoLanh = NPT.NguoiBaoLanh;

                message = _phieuThuService.KiemTraRangBuocTruocKhiUpdatePhieuThuDichVu(obj, NPT, NoBHTT, coc, NoHHTX, NoGCN);
                if (string.IsNullOrEmpty(message))
                {
                    //tongTien = obj.TongCong;
                    //foreach (ChiTietPhieuDichVu objPt in ptdv)
                    //{
                    //    tongTien += objPt.COST - objPt.DISCOUNT;
                    //}
                    //obj.TongCong = tongTien*1.1;
                    if (coc != null)
                    {
                        foreach (var item in coc)
                        {
                            ChiTietPhieuThu ctptcoc = new ChiTietPhieuThu();
                            ctptcoc.Id = item.Id;
                            ctptcoc.HinhThucThanhToan = "DC";
                            ctptcoc.MaNganHang = "COCDV";
                            ctptcoc.MaPhieuThu = obj.MaPhieuThu;
                            ctptcoc.SoTienThanhToan = item.SoTienThanhToan;
                            ctptcoc.SoThamChieu = item.SoThamChieu;
                            ctptcoc.Temp = "COCDV-DC";
                            //_phieuThuService.InsertCTPT(ctptcoc);
                            httt.Add(ctptcoc);
                        }
                    }

                    if (ctbh != null)
                    {
                        ctbh.HinhThucThanhToan = "BH";
                        ctbh.MaPhieuThu = obj.MaPhieuThu;
                        ctbh.Temp = ctbh.MaNganHang + "-BH";
                        httt.Add(ctbh);
                    }
                    string sessionId = "";
                    message = _phieuThuService.UpdatePhieuThu(obj, httt, ref sessionId, false, xml);

                    //neu cap nhat phieu thu thành công thì cập nhật tiếp thanh toán bảo hiểm , nợ phải thu khách lẻ, chi tiết phiếu dịch vụ
                    if (string.IsNullOrEmpty(message))
                    {
                        //tinh toan lai so tien no

                        thanhToan = 0;
                        for (int i = 0; i < httt.Count; i++)
                            thanhToan += httt[i].SoTienThanhToan;
                        //if (coc != null)
                        //{
                        //    for (int i = 0; i < coc.Count; i++)
                        //        thanhToan += coc[i].SoTienThanhToan;
                        //}
                        //if (ctbh != null)
                        //    thanhToan += ctbh.SoTienThanhToan;
                        // noPhaiTra.SoTienNo = tongTien - thanhToan;
                        // noPhaiTra.SoTienDaTra = 0;
                        // noPhaiTra.SoTienConLai = noPhaiTra.SoTienNo;

                        //cap nhat chi tiet phieu dich vu (khong can vi chi load 1 lan tu database cua TNK
                        _soThuService.UpdateChiTietPhieuDichVu(ptdv);
                        // _noPhaiTraService.UpdateNoPhaiTra(noPhaiTra);
                        //  _phieuThuService.UpdateCTPT(coc);

                        //cap nhat bao hiem thanh toan
                        //_phieuThuService.UpdateCTPT(ctbh);
                        //cap nhat no phai thu khach le  --> chuyển xuống database xử lý
                        //NPT.SoTienNo = obj.TongCong - thanhToan;
                        //NPT.SoTienNo = obj.TongCong - thanhToan;
                        //_noPhaiThuService.UpdateNoPhaiThu(NPT);
                        //xu ly sai khi update phieu thu
                        string result = _phieuThuService.XuLySauKhiUpdatePhieuThu(obj.MaPhieuThu, sessionId, xml);
                        if (string.IsNullOrEmpty(result))
                        {
                            TempData["Info"] = "Cập nhật thành công";
                        }
                        else
                        {
                            TempData["Info"] = result;
                        }
                    }
                    //neu cap nhat phieu thu khong thành công thì chỉ cập nhật hoa hồng tài xế + chi tiết phiếu dịch vụ (GCN)
                    else
                    {
                        string msgOther = "";
                        //cap nhat so tien GCN của chi tiết dịch vụ
                        if (!message.Contains("NGCNG"))
                        {
                            _soThuService.UpdateChiTietPhieuDichVu(ptdv);
                            msgOther = " gia công ngoài";
                        }
                        if (!message.Contains("HHTX"))
                        {
                            _phieuThuService.UpdatePhieuDichVuChoHoaHongTaiXe(obj.MaPhieuThu, obj.NguoiDuyetHHTX, obj.HoaHongTaiXe);
                            if (msgOther != "")
                                msgOther += ",";
                            msgOther += " hoa hồng tài xế";
                        }
                        //cap nhat bao hiem thanh toan
                        if (!message.Contains("NBHDV") && !message.Contains("NDIVU"))
                        {
                            _phieuThuService.UpdateCTPT(ctbh, obj);
                            if (msgOther != "")
                                msgOther += ",";
                            msgOther += " bảo hiểm thanh toán";
                        }
                        if (msgOther != "")
                            msgOther = "Chỉ cập nhập được:" + msgOther + ".";
                        string result = _phieuThuService.XuLySauKhiUpdatePhieuThu(obj.MaPhieuThu, sessionId, xml);
                        if (string.IsNullOrEmpty(result))
                        {
                            TempData["Info"] = "Cập nhật thành công";
                        }
                        else
                        {
                            TempData["Warning"] = result;
                        }
                        TempData["Warning"] = msgOther + "Một số thông tin không được phép cập nhật do: " + message;
                    }
                }
                else
                {
                    TempData["Warning"] = "Không được phép cập nhật phiếu do: " + message;
                    ViewBag.Warning = "Không được phép cập nhật phiếu do: " + message;
                }
            }
            catch (Exception ex)
            {
                TempData["Error"] = "Lỗi cập nhật phiếu:" + ex;
                ViewBag.Error = "Lỗi cập nhật phiếu:" + ex;
            }
            //return Redirect("/SoThu/DVEdit/" + obj.MaPhieuThu);
            return Redirect("/SoThu/DVIndex?tab=2");
        }

