                    tongGiamGiaSauVAT += Math.Truncate((double)i.DISCOUNT) * i.VAT;
                    tongGiamGiaVAT_New += Math.Truncate((double)i.DISCOUNT) * i.VAT;
                }

                tongThucThu = tongGiaBan - tongGiamGia;
                tongThucThuVAT = tongGiaBanVAT - tongGiamGiaSauVAT;

