                //tongGiamGiaSauVAT = tongGiamGia * 1.1;
                //tongThucThuSauVAT = tongThucThu * 1.1;
                //cũ
                //tongGiamGiaVAT = tongGiamGia * 0.1;

                ViewBag.TongGiaBan = Math.Round(tongGiaBan);
                ViewBag.TongGiamGia = Math.Round(tongGiamGia);
                ViewBag.TongThucThu = Math.Round(tongThucThu);

                ViewBag.TongGiaBanVAT = Math.Round(tongGiaBanVAT);
                ViewBag.TongGiamGiaVAT = Math.Round(tongGiamGiaVAT_New);
                ViewBag.TongThucThuVAT = Math.Round(tongThucThuVAT);

                ViewBag.TongGiaBanSauVAT = Math.Round(tongGiaBanSauVAT);
                ViewBag.TongGiamGiaSauVAT = Math.Round(tongGiamGiaSauVAT);
                ViewBag.TongThucThuSauVAT = Math.Round(tongThucThuSauVAT);

                model.noPhaiThu = _noPhaiThuService.GetNoPhaiThu(id, "NDIVU");
                model.CTPT = _phieuThuService.GetCTPT(id);
                model.noPhaiTra = _noPhaiTraService.GetNoPhaiTra(id, "HHTXE");
                model.noBaoHiem = _noPhaiThuService.GetNoPhaiThu(id, "NBHDV");
                model.noGCN = _noPhaiTraService.GetNoPhaiTra(id, "NGCNG");
                model.CTBH = _soThuService.GetDoiTac("BH");
                model.HTTT = _soThuService.GetHTTT();
                model.Users = _userService.get();
                model.Coc = _phieuThuService.GetTCODVByBienSo(model.obj.BienSo, false, model.obj.MaPhieuThu);
                model.NBDTK = _phieuThuService.GetNBDTK(model.obj.BienSo, model.obj.SoKhung, false, model.obj.MaPhieuThu);
                ViewBag.action = a;
                //lấy số tiền công nợ Honda
                PhieuThu pt = _phieuThuService.CongNoHonDa(id);
                if (pt != null)
                    ViewBag.CongNoHonDa = pt.TongCong;
                else
                    ViewBag.CongNoHonDa = 0;
                if (model.noPhaiThu == null)
                    ViewBag.SoTienNo = model.obj.TongCong;
                return View(model);
            }
            catch (Exception ex)
            {
                _logger.WriteLog("SoThuController:DVEdit" + ex.ToString());
                TempData["Error"] = ex;
            }
            return View();
        }
