                        //    httt.Add(ctptcoc);
                        //}
                        var Maphieuthu = bdtk.Where(x => x.SoTienSuDung > 0).Select(y => y.MaPhieuThu).Distinct().ToList();
                        foreach (var item in Maphieuthu)
                        {
                            var npt = _noPhaiTraService.getNoPhaiTra(item);
                            //Tính tổng STSD
                            var tong = bdtk.Where(x => x.MaPhieuThu == item).Select(x => x.SoTienSuDung).Sum();
                            //var nbd = bdtk.SingleOrDefault(x => x.MaPhieuThu == item);
                            ChiTietPhieuThu ctptcoc = new ChiTietPhieuThu();
                            ctptcoc.HinhThucThanhToan = "DC";
                            ctptcoc.MaNganHang = "NBDTK";
                            ctptcoc.MaPhieuThu = obj.MaPhieuThu;
                            ctptcoc.SoTienThanhToan = tong;
                            ctptcoc.SoThamChieu = npt.MaPhieuNo;
                            ctptcoc.Temp = "NBDTK-DC";
                            //_phieuThuService.InsertCTPT(ctptcoc);
                            httt.Add(ctptcoc);
                        }
                    }

                    if (ctbh != null)
                    {
                        ctbh.HinhThucThanhToan = "BH";
                        ctbh.MaPhieuThu = obj.MaPhieuThu;
                        ctbh.Temp = ctbh.MaNganHang + "-BH";
                        httt.Add(ctbh);
                    }
                    if (lhtt != null)
                    {
                        lhtt = lhtt.Where(s => s.MaNganHang != null).ToList();
                        foreach (var item in lhtt)
                        {
                            ChiTietPhieuThu ctptcoc = new ChiTietPhieuThu();
                            ctptcoc.Id = item.Id;
                            ctptcoc.HinhThucThanhToan = "HA";
                            ctptcoc.MaNganHang = item.MaNganHang;
                            ctptcoc.MaPhieuThu = obj.MaPhieuThu;
                            ctptcoc.SoTienThanhToan = item.SoTienThanhToan;
                            ctptcoc.SoThamChieu = item.SoThamChieu;
                            ctptcoc.Temp = item.MaNganHang + "-HA";
                            ctptcoc.IsDeleted = item.IsDeleted;
                            //_phieuThuService.InsertCTPT(ctptcoc);
                            httt.Add(ctptcoc);
                        }
                    }
                    string sessionId = "";
                    obj.NguoiBaoLanh = NPT.NguoiBaoLanh;
                    message = _phieuThuService.UpdatePhieuThu(obj, httt, ref sessionId, false, xml);
                    if (bdtk != null)
                        _phieuThuService.UpdateBDTK(bdtk, obj.MaPhieuThu);
                    //neu cap nhat phieu thu thành công thì cập nhật tiếp thanh toán bảo hiểm , nợ phải thu khách lẻ, chi tiết phiếu dịch vụ
                    if (string.IsNullOrEmpty(message))
                    {
                        //tinh toan lai so tien no

                        thanhToan = 0;
                        for (int i = 0; i < httt.Count; i++)
                            thanhToan += httt[i].SoTienThanhToan;

                        _soThuService.UpdateChiTietPhieuDichVu_v1(ptdv, obj.MaPhieuThu);

                        string result = _phieuThuService.XuLySauKhiUpdatePhieuThu(obj.MaPhieuThu, sessionId, xml);
                        if (string.IsNullOrEmpty(result))
                        {
                            TempData["Info"] = "Cập nhật thành công";
                        }
                        else
                        {
                            TempData["Info"] = result;
                        }
                    }
                    //neu cap nhat phieu thu khong thành công thì chỉ cập nhật hoa hồng tài xế + chi tiết phiếu dịch vụ (GCN)
                    else
                    {
                        string msgOther = "";
                        //cap nhat so tien GCN của chi tiết dịch vụ
                        if (!message.Contains("NGCNG"))
                        {
                            _soThuService.UpdateChiTietPhieuDichVu_v1(ptdv, obj.MaPhieuThu);
                            msgOther = " gia công ngoài";
                        }
                        if (!message.Contains("HHTX"))
                        {
                            _phieuThuService.UpdatePhieuDichVuChoHoaHongTaiXe(obj.MaPhieuThu, obj.NguoiDuyetHHTX, obj.HoaHongTaiXe);
                            if (msgOther != "")
                                msgOther += ",";
                            msgOther += " hoa hồng tài xế";
                        }
                        //cap nhat bao hiem thanh toan
                        if (!message.Contains("NBHDV") && !message.Contains("NDIVU"))
                        {
                            _phieuThuService.UpdateCTPT(ctbh, obj);
                            if (msgOther != "")
                                msgOther += ",";
                            msgOther += " bảo hiểm thanh toán";
                        }
                        if (msgOther != "")
                            msgOther = "Chỉ cập nhập được:" + msgOther + ".";
                        string result = _phieuThuService.XuLySauKhiUpdatePhieuThu(obj.MaPhieuThu, sessionId, xml);
                        if (string.IsNullOrEmpty(result))
                        {
                            TempData["Info"] = "Cập nhật thành công";
                        }
                        else
                        {
                            TempData["Info"] = result;
                        }
                        TempData["Warning"] = msgOther + "Một số thông tin không được phép cập nhật do: " + message;
                    }
                }
                else
                {
                    TempData["Warning"] = "Không được phép cập nhật phiếu do: " + message;
                    ViewBag.Warning = "Không được phép cập nhật phiếu do: " + message;
                }
            }
            catch (Exception ex)
            {
                TempData["Error"] = "Lỗi cập nhật phiếu:" + ex;
                ViewBag.Error = "Lỗi cập nhật phiếu:" + ex;
            }
            return Redirect("/SoThu/DVIndex?tab=2");
        }
        public ActionResult DVCreate(string id)
        {
            try
            {
                ViewBag.Title = "Thu dịch vụ";
                double tongGiaBan = 0;
                double tongGiamGia = 0;
                double tongThucThu = 0;

                double tongGiaBanVAT = 0;
                double tongGiamGiaVAT = 0;
                double tongThucThuVAT = 0;

                double tongGiaBanSauVAT = 0;
                double tongGiamGiaSauVAT = 0;
                double tongThucThuSauVAT = 0;

                DichVuModel model = new DichVuModel();
                model.lst = _phieuThuService.GetPDVT(id);
                model.DoiTac = _soThuService.GetDoiTac("NCC");
                model.obj = new PhieuThu();
                if (model.lst == null || model.lst.Count == 0)
                {

                }
                else
                {

                    model.obj.SoHopDong = model.lst[0].REPAIRORDERNO;
                    if (!string.IsNullOrEmpty(model.lst[0].REGISTERNO))
                    {
                        model.obj.BienSo = model.lst[0].REGISTERNO.Replace(".", "").Replace(" ", "");
                    }
                    model.obj.SoKhung = model.lst[0].FRAMENO;
                    model.obj.HoTen = model.lst[0].CAROWNERNAME;
                    model.obj.MaXe = model.lst[0].CF_TYPE;
                    model.obj.DienThoai = model.lst[0].CAROWNERTEL;
                    model.obj.NgayQuyetToan = (DateTime)model.lst[0].RO_DATE;
                    model.obj.TenXe = model.lst[0].CM_NAME;

                    foreach (var i in model.lst)
                    {
                        // i.COST = i.COST;
                        // i.DISCOUNT = i.DISCOUNT;
                        var vat = i.TAX_AMOUNT5 > 0 ? 0.05 : 0.1;
                        tongGiaBan += i.COST;
                        tongGiamGia += (double)i.DISCOUNT;

                        tongGiaBanVAT += vat * i.COST;
                        tongGiamGiaVAT += vat * (double)i.DISCOUNT;

                        model.obj.SoTienThu += ((double)i.COST - (double)i.DISCOUNT);
                        model.obj.TongCong += ((double)i.COST - (double)i.DISCOUNT);

                    }

                    tongThucThu = tongGiaBan - tongGiamGia;
                    model.obj.SoTienThu = Math.Round(model.obj.SoTienThu * 1.1);//10% VAT
                    model.obj.TongCong = Math.Round(model.obj.TongCong * 1.1);//10%VAT
                    if (model.obj.BienSo != "")
                    {
                        model.Cocs = _phieuThuService.GetTCODVByBienSo(model.obj.BienSo, true);
                    }
                    if (model.obj.BienSo != "" || model.obj.SoKhung != "")
                    {
                        model.NBDTK = _phieuThuService.GetNBDTK(model.obj.BienSo, model.obj.SoKhung, true);
                    }

                }


                // tongGiaBanVAT = tongGiaBan * 0.1;
                // tongGiamGiaVAT = tongGiamGia * 0.1;
                tongThucThuVAT = tongGiaBanVAT - tongGiamGiaVAT;


                tongGiaBanSauVAT = tongGiaBan + tongGiaBanVAT;
                tongGiamGiaSauVAT = tongGiamGia + tongGiamGiaVAT;
                tongThucThuSauVAT = tongThucThu + tongThucThuVAT;

                ViewBag.TongGiaBan = Math.Round(tongGiaBan);
                ViewBag.TongGiamGia = Math.Round(tongGiamGia);
                ViewBag.TongThucThu = Math.Round(tongThucThu);

                ViewBag.TongGiaBanVAT = Math.Round(tongGiaBanVAT);
                ViewBag.TongGiamGiaVAT = Math.Round(tongGiamGiaVAT);
                ViewBag.TongThucThuVAT = Math.Round(tongThucThuVAT);

                ViewBag.TongGiaBanSauVAT = Math.Round(tongGiaBanSauVAT);
                ViewBag.TongGiamGiaSauVAT = Math.Round(tongGiamGiaSauVAT);
                ViewBag.TongThucThuSauVAT = Math.Round(tongThucThuSauVAT);

                model.CTPT = new List<ChiTietPhieuThu>();
                model.CTPT.Add(new ChiTietPhieuThu());
                model.Users = _userService.get();
                model.HTTT = _soThuService.GetHTTT();
                model.CTBH = _soThuService.GetDoiTac("BH");
                return View(model);
            }
            catch (Exception ex)
            {
                _logger.WriteLog("SoThuController:DVCreate" + ex.ToString());
                TempData["Error"] = ex;
            }
            return View();

        }
        [HttpPost]
        public ActionResult DVCreate(string id, NoPhaiThu NPT,
            List<ChiTietPhieuDichVu> ptdv,
            List<string> GCN, PhieuThu obj,
            ChiTietPhieuThu ctbh,
            List<ChiTietPhieuThu> httt,
            NoPhaiTra noPhaiTra,
            List<ChiTietPhieuThu> coc,
            string submitType)
        {
            try
            {
                if (CurrentUser.ReadOnly == true)
                {
                    return Redirect("/Home/NoAccess");
                }
                obj.MaLoaiPhieu = "TDIVU";
                obj.NgayThu = obj.NgayHachToan;
                //tinh so tien tong cong doanh thu tu phieu dich vu
                //foreach (var item in ptdv)
                // {
                //     obj.TongCong = (obj.TongCong + item.COST - item.DISCOUNT);
                // }
                // obj.TongCong = Math.Round(obj.TongCong * 1.1);
                string xml = "<Action>DVCreate</Action>";
                if (obj != null)
                    xml += TNK.Core.Common.ConvertObjectToXMLString(obj);
                if (httt != null)
                {
                    xml += Environment.NewLine + "<ThanhToan>";
                    foreach (ChiTietPhieuThu ct in httt)
                        xml += TNK.Core.Common.ConvertObjectToXMLString(ct);
                    xml += Environment.NewLine + "</ThanhToan>";
                }
                if (coc != null)
                {
                    xml += Environment.NewLine + "<Coc>";
                    foreach (ChiTietPhieuThu ct in coc)
                        xml += TNK.Core.Common.ConvertObjectToXMLString(ct);
                    xml += Environment.NewLine + "</Coc>";
                }
                if (ptdv != null)
                {
                    xml += Environment.NewLine + "<ChiTietPhieuDichVu>";
                    foreach (ChiTietPhieuDichVu ct in ptdv)
                        xml += TNK.Core.Common.ConvertObjectToXMLString(ct);
                    xml += Environment.NewLine + "</ChiTietPhieuDichVu>";
                }
                if (ctbh != null)
                    xml += TNK.Core.Common.ConvertObjectToXMLString(ctbh);
                if (NPT != null)
                    xml += TNK.Core.Common.ConvertObjectToXMLString(NPT);
                if (GCN != null)
                {
                    foreach (string ct in GCN)
                        xml += TNK.Core.Common.ConvertObjectToXMLString(ct);
                }
                if (noPhaiTra != null)
                    xml += TNK.Core.Common.ConvertObjectToXMLString(noPhaiTra);

                xml = "<formdata>" + Environment.NewLine + xml + Environment.NewLine + "</formdata>";
                if (coc != null)
                {
                    foreach (var item in coc)
                    {
                        ChiTietPhieuThu ctptcoc = new ChiTietPhieuThu();
                        ctptcoc.Id = item.Id;
                        ctptcoc.HinhThucThanhToan = "DC";
                        ctptcoc.MaNganHang = "COCDV";
                        ctptcoc.MaPhieuThu = obj.MaPhieuThu;
                        ctptcoc.SoTienThanhToan = item.SoTienThanhToan;
                        ctptcoc.SoThamChieu = item.SoThamChieu;
                        ctptcoc.Temp = "COCDV-DC";
                        //_phieuThuService.InsertCTPT(ctptcoc);
                        httt.Add(ctptcoc);
                    }
                }
                if (ctbh != null)
                {
                    ctbh.HinhThucThanhToan = "BH";
                    ctbh.MaPhieuThu = obj.MaPhieuThu;
                    ctbh.Temp = ctbh.MaNganHang + "-BH";
                    httt.Add(ctbh);
                }
                string message = _phieuThuService.CreatePhieuThu(obj, httt, false);
                if (string.IsNullOrEmpty(message))
                {
                    //TempData["Info"] = "Tạo mới thành công";
                    _soThuService.InsertChiTietPhieuDichVu(ptdv, obj.MaPhieuThu);
                    //neu co no thi mmoi insert no phai tra HHTX
                    if (noPhaiTra.SoTienNo > 0)
                        _noPhaiTraService.InsertNoPhaiTra(noPhaiTra, obj.MaPhieuThu);
                    //xu ly sau khi insert phieu thu
                    string result = _phieuThuService.XuLySauKhiInsertPhieuThu(obj.MaPhieuThu, xml);
                    if (string.IsNullOrEmpty(result))
                    {
                        TempData["Info"] = "Tạo mới thành công";
                    }
                    else
                    {
                        TempData["Info"] = result;
                    }
                    if (submitType == "Save")
                        return Redirect("/SoThu/DVIndex");
                    else
                        return Redirect("/SoThu/DVCreate");
                }
                else
                {
                    TempData["Info"] = "Lỗi tạo phiếu::" + message;
                }
                ViewBag.Error = "Lỗi tạo phiếu";
                if (message == "Phiếu này đã tồn tại.")
                {
                    ViewBag.Error = "Phiếu này đã tồn tại.";
                }
                DichVuModel model = new DichVuModel();
                model.obj = obj;
                model.lst = _phieuThuService.GetPDVT(id);
                model.Cocs = _phieuThuService.GetTCODVByBienSo(model.obj.BienSo, true);
                model.Users = _userService.get();
                model.CTBH = _soThuService.GetDoiTac("BH");
                model.HTTT = _soThuService.GetHTTT();
                model.CTPT = httt;
                return View(model);
            }
            catch (Exception ex)
            {
                _logger.WriteLog("SoThuController:DVCreate" + ex.ToString());
                TempData["Error"] = ex;
            }
            return View();

        }
