                        {
                            ptdv.Add(ct9);
                        }
                    }
                }
                obj.TongCong = 0;
                obj.SoTienThu = 0;
                foreach (var pt in ptdv)
                {
                    if (pt.VAT >= 0)
                    {
                        pt.VAT = pt.VAT / 100;
                        if (pt.VAT == 0)
                            obj.TongCong += (pt.COST - pt.DISCOUNT);
                        else
                            obj.TongCong += (pt.COST - pt.DISCOUNT) + ((pt.COST - pt.DISCOUNT) * pt.VAT);
                    }
                }
                foreach (var thanhtoan in httt)
                {
                    obj.SoTienThu += thanhtoan.SoTienThanhToan;
                }
