                    if (string.IsNullOrEmpty(result))
                    {
                        TempData["Info"] = "Tạo mới thành công";
                    }
                    else
                    {
                        TempData["Info"] = result;
                    }
                    if (submitType == "Save")
                        return Redirect("/SoThu/DVIndex");
                    else
                        return Redirect("/SoThu/DVCreate");
                }
                else
                {
                    TempData["Error"] = "Lỗi tạo phiếu:" + message;
                    return Redirect("/SoThu/DVIndex");
                }
                ViewBag.Error = "Lỗi tạo phiếu:" + message;
                DichVuModelCyber model = new DichVuModelCyber();
                model.obj = obj;
                model.DoiTac = _soThuService.GetDoiTac("NCC");
                model.lst = _phieuThuService.GetCTPDVTCybers(id);
                model.Cocs = _phieuThuService.GetTCODVByBienSo(model.obj.BienSo, true);
                model.Users = _userService.get();
                model.CTBH = _soThuService.GetDoiTac("BH");
                model.HTTT = _soThuService.GetHTTT();
                model.CTPT = httt;
                return View(model);
                //return View();
            }
            catch (Exception ex)
            {
                _logger.WriteLog("SoThuController:DVCreate_New_v2" + ex.ToString());
                TempData["Error"] = ex;
                return Redirect("/SoThu/DVIndex");
            }
            return View();

        }
        public ActionResult DVCreate_New_v2(string id)
        {
            try
            {
                ViewBag.Title = "Thu dịch vụ mới";
                DichVuModelCyber model = new DichVuModelCyber();
                model.obj = new PhieuThu();

                model.lst = new List<CTPDVTamCyber>();

                string[] lst = {"SCC","DS","PTT", "PKDV" };
                foreach (var item in lst)
                {
                    CTPDVTamCyber cTPDVTamCyber = new CTPDVTamCyber();
                    cTPDVTamCyber.JOBTYPE = item;
                    cTPDVTamCyber.QUANTITY = 1;
                    cTPDVTamCyber.COST = 0;
                    model.lst.Add(cTPDVTamCyber);
                }

                model.CTPT = new List<ChiTietPhieuThu>();
                model.CTPT.Add(new ChiTietPhieuThu());
                ChiTietPhieuThu chiTiet_ = new ChiTietPhieuThu();
                chiTiet_.HinhThucThanhToan = "HA";
                chiTiet_.MaNganHang = string.Empty;
                chiTiet_.SoTienThanhToan = 0;
                model.CTPT.Add(chiTiet_);

                model.Users = _userService.get();
                model.HTTT = _soThuService.GetHTTT();
                model.CTBH = _soThuService.GetDoiTac("BH");
                model.DoiTac = _soThuService.GetDoiTac("NCC");
                model.LHTT = _commonService.getChuongTrinhDichVuHang();

                ViewBag.SoPhieu = id;
                ViewBag.TongGiaBan = 0;
                ViewBag.TongGiamGia = 0;
                ViewBag.TongThucThu = 0;

                ViewBag.TongGiaBanVAT = 0;
                ViewBag.TongGiamGiaVAT = 0;
                ViewBag.TongThucThuVAT = 0;

                ViewBag.TongGiaBanSauVAT = 0;
                ViewBag.TongGiamGiaSauVAT = 0;
                ViewBag.TongThucThuSauVAT = 0;
                return View(model);
            }
            catch (Exception ex)
            {
                _logger.WriteLog("SoThuController:DVCreate" + ex.ToString());
                TempData["Error"] = ex;
            }
            return View();

        }
        public ActionResult DVCreate_New_Cybers(string id)
        {
            try
            {
                ViewBag.Title = "Thu dịch vụ mới";
                double tongGiaBan = 0;
                double tongGiamGia = 0;
                double tongThucThu = 0;

                double tongGiaBanVAT = 0;
                double tongGiamGiaVAT = 0;
                double tongThucThuVAT = 0;

                double tongGiaBanSauVAT = 0;
                double tongGiamGiaSauVAT = 0;
                double tongThucThuSauVAT = 0;


                DichVuModelCyber model = new DichVuModelCyber();
                model.obj = new PhieuThu();

                model.DoiTac = _soThuService.GetDoiTac("NCC");
                var phieuthu = _phieuThuService.GetPDVTCybers(id);//get phieuthu
                model.lst = _phieuThuService.GetCTPDVTCybers(id);//get chitietphieu
               
                if (model.lst == null || model.lst.Count == 0)
                {

                }
                else
                {
                  

                    foreach (var i in model.lst)
                    {
                        // i.COST = i.COST;
                        // i.DISCOUNT = i.DISCOUNT;
                        tongGiaBan += i.COST;
                        tongGiamGia += (double)i.DISCOUNT;
                        model.obj.SoTienThu += ((double)i.COST - (double)i.DISCOUNT);
                        model.obj.TongCong += ((double)i.COST - (double)i.DISCOUNT);

                    }

                    tongThucThu = tongGiaBan - tongGiamGia;
                    model.obj.SoTienThu = Math.Round(model.obj.SoTienThu * 1.1);//10% VAT
                    model.obj.TongCong = Math.Round(model.obj.TongCong * 1.1);//10%VAT
                    if (model.obj.BienSo != "")
                    {
                        model.Cocs = _phieuThuService.GetTCODVByBienSo(model.obj.BienSo, true);
                    }

                    if (model.obj.BienSo != "" || model.obj.SoKhung != "")
                    {
                        model.NBDTK = _phieuThuService.GetNBDTK(model.obj.BienSo, model.obj.SoKhung, true);
                    }
                }


                tongGiaBanVAT = tongGiaBan * 0.1;
                tongGiamGiaVAT = tongGiamGia * 0.1;
                tongThucThuVAT = tongThucThu * 0.1;


                tongGiaBanSauVAT = tongGiaBan * 1.1;
                tongGiamGiaSauVAT = tongGiamGia * 1.1;
                tongThucThuSauVAT = tongThucThu * 1.1;

                ViewBag.TongGiaBan = Math.Round(tongGiaBan);
                ViewBag.TongGiamGia = Math.Round(tongGiamGia);
                ViewBag.TongThucThu = Math.Round(tongThucThu);

                ViewBag.TongGiaBanVAT = Math.Round(tongGiaBanVAT);
                ViewBag.TongGiamGiaVAT = Math.Round(tongGiamGiaVAT);
                ViewBag.TongThucThuVAT = Math.Round(tongThucThuVAT);

                ViewBag.TongGiaBanSauVAT = Math.Round(tongGiaBanSauVAT);
                ViewBag.TongGiamGiaSauVAT = Math.Round(tongGiamGiaSauVAT);
                ViewBag.TongThucThuSauVAT = Math.Round(tongThucThuSauVAT);

                model.CTPT = new List<ChiTietPhieuThu>();
                model.CTPT.Add(new ChiTietPhieuThu());
                model.Users = _userService.get();
                model.HTTT = _soThuService.GetHTTT();
                model.CTBH = _soThuService.GetDoiTac("BH");
                ViewBag.SoPhieu = id;
                return View(model);
            }
            catch (Exception ex)
            {
                _logger.WriteLog("SoThuController:DVCreate" + ex.ToString());

                TempData["Error"] = ex;
            }
            return View();

        }
