                {
                    foreach (var ct1 in ptdv1)
                    {
                        if (ct1.JOBSNAME != null)
                        {
                            ptdv.Add(ct1);
                        }
                    }
                }
                if (ptdv2 != null)
                {
                    foreach (var ct2 in ptdv2)
                    {
                        if (ct2.JOBSNAME != null)
                        {
                            ptdv.Add(ct2);
                        }
                    }
                }
                if (ptdv3 != null)
                {
                    foreach (var ct3 in ptdv3)
                    {
