                        }
                    }
                }
                if (ptdv6 != null)
                {
                    foreach (var ct6 in ptdv6)
                    {
                        if (ct6.JOBSNAME != null)
                        {
                            ptdv.Add(ct6);
                        }
                    }
                }
                if (ptdv7 != null)
                {
                    foreach (var ct7 in ptdv7)
                    {
                        if (ct7.JOBSNAME != null)
                        {
                            ptdv.Add(ct7);
                        }
                    }
                }
                if (ptdv8 != null)
                {
                    foreach (var ct8 in ptdv8)
                    {
                        if (ct8.JOBSNAME != null)
                        {
                            ptdv.Add(ct8);
                        }
                    }
                }
                if (ptdv9 != null)
                {
                    foreach (var ct9 in ptdv9)
                    {
                        if (ct9.JOBSNAME != null)
                        {
                            ptdv.Add(ct9);
                        }
                    }
                }
                foreach (var pt in ptdv)
                {
                    if (pt.VAT >= 0)
                    {
                        pt.VAT = pt.VAT / 100;
                        if (pt.VAT == 0)
                            obj.TongCong += (pt.COST - pt.DISCOUNT);
                        else
                            obj.TongCong += (pt.COST - pt.DISCOUNT) + ((pt.COST - pt.DISCOUNT) * pt.VAT);
                    }
                }
                foreach (var thanhtoan in httt)
                {
                    obj.SoTienThu += thanhtoan.SoTienThanhToan;
                }
                obj.Flag = true;
                string message = _phieuThuService.CreatePhieuThu(obj, httt, false);

                if (string.IsNullOrEmpty(message))
                {
                    // tạo mới phiếu thu khác
                    if (CongNoHonda > 0)
                    {
                        PhieuThu pt = new PhieuThu();
                        pt.MaLoaiPhieu = "TKHAC";
                        pt.DoiTac = "HVN";
                        pt.TongCong = CongNoHonda;
                        pt.NoiDung = "BẢO HÀNH THEO QT: (" + obj.SoHopDong + "), BSX: (" + obj.BienSo + ")";
                        pt.BienSo = obj.BienSo;
                        pt.MaPhieuLienQuan = obj.MaPhieuThu;
                        pt.ThongTinKhac = obj.HoTen;
                        pt.SoChungTu = "CNHONDA";
                        pt.ConLai = CongNoHonda;
                        pt.NguoiThuTien = obj.NguoiThuTien;
                        pt.NgayThu = obj.NgayThu;
                        List<ChiTietPhieuThu> ctpt = new List<ChiTietPhieuThu>();
                        List<ChiTietBanPhuKien> ctbpk = new List<ChiTietBanPhuKien>();
                        List<ChiTietBaoDuongTietKiem> ctbdtk = new List<ChiTietBaoDuongTietKiem>();
                        PhieuThu(pt, ctpt, "", "Create", "", ctpt, ctbpk, ctbdtk, ctpt);
                    }
                    //TempData["Info"] = "Tạo mới thành công";
                    _soThuService.InsertChiTietPhieuDichVu(ptdv, obj.MaPhieuThu);
                    //neu co no thi mmoi insert no phai tra HHTX
                    if (noPhaiTra.SoTienNo > 0)
                        _noPhaiTraService.InsertNoPhaiTra(noPhaiTra, obj.MaPhieuThu);
                    //xu ly sau khi insert phieu thu
                    string result = _phieuThuService.XuLySauKhiInsertPhieuThu(obj.MaPhieuThu, xml);
                    _phieuThuService.UpdateBDTK(bdtk, obj.MaPhieuThu);

                    if (string.IsNullOrEmpty(result))
                    {
                        TempData["Info"] = "Tạo mới thành công";
                    }
                    else
                    {
                        TempData["Info"] = result;
                    }
                    if (submitType == "Save")
                        return Redirect("/SoThu/DVIndex");
                    else
                        return Redirect("/SoThu/DVCreate");
                }
                else
                {
                    TempData["Info"] = "Lỗi tạo phiếu:" + message;
                    return Redirect("/SoThu/DVIndex");
                }
                ViewBag.Error = "Lỗi tạo phiếu:" + message;
                DichVuModel model = new DichVuModel();
                model.obj = obj;
                model.lst = _phieuThuService.GetPDVT(id);
                model.Cocs = _phieuThuService.GetTCODVByBienSo(model.obj.BienSo, true);
                model.Users = _userService.get();
                model.CTBH = _soThuService.GetDoiTac("BH");
                model.HTTT = _soThuService.GetHTTT();
                model.CTPT = httt;
                return View(model);
            }
            catch (Exception ex)
            {
                _logger.WriteLog("SoThuController:DVCreate" + ex.ToString());
                TempData["Error"] = ex;
            }
            return View();

        }

