                        {
                            ChiTietPhieuThu ctptLHTT = new ChiTietPhieuThu();
                            ctptLHTT.Id = item.Id;
                            ctptLHTT.HinhThucThanhToan = "HA";
                            ctptLHTT.MaNganHang = item.MaNganHang;
                            ctptLHTT.MaPhieuThu = obj.MaPhieuThu;
                            ctptLHTT.SoTienThanhToan = item.SoTienThanhToan;
                            ctptLHTT.SoThamChieu = item.SoThamChieu;
                            ctptLHTT.Temp = item.MaNganHang + "-HA";
                            httt.Add(ctptLHTT);
                        }
                    }
                }
                List<ChiTietPhieuDichVu> ptdv = new List<ChiTietPhieuDichVu>();
                if (ptdv1 != null)
                {
                    foreach (var ct1 in ptdv1)
                    {
                        if (ct1.JOBSNAME != null && ct1.IsDeleted == false)
                        {
                            ptdv.Add(ct1);
                        }
                    }
                }
                if (ptdv2 != null)
                {
                    foreach (var ct2 in ptdv2)
                    {
                        if (ct2.JOBSNAME != null && ct2.IsDeleted == false)
                        {
                            ptdv.Add(ct2);
                        }
                    }
                }
