                        {
                            ptdv.Add(ct3);
                        }
                    }
                }
                if (ptdv4 != null)
                {
                    foreach (var ct4 in ptdv4)
                    {
                        if (ct4.JOBSNAME != null && ct4.IsDeleted == false)
                        {
                            ptdv.Add(ct4);
                        }
                    }
                }
                if (ptdv5 != null)
                {
                    foreach (var ct5 in ptdv5)
                    {
                        if (ct5.JOBSNAME != null && ct5.IsDeleted == false)
                        {
                            ptdv.Add(ct5);
                        }
                    }
                }
                if (ptdv6 != null)
                {
                    foreach (var ct6 in ptdv6)
                    {
                        if (ct6.JOBSNAME != null && ct6.IsDeleted == false)
                        {
                            ptdv.Add(ct6);
                        }
                    }
                }
                if (ptdv7 != null)
                {
                    foreach (var ct7 in ptdv7)
                    {
                        if (ct7.JOBSNAME != null && ct7.IsDeleted == false)
                        {
                            ptdv.Add(ct7);
                        }
                    }
                }
                if (ptdv8 != null)
                {
                    foreach (var ct8 in ptdv8)
                    {
                        if (ct8.JOBSNAME != null && ct8.IsDeleted == false)
                        {
                            ptdv.Add(ct8);
                        }
                    }
                }
                if (ptdv9 != null)
                {
                    foreach (var ct9 in ptdv9)
                    {
                        if (ct9.JOBSNAME != null && ct9.IsDeleted == false)
                        {
                            ptdv.Add(ct9);
                        }
                    }
                }
                obj.TongCong = 0;
                obj.SoTienThu = 0;
                foreach (var pt in ptdv)
                {
                    if (pt.VAT >= 0)
                    {
                        pt.VAT = pt.VAT / 100;
                        if (pt.VAT == 0)
                            obj.TongCong += (pt.COST - pt.DISCOUNT);
                        else
                            obj.TongCong += (pt.COST - pt.DISCOUNT) + ((pt.COST - pt.DISCOUNT) * pt.VAT);
                    }
                }
                foreach (var thanhtoan in httt)
                {
                    obj.SoTienThu += thanhtoan.SoTienThanhToan;
                }
                obj.Flag = true;
                string message = _phieuThuService.CreatePhieuThu(obj, httt, false);

                if (string.IsNullOrEmpty(message))
                {
                    // tạo mới phiếu thu khác
                    if (CongNoHonda > 0)
                    {
                        PhieuThu pt = new PhieuThu();
                        pt.MaLoaiPhieu = "TKHAC";
                        pt.DoiTac = "HVN";
                        pt.TongCong = double.Parse(CongNoHonda.ToString());
                        pt.NoiDung = "BẢO HÀNH THEO QT: (" + obj.SoHopDong + "), BSX: (" + obj.BienSo + ")";
                        pt.BienSo = obj.BienSo;
                        pt.MaPhieuLienQuan = obj.MaPhieuThu;
                        pt.ThongTinKhac = obj.HoTen;
                        pt.SoChungTu = "CNHONDA";
                        pt.ConLai = CongNoHonda;
                        pt.NguoiThuTien = obj.NguoiThuTien;
                        pt.NgayThu = obj.NgayThu;
                        List<ChiTietPhieuThu> ctpt = new List<ChiTietPhieuThu>();
                        List<ChiTietBanPhuKien> ctbpk = new List<ChiTietBanPhuKien>();
                        List<ChiTietBaoDuongTietKiem> ctbdtk = new List<ChiTietBaoDuongTietKiem>();
                        PhieuThu(pt, ctpt, "", "Create", "", ctpt, ctbpk, ctbdtk, ctpt);
                    }
                    //TempData["Info"] = "Tạo mới thành công";
                    _soThuService.InsertChiTietPhieuDichVu(ptdv, obj.MaPhieuThu);
                    //neu co no thi mmoi insert no phai tra HHTX
                    if (noPhaiTra.SoTienNo > 0)
                        _noPhaiTraService.InsertNoPhaiTra(noPhaiTra, obj.MaPhieuThu);
                    //xu ly sau khi insert phieu thu
                    string result = _phieuThuService.XuLySauKhiInsertPhieuThu(obj.MaPhieuThu, xml);
                    _phieuThuService.UpdateBDTK(bdtk, obj.MaPhieuThu);

                    if (string.IsNullOrEmpty(result))
                    {
                        TempData["Info"] = "Tạo mới thành công";
                    }
                    else
                    {
                        TempData["Info"] = result;
                    }
                    if (submitType == "Save")
                        return Redirect("/SoThu/DVIndex");
                    else
                        return Redirect("/SoThu/DVCreate");
                }
                else
                {
                    TempData["Error"] = "Lỗi tạo phiếu:" + message;
                    return Redirect("/SoThu/DVIndex");
                }
                ViewBag.Error = "Lỗi tạo phiếu:" + message;
                DichVuModelCyber model = new DichVuModelCyber();
                model.obj = obj;
                model.DoiTac = _soThuService.GetDoiTac("NCC");
                model.lst = _phieuThuService.GetCTPDVTCybers(id);
                model.Cocs = _phieuThuService.GetTCODVByBienSo(model.obj.BienSo, true);
                model.Users = _userService.get();
                model.CTBH = _soThuService.GetDoiTac("BH");
                model.HTTT = _soThuService.GetHTTT();
                model.CTPT = httt;
                return View(model);
                //return View();
            }
            catch (Exception ex)
            {
                _logger.WriteLog("SoThuController:DVCreate_Cybers_V2" + ex.ToString());
                TempData["Error"] = ex;
                return Redirect("/SoThu/DVIndex");
            }
            return View();

        }
        public ActionResult DVCreate_Cybers(string id)
        {
            DateTime start = DateTime.Now;
            id = TNK.Core.Common.DecodeHtmlUrl(id);
            try
            {
                ViewBag.Title = "Thu dịch vụ";
                double tongGiaBan = 0;
                double tongGiamGia = 0;
                double tongThucThu = 0;

                double tongGiaBanVAT = 0;
                double tongGiamGiaVAT = 0;
                double tongThucThuVAT = 0;

                double tongGiaBanSauVAT = 0;
                double tongGiamGiaSauVAT = 0;
                double tongThucThuSauVAT = 0;

                DichVuModelCyber model = new DichVuModelCyber();
                model.obj = new PhieuThu();

                model.DoiTac = _soThuService.GetDoiTac("NCC");
                var phieuthu = _phieuThuService.GetPDVTCybers(id);//get phieuthu
                model.lst = _phieuThuService.GetCTPDVTCybers(id);//get chitietphieu
                if (phieuthu != null)
                {
                    //header information
                    model.obj.SoHopDong = phieuthu.REPAIRORDERNO;
                    if (!string.IsNullOrEmpty(phieuthu.REGISTERNO))
                    {
                        model.obj.BienSo = phieuthu.REGISTERNO.Replace(".", "").Replace(" ", "");
                    }
                    model.obj.SoKhung = phieuthu.FRAMENO;
                    model.obj.HoTen = phieuthu.CAROWNERNAME;
                    model.obj.MaXe = phieuthu.CF_TYPE;
                    model.obj.DienThoai = phieuthu.CAROWNERTEL;
                    model.obj.NgayQuyetToan = (DateTime)phieuthu.RO_DATE;
                    model.obj.TenXe = phieuthu.CM_NAME;
                    model.obj.DiaChi = phieuthu.CAROWNERADD;
                    model.obj.YeuCauKH = phieuthu.REQUEST_DESC;
                    model.obj.SoHoaDon = phieuthu.INVOICE;
                    model.obj.SoChungTu = phieuthu.R_Documents;
                    model.obj.HoaHongTaiXe = phieuthu.DRIVERREMUNERATION;
                    model.obj.NguoiDuyetHHTX = phieuthu.APPROVEDREMUNERATION;
                    model.obj.NgayQuyetToan = phieuthu.NgayThu;
                    model.obj.NgayThu = phieuthu.NgayThu;
                    model.obj.NgayHachToan = phieuthu.NgayThu;

                    model.CTPT = new List<ChiTietPhieuThu>();
                    if (phieuthu.PAYMENTCUSTOMERS != null)
                    {
                        var kh_TT = phieuthu.PAYMENTCUSTOMERS.Split('{', '}').Where(s => !string.IsNullOrEmpty(s));
                        foreach (var i in kh_TT)
                        {
                            if (!string.IsNullOrEmpty(i))
                            {
                                var ct = i.Split(new char[] { ',' }, StringSplitOptions.None);
                                if (ct.Length >= 3)//xu ly truong hop Cyber tra ve khong du 3 thanh phan
                                {
                                    ChiTietPhieuThu chiTiet = new ChiTietPhieuThu();
                                    chiTiet.Temp = ct[1] + "-" + ct[0];
                                    chiTiet.SoTienThanhToan = double.Parse(ct[2]);
                                    model.CTPT.Add(chiTiet);
                                }
                            }
                        }
                    }
                    //add bao hiểm thanh toán
                    if (!string.IsNullOrEmpty(phieuthu.InsuranceCompany))
                    {
                        ChiTietPhieuThu chiTiet = new ChiTietPhieuThu();
                        chiTiet.MaNganHang = phieuthu.InsuranceCompany;
                        chiTiet.SoTienThanhToan = phieuthu.PaymentInsurance;
                        chiTiet.HinhThucThanhToan = "BH";
                        model.CTPT.Add(chiTiet);
                    }
                    model.CTPT.Add(new ChiTietPhieuThu());
                    //if (model.obj.BienSo != "")
                    //{
                    //    model.Cocs = _phieuThuService.GetTCODVByBienSo(model.obj.BienSo, true);
                    //    var coc = model.Cocs.Where(s => s.MaPhieuThu == phieuthu.DEPOSITDOCUMENTS).FirstOrDefault();//Cọc đã dùng
                    //    if (coc != null)
                    //        coc.SoTienDaSuDung = phieuthu.DEPOSIT;
                    //}
                    foreach (var i in model.lst)
                    {
                        tongGiaBan += i.COST;
                        tongGiamGia += (double)i.DISCOUNT;
                        model.obj.SoTienThu += ((double)i.COST - (double)i.DISCOUNT);
                        model.obj.TongCong += ((double)i.COST - (double)i.DISCOUNT);

                        tongGiaBanVAT += i.COST * i.THUE;
                        tongGiamGiaVAT += (double)i.DISCOUNT * i.THUE;
                        tongThucThuVAT += ((double)i.COST - (double)i.DISCOUNT) * i.THUE;

                        tongGiaBanSauVAT += i.COST * (1 + i.THUE);
                        tongGiamGiaSauVAT += (double)i.DISCOUNT * (1 + i.THUE);
                        tongThucThuSauVAT += ((double)i.COST - (double)i.DISCOUNT) * (1 + i.THUE);
                    }
                    model.obj.SoTienThu = tongThucThuSauVAT;
                    model.obj.TongCong = tongThucThuSauVAT;
                    model.NBDTK = _phieuThuService.GetNBDTK(model.obj.BienSo, model.obj.SoKhung, false, model.obj.MaPhieuThu);
                }
                //tongGiaBanVAT = tongGiaBan * 0.1;
                //tongGiamGiaVAT = tongGiamGia * 0.1;
                //tongThucThuVAT = tongThucThu * 0.1;


                //tongGiaBanSauVAT = tongGiaBan * 1.1;
                //tongGiamGiaSauVAT = tongGiamGia * 1.1;
                //model.Cocs = _phieuThuService.GetTCOC_V2(model.obj.MaPhieuThu, model.obj.BienSo, model.obj.SoHopDong, model.obj.HoTen, true);

                model.Cocs = _phieuThuService.GetTCODVByBienSo(model.obj.BienSo, true).Where(x=>x.ConLai>0).ToList();


                tongThucThu = tongGiaBan - tongGiamGia;

                //tongThucThuSauVAT = tongThucThu * 1.1;
                ViewBag.TongGiaBan = Math.Round(tongGiaBan);
                ViewBag.TongGiamGia = Math.Round(tongGiamGia);
                ViewBag.TongThucThu = Math.Round(tongThucThu);

                ViewBag.TongGiaBanVAT = Math.Round(tongGiaBanVAT);
                ViewBag.TongGiamGiaVAT = Math.Round(tongGiamGiaVAT);
                ViewBag.TongThucThuVAT = Math.Round(tongThucThuVAT);

                ViewBag.TongGiaBanSauVAT = Math.Round(tongGiaBanSauVAT);
                ViewBag.TongGiamGiaSauVAT = Math.Round(tongGiamGiaSauVAT);
                ViewBag.TongThucThuSauVAT = Math.Round(tongThucThuSauVAT);

                ViewBag.SoPhieu = id;

                model.HTTT = _soThuService.GetHTTT();
                model.CTBH = _soThuService.GetDoiTac("BH");
                model.Users = _userService.get();
                return View(model);
            }
            catch (Exception ex)
            {
                DateTime end = DateTime.Now;
                _logger.WriteLog("SoThuController:DVCreate_Cybers" + ex.ToString());
                this.AddActionLog(CurrentUser.UserName,"SoThu", "DVCreate_Cybers", start, end, ex);

            }
            return View();
        }


