        public ActionResult GetInfoTicketDV(string strSoPhieu)
        {
            try
            {
                List<REPAIR_ORDER_PYS> lst = _phieuThuService.GetPDVT(strSoPhieu);
                PhieuThu ctPDIVU = _phieuThuService.GetPhieuThuTDIVUBySoDichVu(strSoPhieu);
                string msg = ctPDIVU != null ? "DVEdit/" + ctPDIVU.MaPhieuThu : "DVCreate/" + strSoPhieu;
