                    return Json(new { IsError = true, Message = "Lỗi tìm kiếm thông tin theo số phiếu." });
                return Json(new { IsError = false, Message = msg });
            }
            catch (Exception ex)
            {
                _logger.WriteLog("SoThuController:GetInfoTicketDV" + ex.ToString());
                TempData["Error"] = ex;
            }
            return View();
        }

