                        foreach (var item in KVNH)
                        {
                            if (!item.IsDeleted)
                            {
                                ChiTietPhieuThu ctptkvnh = new ChiTietPhieuThu();
                                ctptkvnh.Id = IdCTPTNganHang;//lay ID ChiTietPhieuThu lien quan den ngan hang
                                ctptkvnh.HinhThucThanhToan = "NH";
                                ctptkvnh.MaNganHang = item.DonViNo;
                                ctptkvnh.MaPhieuThu = obj.MaPhieuThu;
                                ctptkvnh.SoTienThanhToan = (double)item.SoTienNo;
                                ctptkvnh.GhiChu = item.GhiChu == null ? "" : item.GhiChu;
                                ctptkvnh.Temp = item.DonViNo + "-NH";
                                httt.Add(ctptkvnh);
                                //_phieuThuService.InsertCTPT(ctptkvnh);
                                //da chuyen xu ly xuong database
                                //_noPhaiThuService.InsertNoPhaiThu("NNHBX", obj.MaPhieuThu, "", ctptkvnh.SoTienThanhToan, item.NguoiBaoLanh, ctptkvnh.GhiChu);
                                _noPhaiThuService.UpdateNoPhaiThu(item);
                            }
                        }
                    }

                    //neu so tien da tra no bang 0 thi moi cho cap nhat cac thong tin phieu thu
                    if (NPT.SoTienDaTra == 0)
                        message = _phieuThuService.UpdatePhieuThu(obj, httt, ref sessionId, false);
                    if (string.IsNullOrEmpty(message))
                    {
                        if (NPT.SoTienDaTra == 0)
                        {
                            if (coc != null)
                            {
                                _phieuThuService.UpdateCTPT(coc, obj);
                            }
                            // dem xu ly xuong duoi database
                            //xem lai
                            //foreach (var item in KVNH)
                            //{
                            //    if (item.DonViNo != null)
                            //    {
                            //        if (item.MaPhieuNo != null)
                            //            _noPhaiThuService.UpdateNoPhaiThu(item);
                            //        else
                            //        {                              
                            //            _noPhaiThuService.InsertNoPhaiThu("NNHBX", obj.MaPhieuThu, "", item.SoTienNo, item.DonViNo, item.GhiChu!=null?item.GhiChu:"");
                            //        }
                            //    }
                            //}
                            // NPT.SoTienNo = obj.TongCong - obj.SoTienThu;
                            _noPhaiThuService.UpdateNoPhaiThu(NPT);
                        }

                    }
                    //luu thong tin luoi khuyen mai
                    //xem lai
                    //luu thong tin khuyen mai
                    foreach (var item in CTKM)
                    {
                        item.GiaVon = item.GiaBan;
                        if (item.Id != Guid.Empty)
                            _ctkmService.UpdateCTKM(item);
                        else
                        {
                            if (item.IsDeleted == false)
                            {
                                item.MaPhieuThu = obj.MaPhieuThu;
                                _ctkmService.InsertCTKM(item);
                            }
                        }
                    }
                }
                else
                {
                    //luu thong tin luoi khuyen mai
                    //xem lai
                    //luu thong tin khuyen mai
                    foreach (var item in CTKM)
                    {
                        item.GiaVon = item.GiaBan;
                        if (item.Id != Guid.Empty)
                            _ctkmService.UpdateCTKM(item);
                        else
                        {
                            if (item.IsDeleted == false)
                            {
                                item.MaPhieuThu = obj.MaPhieuThu;
                                _ctkmService.InsertCTKM(item);
                            }
                        }
                    }
                    if (!string.IsNullOrEmpty(message))
                        message = "Đã lưu thông tin khuyến mãi. Các thông tin còn lại không được phép lưu vì: " + message;

                    //xu ly sai khi update phieu thu
                    //  _phieuThuService.XuLySauKhiUpdatePhieuThu(obj.MaPhieuThu);
                }
                string result = _phieuThuService.XuLySauKhiUpdatePhieuThu(obj.MaPhieuThu, sessionId, xml);
                if (string.IsNullOrEmpty(result))
                {
                    TempData["Info"] = "Cập nhật thành công." + message;
                }
                else
                {
                    TempData["Alert"] = result + message;
                }
                //if (!string.IsNullOrEmpty(message))
                //{
                //    //TempData["Alert"] = "Đã lưu thông tin khuyến mãi. Các thông tin còn lại không được phép lưu vì: " + message;
                //    TempData["Error"] = message;
                //    ViewBag.Error = "Cập nhật thất bại:" + message;
                //}
                //if (!string.IsNullOrEmpty(message))
                //{
                //    TempData["Alert"] = "Lỗi:" +  message;
                //    ViewBag.Alert = "Cập nhật thất bại:" + message;
                //}

                //return Redirect("/Sothu/TBAXEEdit/" + obj.MaPhieuThu);
                return Redirect("/Sothu/TBAXEIndex");
            }
            catch (Exception ex)
            {
                _logger.WriteLog("SoThuController:TBAXEEdit" + ex.ToString());
                TempData["Error"] = ex;
            }
            return View();

        }

        public ActionResult TBAXEEdit(string id, string a = "")
        {
            try
            {
                ViewBag.Title = "Thu bán xe";
                BanXeModel model = new BanXeModel();
                model.ListCTPT = _phieuThuService.GetCTPT(id);
                model.obj = _phieuThuService.GetPhieuThu(id);
                model.DoiTac = _soThuService.GetDoiTac("NCC");
                if (model.obj == null)
                {
                    ViewBag.Alert = "Phiếu đã bị xóa";
                }
                else
                {
                    model.Users = _userService.get();
                    model.CTKM = _ctkmService.GetCTKM(id);
                    model.ListKMBaoHiem = _phieuThuService.GetKMBaoHiem(model.obj.SoHopDong);
                    model.ListKMPKien = _phieuThuService.GetKMPKien(model.obj.SoHopDong);

                    if (model.CTKM.Count == 0)
                        model.CTKM.Add(new ViewChiTietKhuyenMai());
                    model.NganHang = _soThuService.GetDoiTac("NH");
                    model.NKM = _ctkmService.GetNKM(false);
                    //Thang moi cap nhat chi lay no ban xe dua vao
                    model.noPhaiThu = _noPhaiThuService.GetNoPhaiThu(id).Where(x => x.LoaiPhieuNo == "NBAXE").ToList().FirstOrDefault();
                    model.CTPT = model.ListCTPT.Where(x => x.HinhThucThanhToan != "DC" && x.HinhThucThanhToan != "NH").ToList();
                    if (model.CTPT.Count == 0)
                        model.CTPT.Add(new ChiTietPhieuThu());
                    model.KVNH = _noPhaiThuService.GetNoPhaiThu(id).Where(x => x.LoaiPhieuNo == "NNHBX").ToList();
                    //lay ma phieu chi tiet phieu thu cua no ngan hang
                    List<ChiTietPhieuThu> lstCTPTNH = model.ListCTPT.Where(x => x.HinhThucThanhToan == "NH").ToList();
                    if (lstCTPTNH.Count > 0)
                    {
                        ViewBag.IdThanhToanNganHang = lstCTPTNH[0].Id;
                    }
                    else
                        ViewBag.IdThanhToanNganHang = Guid.Empty;
                    if (model.KVNH.Count == 0)
                        model.KVNH.Add(new NoPhaiThu());
                    List<NoPhaiTra> lst = _noPhaiTraService.GetNoPhaiTra(id).Where(x => x.LoaiPhieuNo == "CHHBX").ToList();
                    if (lst.Count > 0)
                        model.noHHBX = lst[0];
                    model.HTTT = _soThuService.GetHTTT();
                    #region Chiet khau thuong mai
                    //List<DropDownListItem> listCKTM = new List<DropDownListItem>();
                    //List<CategoryItem> ls = _categoryService.GetCategoryItem("TKHAC");
                    //foreach (CategoryItem item in ls)
                    //{
                    //    listCKTM.Add(new DropDownListItem(item.Name, item.Code));
                    //}
                    //model.LoaiChietKhau = listCKTM;
                    //model.ListChietKhauHang = _phieuThuService.GetNoChietKhauThuongMai(model.obj.SoKhung);
                    ViewNoPhaiThu nptChietKhauTM = _phieuThuService.LayCongNoChietKhauThuongMai(model.obj);
                    if (nptChietKhauTM != null)
                    {
                        ViewBag.NoChietKhauThuongMai = nptChietKhauTM.SoTienNo;
                        ViewBag.NoChietKhauThuongMai_DaTra = nptChietKhauTM.SoTienDaTra;
                        ViewBag.NoChietKhauThuongMai_ConLai = nptChietKhauTM.SoTienConLai;
                    }

                    #endregion
                    //model.Cocs = _phieuThuService.GetTCOBXBySHD(id, false);
                    //model.Cocs = _phieuThuService.GetTCOBXBySHD(model.obj.SoHopDong.Trim(), false);
                    model.Cocs = _phieuThuService.GetTCOC_V2(model.obj.MaPhieuThu, model.obj.BienSo, model.obj.SoHopDong, model.obj.HoTen, false, "TBAXE");
                    if (model.noPhaiThu == null)
                        model.noPhaiThu = new NoPhaiThu();
                    if (model.KVNH == null)
                        model.KVNH = new List<NoPhaiThu>();
                    if (model.noHHBX == null)
                        model.noHHBX = new NoPhaiTra();
                    //lấy số tiền công nợ Honda
                    ViewNoPhaiThu pt = _phieuThuService.LayCongNoChietKhauThuongMai(model.obj);
                    if (pt != null)
                    {
                        ViewBag.CongNoChietKhauThuongMai = pt.SoTienNo;
                        ViewBag.NoChietKhauThuongMai_NoiDung = pt.NoiDung;
                        ViewBag.NoChietKhauThuongMai_ConLai = pt.SoTienConLai;
                    }
                    else
                        ViewBag.CongNoChietKhauThuongMai = 0;
                }
                ViewBag.action = a;
                return View(model);
            }
            catch (Exception ex)
            {
                _logger.WriteLog("SoThuController:TBAXEEdit" + ex.ToString());
                TempData["Error"] = ex;
            }
            return View();
            // ViewBag.Alert = TempData["Alert"];

        }
