        [HttpPost]
        public ActionResult TBAXEEdit_New(PhieuThu obj, List<ChiTietPhieuThu> coc,
            List<NoPhaiThu> KVNH, List<ChiTietPhieuThu> httt, NoPhaiThu NPT, List<ChiTietKhuyenMai> CTKM, Guid IdCTPTNganHang, float? CongNoChietKhauThuongMai, string NoiDungChietKhauThuongMai, string DoiTacChietKhauThuongMai)
        {
            try
            {
                _auModel.Action = "TBAXEEdit";
                _auModel.Controller = "SoThu";
                var user = _userRegistrationService.getCurrentUser();

                if (CurrentUser.ReadOnly == true)// && !_userRegistrationService.CheckRole(_auModel)) // neu user readonly va khong duoc phan quyen tao phieu ban xe
                {
                    if (!(CurrentUser.UserName == "phuc.ngo"))
                        return Redirect("/Home/NoAccess");
                }
                //foreach (var item in coc)
                //{
                //    PhieuThu pt = _phieuThuService.GetPhieuThu(obj.MaPhieuThu);
                //    if (item.SoTienThanhToan > pt.ConLai)
                //    {
                //        TempData["Warning"] = "Không được sử dụng cọc lớn hơn số tiền còn lại.";
                //        return Redirect("~/SoThu/TBAXEEdit_New/" + obj.MaPhieuThu);
                //    }
                //}
                obj.MaLoaiPhieu = "TBAXE";
                string xml = "<Action>TBAXEEdit</Action>";
                if (obj != null)
                    xml += TNK.Core.Common.ConvertObjectToXMLString(obj);
                if (httt != null)
                {
                    xml += Environment.NewLine + "<ThanhToan>";
                    foreach (ChiTietPhieuThu ct in httt)
                        xml += TNK.Core.Common.ConvertObjectToXMLString(ct);
                    xml += Environment.NewLine + "</ThanhToan>";
                }
                if (coc != null)
                {
                    xml += Environment.NewLine + "<Coc>";
                    foreach (ChiTietPhieuThu ct in coc)
                        xml += TNK.Core.Common.ConvertObjectToXMLString(ct);
                    xml += Environment.NewLine + "</Coc>";
                }
                if (KVNH != null)
                {
                    xml += Environment.NewLine + "<KVNH>";
                    foreach (NoPhaiThu ct in KVNH)
                        xml += TNK.Core.Common.ConvertObjectToXMLString(ct);
                    xml += Environment.NewLine + "</KVNH>";
                }
                if (CTKM != null)
                {
                    xml += Environment.NewLine + "<KhuyenMai>";
                    foreach (ChiTietKhuyenMai ct in CTKM)
                        xml += TNK.Core.Common.ConvertObjectToXMLString(ct);
                    xml += Environment.NewLine + "</KhuyenMai>";
                }

                if (NPT != null)
                    xml += TNK.Core.Common.ConvertObjectToXMLString(NPT);
                xml = "<formdata>" + Environment.NewLine + xml + Environment.NewLine + "</formdata>";
                //thay doi khong can tinh ty le gia von KM nua
                double tyLeGiaVonKM = 1; //_phieuThuService.GetTyLeGiaVonKhuyenMai();
                string message = "";
                //ngay thu chinh la ngay hach toan
                obj.NgayThu = obj.NgayHachToan;
                obj.TongCong = obj.GiaBan.Value;
                string sessionId = "";
                message = _phieuThuService.KiemTraRangBuocTruocKhiUpdatePhieuThuBanXe(obj, NPT, KVNH[0], coc, CTKM);
                //khong canh bao khi co phieu tra no lien quan, chi khoa khong cho sua
                if (string.IsNullOrEmpty(message))
                {
                    if (coc != null)
                    {
                        foreach (var item in coc)
                        {
                            ChiTietPhieuThu ctptcoc = new ChiTietPhieuThu();
                            ctptcoc.Id = item.Id;
                            ctptcoc.HinhThucThanhToan = "DC";
                            ctptcoc.MaNganHang = "COCBX";
                            ctptcoc.MaPhieuThu = obj.MaPhieuThu;
                            ctptcoc.SoTienThanhToan = item.SoTienThanhToan;
                            ctptcoc.SoThamChieu = item.SoThamChieu;
                            ctptcoc.Temp = "COCBX-DC";
                            //_phieuThuService.InsertCTPT(ctptcoc);
                            httt.Add(ctptcoc);
                        }
                    }
                    if (KVNH != null)
                    {
                        foreach (var item in KVNH)
                        {
                            if (!item.IsDeleted)
                            {
                                ChiTietPhieuThu ctptkvnh = new ChiTietPhieuThu();
                                ctptkvnh.Id = IdCTPTNganHang;//lay ID ChiTietPhieuThu lien quan den ngan hang
                                ctptkvnh.HinhThucThanhToan = "NH";
                                ctptkvnh.MaNganHang = item.DonViNo;
                                ctptkvnh.MaPhieuThu = obj.MaPhieuThu;
                                ctptkvnh.SoTienThanhToan = (double)item.SoTienNo;
                                ctptkvnh.GhiChu = item.GhiChu == null ? "" : item.GhiChu;
                                ctptkvnh.Temp = item.DonViNo + "-NH";
                                httt.Add(ctptkvnh);
                                //_phieuThuService.InsertCTPT(ctptkvnh);
                                //da chuyen xu ly xuong database
                                //_noPhaiThuService.InsertNoPhaiThu("NNHBX", obj.MaPhieuThu, "", ctptkvnh.SoTienThanhToan, item.NguoiBaoLanh, ctptkvnh.GhiChu);
                                _noPhaiThuService.UpdateNoPhaiThu(item);
                            }
                        }
                    }

                    //neu so tien da tra no bang 0 thi moi cho cap nhat cac thong tin phieu thu
                    if (NPT.SoTienDaTra == 0)
                        message = _phieuThuService.UpdatePhieuThu(obj, httt, ref sessionId, false);
                    else
                    {
                        message = _phieuThuService.UpdatePhieuThuHH(obj);
                        //Cập nhật lại nợ Khuyến mãi
                        message = _phieuThuService.UpdatePhieuThuNoKhuyenMai(obj);
                    }
                        
                    if (string.IsNullOrEmpty(message))
                    {
                        if (NPT.SoTienDaTra == 0)
                        {
                            if (coc != null)
                            {
                                _phieuThuService.UpdateCTPT(coc, obj);
                            }
                            _noPhaiThuService.UpdateNoPhaiThu(NPT);
                        }

                    }
                    foreach (var item in CTKM)
                    {
                        item.GiaVon = item.GiaBan;
                        if (item.Id != Guid.Empty)
                            _ctkmService.UpdateCTKM(item);
                        else
                        {
                            if (item.IsDeleted == false)
                            {
                                item.MaPhieuThu = obj.MaPhieuThu;
                                _ctkmService.InsertCTKM(item);
                            }
                        }
                    }
                }
                else
                {
                    foreach (var item in CTKM)
                    {
                        if (item.MaPhieuThu != null)
                        {
                            item.GiaVon = item.GiaBan;
                            if (item.Id != Guid.Empty)
                            {
                                if (!((item.NguonKhuyenMai == "HH" && message == "Đã có phiếu chi hoa hồng bán xe")
                                    || (item.NguonKhuyenMai.Contains("BDTK") && message == "Đã sử dụng gói Bảo dưỡng tiết kiệm")
                                    )
                                    )
                                    _ctkmService.UpdateCTKM(item);
                            }
                            else
                            {
                                if (item.IsDeleted == false)
                                {
                                    item.MaPhieuThu = obj.MaPhieuThu;
                                    _ctkmService.InsertCTKM(item);
                                }
                            }
                        }
                    }
                    if (!string.IsNullOrEmpty(message))
                        message = "Đã lưu thông tin khuyến mãi. Các thông tin còn lại không được phép lưu vì: " + message;
                }
                //tạo công nợ chiết khấu thương mại
                // tạo mới phiếu thu khác
                string messageChietKhauThuongMai = "";
                if (CongNoChietKhauThuongMai >= 0 && CongNoChietKhauThuongMai !=null)
                {
                    string noiDung = NoiDungChietKhauThuongMai;
                    messageChietKhauThuongMai = _phieuThuService.TaoCongNoChietKhauThuongMai(obj, "NKHAC", "TTBH", noiDung, (float)CongNoChietKhauThuongMai, DoiTacChietKhauThuongMai);
                }
                string result = _phieuThuService.XuLySauKhiUpdatePhieuThu(obj.MaPhieuThu, sessionId, xml);              
                result += messageChietKhauThuongMai;
                if (string.IsNullOrEmpty(result))
                {
                    TempData["Info"] = "Cập nhật thành công." + message;
                }
                else
                {
                    TempData["Alert"] = result + "." + message ;
                }
                return Redirect("/Sothu/TBAXEIndex");
            }
            catch (Exception ex)
            {
                _logger.WriteLog("SoThuController:TBAXEEdit_New" + ex.ToString());
                TempData["Error"] = ex;
            }
            return View();

        }

        public ActionResult TBAXECreate(string id)
        {
            DateTime start = DateTime.Now;
            try
            {

                ViewBag.Title = "Thu bán xe";
                BanXeModel model = new BanXeModel();
                model.Users = _userService.get();
                model.CTKM = new List<ViewChiTietKhuyenMai>();
                model.CTKM.Add(new ViewChiTietKhuyenMai());
