                model.NKM = _ctkmService.GetNKM(true);
                model.noPhaiThu = new NoPhaiThu();
                model.CTPT = new List<ChiTietPhieuThu>();
                model.CTPT.Add(new ChiTietPhieuThu());
                model.KVNH = new List<NoPhaiThu>();
                model.KVNH.Add(new NoPhaiThu());
                model.HTTT = _soThuService.GetHTTT();
                model.DoiTac = _soThuService.GetDoiTac("NCC");
                var obj = _phieuThuService.GetTBAXE(id);
                model.obj = new PhieuThu();
                ViewBag.CNTT = 0;
                if (obj != null)
                {
                    ViewBag.CNTT = _phieuThuService.GetCNTT(obj.SoKhung);
                    model.obj.SoHopDong = obj.SoHopDong.ToString();
                    model.obj.NgayHopDong = obj.NgayHopDong;
                    model.obj.SoKhung = obj.SoKhung;
                    model.obj.MaXe = obj.LoaiXe;
                    model.obj.NgayHopDong = obj.NgayHopDong;
                    model.obj.MauXe = obj.MauXe;
                    model.obj.DiaChi = obj.DiaChi;
                    model.obj.DienThoai = obj.DienThoai;
                    model.obj.HoTen = obj.HoTen;
                    model.obj.GiaBan = obj.GiaBan == null ? 0 : (double)obj.GiaBan;
                    model.obj.GiaNiemYet = (double)obj.GiaNiemYet;
                    model.obj.GiamGia = obj.GiamGia;
                    model.obj.NhanVienTuVan = obj.NhanVienTuVan;
                    model.obj.NoKhuyenMai = obj.PhuKienHuaTang;
                    //model.Cocs = _phieuThuService.GetTCOBXBySHD(model.obj.SoHopDong.Trim().ToString(), true);
                    model.Cocs = _phieuThuService.GetTCOC_V2(model.obj.MaPhieuThu, model.obj.BienSo, model.obj.SoHopDong, model.obj.HoTen, false, "TBAXE");
                    model.ListKMBaoHiem = _phieuThuService.GetKMBaoHiem(model.obj.SoHopDong.Trim().ToString());
                    model.ListKMPKien = _phieuThuService.GetKMPKien(model.obj.SoHopDong.Trim().ToString());
                    //Khuyen mai hua tang lay tu Cyber


                    if (obj.HoaHong > 0)
                    {
                        ViewChiTietKhuyenMai ctkm = new ViewChiTietKhuyenMai();
                        ctkm.GiaBan = obj.HoaHong.Value;
                        ctkm.GiaVon = obj.HoaHong.Value;
                        ctkm.NoiDung = "Hoa Hồng";
                        ctkm.GhiChu = "Hoa Hồng môi giới bán xe ";
                        ctkm.NguonKhuyenMai = "HH";
                        ctkm.SoTienDaTra = 0;
                        model.CTKM.Add(ctkm);
                    }
                    if (obj.PhiTruocBa > 0)
                    {
                        ViewChiTietKhuyenMai ctkm = new ViewChiTietKhuyenMai();
                        ctkm.GiaBan = obj.PhiTruocBa.Value;
                        ctkm.GiaVon = obj.PhiTruocBa.Value;
                        ctkm.NoiDung = "Phí trước bạ";
                        ctkm.GhiChu = "Phí trước bạ";
                        ctkm.NguonKhuyenMai = "KM_KHAC";
                        ctkm.SoTienDaTra = 0;
                        model.CTKM.Add(ctkm);
                    }
                    //model.ListChiPhi = _phieuThuService.GetChiPhiPhieuBanXe(model.obj.SoKhung);
                }
                else
                {
                    //model.Cocs = new List<ViewTCOBX>();
                    //model.Cocs = _phieuThuService.GetTCOBXBySHD(model.obj.SoHopDong.Trim().ToString(), true);
                    model.Cocs = _phieuThuService.GetTCOC_V2(model.obj.MaPhieuThu, model.obj.BienSo, model.obj.SoHopDong, model.obj.HoTen, false, "TBAXE");
                }
                DateTime end = DateTime.Now;
                this.AddActionLog(CurrentUser.UserName,"SoThu", "TBAXECreate", start, end, "");
                return View(model);
            }
            catch (Exception ex)
            {
                _logger.WriteLog("SoThuController:TBAXECreate" + ex.ToString());
                TempData["Error"] = ex;
                DateTime end = DateTime.Now;
                this.AddActionLog(CurrentUser.UserName,"SoThu", "TBAXECreate", start, end, ex);
            }
            return View();
            // ViewBag.Alert = TempData["Alert"];

        }

