        //phan ban xe nhap tay
        public static string messageBanXe = "";
        public ActionResult TBAXECreate_New(string id)
        {
            _auModel.Action = "TBAXECreate_New";
            _auModel.Controller = "SoThu";
            var user = _userRegistrationService.getCurrentUser();

            if (CurrentUser.ReadOnly == true)// && !_userRegistrationService.CheckRole(_auModel)) // neu user readonly va khong duoc phan quyen tao phieu ban xe
            {
                if (!(CurrentUser.UserName == "phuc.ngo"))
                    return Redirect("/Home/NoAccess");
            }
            try
            {
                ViewBag.Message = messageBanXe;
                ViewBag.Title = "Thu bán xe";
                BanXeModel model = new BanXeModel();
                model.Users = _userService.get();
                model.CTKM = new List<ViewChiTietKhuyenMai>();
                model.CTKM.Add(new ViewChiTietKhuyenMai());
                model.NganHang = _soThuService.GetDoiTac("NH");
                model.NKM = _ctkmService.GetNKM(true);
                model.noPhaiThu = new NoPhaiThu();
                model.CTPT = new List<ChiTietPhieuThu>();
                model.CTPT.Add(new ChiTietPhieuThu());
                model.KVNH = new List<NoPhaiThu>();
                model.KVNH.Add(new NoPhaiThu());
                model.HTTT = _soThuService.GetHTTT();
                var obj = _phieuThuService.GetTBAXE(id);
                model.DoiTac = _soThuService.GetDoiTac("NCC");
              
                model.obj = new PhieuThu();
                
                if (obj != null)
                {
                    model.obj.SoHopDong = obj.SoHopDong.ToString();
                    model.obj.NgayHopDong = obj.NgayHopDong;
                    model.obj.SoKhung = obj.SoKhung;
                    model.obj.MaXe = obj.LoaiXe;
                    model.obj.NgayHopDong = obj.NgayHopDong;
                    model.obj.MauXe = obj.MauXe;
                    model.obj.DiaChi = obj.DiaChi;
                    model.obj.DienThoai = obj.DienThoai;
                    model.obj.HoTen = obj.HoTen;
                    //model.obj.GiaBan = obj.GiaBan == null ? 0 : (double)obj.GiaBan;
                    model.obj.GiaNiemYet = (double)obj.GiaNiemYet;
                    model.obj.GiamGia = obj.GiamGia;
                    //model.Cocs = _phieuThuService.GetTCOBXBySHD(model.obj.SoHopDong.Trim().ToString(), true);
                    model.Cocs = _phieuThuService.GetTCOC_V2(model.obj.MaPhieuThu, model.obj.BienSo, model.obj.SoHopDong, model.obj.HoTen, true, "TBAXE");
                    model.ListKMBaoHiem = _phieuThuService.GetKMBaoHiem(model.obj.SoHopDong.Trim().ToString());
                    model.ListKMPKien = _phieuThuService.GetKMPKien(model.obj.SoHopDong.Trim().ToString());
                    model.CTKM = _ctkmService.GetCTKM(id);
                    ViewBag.NoKhuyenMai = _phieuThuService.GetNKMPK(model.obj.SoHopDong.Trim().ToString());
                }
                else
                {
                    model.obj.SoHopDong = id;
                    model.Cocs = new List<ViewTCOC>();
                    model.Cocs = _phieuThuService.GetTCOC_V2(model.obj.MaPhieuThu, model.obj.BienSo, model.obj.SoHopDong, model.obj.HoTen, true, "TBAXE");
                    //model.Cocs = _phieuThuService.GetTCOBXBySHD(id.Trim().ToString(), true);
                    model.ListKMBaoHiem = _phieuThuService.GetKMBaoHiem(id.Trim().ToString());
                    model.ListKMPKien = _phieuThuService.GetKMPKien(id.Trim().ToString());
                    model.CTKM = _ctkmService.GetCTKM(id.Trim().ToString());
                    model.ListBDTK = _phieuThuService.GetBDTK(id.Trim().ToString());
                    ViewBag.NoKhuyenMai = _phieuThuService.GetNKMPK(id.Trim().ToString());
                }
                if (messageBanXe != "")
                {
                    ViewBag.Message = messageBanXe;
                    messageBanXe = "";
                }
                if (model.CTKM.Count == 0)
                    model.CTKM.Add(new ViewChiTietKhuyenMai());
                ViewBag.SoPhieu = id;
                return View(model);
            }
            catch (Exception ex)
            {
                _logger.WriteLog("SoThuController:TBAXECreate_New" + ex.ToString());
                TempData["Error"] = ex;
            }
            return View();
        }
        public JsonResult LaySoKhung(string soKhung)
        {
            var item = new ViewKhoXe();
            if (soKhung != "")
            {
                item = _phieuThuService.GetXe(soKhung);
                if (item != null)
                {
                    if (item.GiaNiemYet == 0)
                        item.GiaNiemYet = item.GiaVon;
                }
            }
            if (item == null)
            {
                item = new ViewKhoXe();
            }
            return Json(item, JsonRequestBehavior.AllowGet);
        }

        public JsonResult LayGiaVonBDTK(string ma)
        {
            double giaVonBDTK = 0;
            if (ma != "" && ma.Contains("BDTK"))
            {
                giaVonBDTK = _phieuThuService.LayGiaVonBDTK(ma);

            }
            return Json(giaVonBDTK, JsonRequestBehavior.AllowGet);
        }

        [HttpPost]
        public ActionResult TBAXECreate_New(PhieuThu obj, List<ViewTCOBX> coc, List<NoPhaiThu> KVNH, List<ChiTietPhieuThu> httt, NoPhaiThu NPT, List<ChiTietKhuyenMai> CTKM, float? CongNoChietKhauThuongMai, string NoiDungChietKhauThuongMai, string DoiTacChietKhauThuongMai)
        {
            try
            {
                _auModel.Action = "TBAXECreate_New";
                _auModel.Controller = "SoThu";
                var user = _userRegistrationService.getCurrentUser();

                if (CurrentUser.ReadOnly == true)// && !_userRegistrationService.CheckRole(_auModel)) // neu user readonly va khong duoc phan quyen tao phieu ban xe
                {
                    if (!(CurrentUser.UserName == "phuc.ngo"))
                        return Redirect("/Home/NoAccess");
                }
                obj.MaLoaiPhieu = "TBAXE";
                obj.GiaNiemYet = obj.GiaVon;
                obj.GiaBan = obj.GiaNiemYet.Value - obj.GiamGia;
                KhoXe khoxe = new KhoXe();
                khoxe = _khoXeService.GetXebySoKhung(obj.SoKhung);

                if (khoxe != null)
                {
                    LoaiXe loaixe = _loaiXeService.GetLoaiXe(khoxe.MaLoaiXe);
                    if (loaixe != null)
                    {
                        //25.7.2024: Xin ý kiến Phú không cần ràng buộc Giá Niêm Yết được vì đã lấy từ Cyber
                        //if (obj.GiaNiemYet.Value != khoxe.GiaNiemYet
                        //    || obj.GiaNiemYet.Value != loaixe.GiaNiemYet
                        //    || loaixe.GiaNiemYet != khoxe.GiaNiemYet)
                        //{
                        //    //LichSuThaoTac lichsuthaotac = _lichSuThaoTacService.GetLSTTGNY(loaixe.MaLoaiXe);
                        //    //if(lichsuthaotac != null)
                        //    //{
                        //    //    string date = lichsuthaotac.CreatedDate.Day.ToString() + "/"
                        //    //                + lichsuthaotac.CreatedDate.Month.ToString() + "/"
                        //    //                + lichsuthaotac.CreatedDate.Year.ToString() + " "
                        //    //                + lichsuthaotac.CreatedDate.Hour.ToString()
                        //    //                + lichsuthaotac.CreatedDate.Minute.ToString()
                        //    //                + lichsuthaotac.CreatedDate.Second.ToString();
                        //    //    TempData["Error"] = lichsuthaotac.ChiTiet + " vào lúc " + date;
                        //    //    messageBanXe = lichsuthaotac.ChiTiet + " vào lúc " + date;
                        //    //    return Redirect("~/SoThu/TBAXEIndex");
                        //    //}
                        //    //return Redirect("~/SoThu/TBAXEIndex/");
                        //    TempData["Error"] = "Không thể lưu do giá niêm yết đã thay đổi";
                        //    return Redirect("/SoThu/TBAXEIndex");
                        //}
                    }
                }


                obj.Flag = true;
                //kiểm tra số khung có tồn tại trong kho hay không ?
                bool CheckSoKhung = _phieuThuService.CheckSoKhung(obj.SoKhung);
                if (CheckSoKhung == false)
                {
                    TempData["Error"] = "Không tìm thấy số khung trong kho";
                    //ViewBag.Error = "Không tìm thấy số khung trong kho";
                    return Redirect("/SoThu/TBAXECreate");
                }
                //kiểm tra tồn tại màu xe trong 
                bool CheckMauXe = _phieuThuService.CheckMauXe(obj.MauXe, obj.SoKhung);
                if (CheckMauXe == false)
                {
                    TempData["Error"] = "Không tìm thấy màu xe trong kho";
                    //ViewBag.Error = "Không tìm thấy màu xe trong kho";
                    return Redirect("/SoThu/TBAXECreate");
                }

                //kiểm tra tồn tại mã xe
                bool CheckMaXe = _phieuThuService.CheckMaXe(obj.MaXe, obj.SoKhung);
                if (CheckMaXe == false)
                {
                    TempData["Error"] = "Không tìm thấy mã xe trong kho";
                    //ViewBag.Error = "Không tìm thấy mã xe trong kho";
                    return Redirect("/SoThu/TBAXECreate");
                }
                string xml = "<Action>TBAXECreate_New</Action>";
                if (obj != null)
                    xml += TNK.Core.Common.ConvertObjectToXMLString(obj);
                if (httt != null)
                {
                    xml += Environment.NewLine + "<ThanhToan>";
                    foreach (ChiTietPhieuThu ct in httt)
                        xml += TNK.Core.Common.ConvertObjectToXMLString(ct);
                    xml += Environment.NewLine + "</ThanhToan>";
                }
                if (coc != null)
                {
                    xml += Environment.NewLine + "<Coc>";
                    foreach (ViewTCOBX ct in coc)
                        xml += TNK.Core.Common.ConvertObjectToXMLString(ct);
                    xml += Environment.NewLine + "</Coc>";
                }
                if (CTKM != null)
                {
                    xml += Environment.NewLine + "<KhuyenMai>";
                    foreach (ChiTietKhuyenMai ct in CTKM)
                        xml += TNK.Core.Common.ConvertObjectToXMLString(ct);
                    xml += Environment.NewLine + "</KhuyenMai>";
                }
                if (KVNH != null)
                {
                    xml += Environment.NewLine + "<KVNH>";
                    foreach (NoPhaiThu ct in KVNH)
                        xml += TNK.Core.Common.ConvertObjectToXMLString(ct);
                    xml += Environment.NewLine + "</KVNH>";
                }
                if (NPT != null)
                    xml += TNK.Core.Common.ConvertObjectToXMLString(NPT);
                if (CongNoChietKhauThuongMai != null)
                    xml += TNK.Core.Common.ConvertObjectToXMLString(CongNoChietKhauThuongMai);
                xml = "<formdata>" + Environment.NewLine + xml + Environment.NewLine + "</formdata>";
                //thay đổi: không cần lấy tỷ lệ giá vốn bán xe nữa
                double tyLeGiaVonKM = 1;// _phieuThuService.GetTyLeGiaVonKhuyenMai();

                //thangtx: Tong cong can thu = gia ban xe
                obj.TongCong = obj.GiaBan.Value;
                TempData["Info"] = "Tạo mới thành công";
                if (coc != null)
                {
                    foreach (var item in coc)
                    {
                        ChiTietPhieuThu ctptcoc = new ChiTietPhieuThu();
                        ctptcoc.HinhThucThanhToan = "DC";
                        ctptcoc.MaNganHang = "COCBX";
                        ctptcoc.MaPhieuThu = obj.MaPhieuThu;
                        ctptcoc.SoTienThanhToan = (double)item.SoTienDaSuDung;
                        ctptcoc.SoThamChieu = item.MaPhieuThu;
                        ctptcoc.Temp = "COCBX" + "-" + "DC";
                        httt.Add(ctptcoc);
                    }
                }
                if (KVNH != null)
                {
                    foreach (var item in KVNH)
                    {
                        if (!item.IsDeleted)
                        {
                            ChiTietPhieuThu ctptkvnh = new ChiTietPhieuThu();
                            ctptkvnh.HinhThucThanhToan = "NH";
                            ctptkvnh.MaNganHang = item.DonViNo;
                            ctptkvnh.MaPhieuThu = obj.MaPhieuThu;
                            ctptkvnh.SoTienThanhToan = (double)item.SoTienNo;
                            ctptkvnh.GhiChu = item.GhiChu == null ? "" : item.GhiChu;
                            ctptkvnh.Temp = item.DonViNo + "-NH";
                            httt.Add(ctptkvnh);
                            //da chuyen xu ly xuong database
                            //_noPhaiThuService.InsertNoPhaiThu("NNHBX", obj.MaPhieuThu, "", ctptkvnh.SoTienThanhToan, item.NguoiBaoLanh, ctptkvnh.GhiChu);
                        }
                    }
                }
                string message = _phieuThuService.CreatePhieuThu(obj, httt, false);
                if (string.IsNullOrEmpty(message))
                {

                    NPT.SoTienNo = obj.TongCong - obj.SoTienThu;
                    //da chuyen xuong xu ly duooi database
                    // _noPhaiThuService.InsertNoPhaiThu("NBAXE", obj.MaPhieuThu, NPT.NguoiBaoLanh, NPT.SoTienNo, "", "");
                    if (CTKM != null)
                    {
                        foreach (var item in CTKM)
                        {
                            if (!item.IsDeleted)
                            {
                                item.MaPhieuThu = obj.MaPhieuThu;
                                //thay doi khong can tinh ty le gia von khuyen mai nua
                                //item.GiaVon = tyLeGiaVonKM * item.GiaBan;
                                item.GiaVon = item.GiaBan;
                                _ctkmService.InsertCTKM(item);
                            }
                        }
                    }
                    //tạo công nợ chiết khấu thương mại
                    // tạo mới phiếu thu khác
                    string messageChietKhauThuongMai = "";
                    if (CongNoChietKhauThuongMai > 0)
                    {
                        string noiDung = NoiDungChietKhauThuongMai;
                        messageChietKhauThuongMai = _phieuThuService.TaoCongNoChietKhauThuongMai(obj, "NKHAC", "TTBH", noiDung, (float)CongNoChietKhauThuongMai, DoiTacChietKhauThuongMai);
                    }

                    //xu ly sai khi insert phieu thu
                    string result = _phieuThuService.XuLySauKhiInsertPhieuThu(obj.MaPhieuThu, xml);
                    result += messageChietKhauThuongMai;
                    if (string.IsNullOrEmpty(result))
                    {
                        TempData["Info"] = "Tạo mới thành công";
                    }
                    else
                    {
                        TempData["Info"] = result;
                    }
                    return Redirect("/SoThu/TBAXEIndex");
                }
                else
                {
                    TempData["Info"] = "Lỗi tạo phiếu:" + message;
                }
                ViewBag.Error = "Lỗi tạo phiếu";
                return Redirect("/Sothu/TBAXEIndex");
            }
            catch (Exception ex)
            {
                _logger.WriteLog("SoThuController:TBAXECreate_New" + ex.ToString());
                TempData["Error"] = ex;
            }
            return View();

        }

