                if (coc != null)
                {
                    foreach (var item in coc)
                    {
                        ChiTietPhieuThu ctptcoc = new ChiTietPhieuThu();
                        ctptcoc.HinhThucThanhToan = "DC";
                        ctptcoc.MaNganHang = "COCBX";
                        ctptcoc.MaPhieuThu = obj.MaPhieuThu;
                        ctptcoc.SoTienThanhToan = (double)item.SoTienDaSuDung;
                        ctptcoc.SoThamChieu = item.MaPhieuThu;
                        ctptcoc.Temp = "COCBX" + "-" + "DC";
                        httt.Add(ctptcoc);
                    }
                }
                if (KVNH != null)
                {
                    foreach (var item in KVNH)
                    {
                        if (!item.IsDeleted)
                        {
                            ChiTietPhieuThu ctptkvnh = new ChiTietPhieuThu();
                            ctptkvnh.HinhThucThanhToan = "NH";
                            ctptkvnh.MaNganHang = item.DonViNo;
                            ctptkvnh.MaPhieuThu = obj.MaPhieuThu;
                            ctptkvnh.SoTienThanhToan = (double)item.SoTienNo;
                            ctptkvnh.GhiChu = item.GhiChu == null ? "" : item.GhiChu;
                            ctptkvnh.Temp = item.DonViNo + "-NH";
                            httt.Add(ctptkvnh);
                            //da chuyen xu ly xuong database
                            //_noPhaiThuService.InsertNoPhaiThu("NNHBX", obj.MaPhieuThu, "", ctptkvnh.SoTienThanhToan, item.NguoiBaoLanh, ctptkvnh.GhiChu);
                        }
                    }
                }
                string message = _phieuThuService.CreatePhieuThu(obj, httt, false);
                if (string.IsNullOrEmpty(message))
                {

                    NPT.SoTienNo = obj.TongCong - obj.SoTienThu;
                    //da chuyen xuong xu ly duooi database
                    // _noPhaiThuService.InsertNoPhaiThu("NBAXE", obj.MaPhieuThu, NPT.NguoiBaoLanh, NPT.SoTienNo, "", "");
                    if (CTKM != null)
                    {
                        foreach (var item in CTKM)
                        {
                            if (!item.IsDeleted)
                            {
                                item.MaPhieuThu = obj.MaPhieuThu;
                                //thay doi khong can tinh ty le gia von khuyen mai nua
                                //item.GiaVon = tyLeGiaVonKM * item.GiaBan;
                                item.GiaVon = item.GiaBan;
                                _ctkmService.InsertCTKM(item);
                            }
                        }
                    }
                    //tạo công nợ chiết khấu thương mại
                    // tạo mới phiếu thu khác
                    string messageChietKhauThuongMai = "";
                    if (CongNoChietKhauThuongMai > 0)
                    {
                        string noiDung = NoiDungChietKhauThuongMai + "(" + obj.HoTen + "-SK:" + obj.SoKhung + ")";
                        messageChietKhauThuongMai = _phieuThuService.TaoCongNoChietKhauThuongMai(obj, "NKHAC", "TTBH", noiDung, CongNoChietKhauThuongMai, DoiTacChietKhauThuongMai);
                    }
                    //xu ly sai khi insert phieu thu
                    string result = _phieuThuService.XuLySauKhiInsertPhieuThu(obj.MaPhieuThu, xml);
                    result += messageChietKhauThuongMai;
                    if (string.IsNullOrEmpty(result))
                    {
                        TempData["Info"] = "Tạo mới thành công";
                    }
                    else
                    {
                        TempData["Info"] = result;
                    }
                    return Redirect("/SoThu/TBAXEIndex");
                }
                else
                {
                    TempData["Info"] = "Lỗi tạo phiếu:" + message;
                }
                ViewBag.Error = "Lỗi tạo phiếu";
                return Redirect("/Sothu/TBAXECreate/" + obj.SoHopDong);
            }
            catch (Exception ex)
            {
                _logger.WriteLog("SoThuController:TBAXECreate" + ex.ToString());
                TempData["Error"] = ex;
            }
            return View();

        }

