        #region Thu nợ
        public ActionResult ThuNo(string submit, string id = "", string from = "", string to = "", string query = "", int p = 1, string tinhtrang = "", string queryGiaiTrinh = "", string loaiGiaiTrinh = "", string loaiBH = "", int pageSize = 30)
        {
            try
            {
                ViewBag.Alert = TempData["Alert"];
                ViewBag.Title = "Danh sách nợ " + GetTenLoaiNo(id);
                ViewBag.SearchHolder = GetSearchNoHolder(id);
                ViewBag.KhachHangNoTitle = GetKhachHangNoTitle(id);
                switch (submit)
                {
                    case "Tìm kiếm giải trình":
                        submit = "SearchGiaiTrinh";
                        break;
                    default:
                        submit = "Search";
                        break;

                }

                ViewBag.Submit = submit;
                DateTime f = new DateTime(), t = new DateTime();
                var model = new List<ViewNoPhaiThuBHDV>();
                if (id == "NNHBX" || id == "NBHDV")
                {
                    if (submit == "Search")
                    {
                        SetSearch(ref from, ref to, ref f, ref t, p, ref query, id, tinhtrang, pageSize);
                        model = _phieuThuService.GetNoPhaiThuBHDVs(id, f, t, query, p, ref total, pageSize, tinhtrang,loaiBH);
                    }


                }
                else
                {
                    SetSearch(ref from, ref to, ref f, ref t, p, ref query, id, tinhtrang, pageSize);
                    model = _phieuThuService.GetNoPhaiThuBHDVs(id, f, t, query, p, ref total, pageSize, tinhtrang, loaiBH);
                }
                //Kiểm tra tk thuộc quyền PTC
                bool rs = false;
                if (id == "NHHGP")
                {
                    rs = _roleService.CheckUserInRole(CurrentUser.UserId, "PTC");
                }
                ViewBag.IsPTC = rs;
                ViewBag.Type = id;
                ViewBag.Total = total;
                ViewBag.Url = Request.Url.AbsolutePath + "?from=" + from + "&to=" + to + "&query=" + query + "&id=" + id + "&tinhtrang=" + tinhtrang + "&p=";

                return View(model);
            }
            catch (Exception ex)
            {
                _logger.WriteLog("SoThuController:ThuNo" + ex.ToString());
                TempData["Error"] = ex;
            }
            return View();

        }

