        public ActionResult ThuNoCreate(string id, string type)
        {
            try
            {
                if (type == "NHHBH" || type == "NBHDV" || type == "NHHHB" || type == "NHHGP" || type == "NTKHA" || type == "NHANG" || type == "CHIHO")
                {
                    if (id == "0")
                    {
                        var cookie = Request.Cookies.Get("link");
                        if (cookie != null)
                        {
                            id = cookie.Value;
                            id = id.Replace(",", ";");
                        }
                    }
                }
                Request.Cookies.Remove("link");
                var result = id.Split(new char[] { ';' }, StringSplitOptions.RemoveEmptyEntries);
                //ViewBag.Alert = TempData["Alert"];

                ViewBag.Title = "Tạo mới phiếu thu nợ " + GetTenLoaiNo(type);
                ViewBag.KhachHangNoTitle = GetKhachHangNoTitle(type);
                ViewBag.Id = id;
                ViewBag.Type = type;
                //Lay chuoi updateddate cua cac phieu thu no goc de khi luu xuong thi kiem tra xem cac phieu nay da bi thay doi thong tin chua
                ViewBag.ChuoiUpdatedDate = _phieuThuService.LayNgayUpdateCuaCacPhieuNo(id);

                var model = GetModelCreate();
                int demNTHKA = 0;
                if (type == "NBHDV" || type == "NHHBH" || type == "NTKHA" || type == "NHHHB" || type == "NHHGP" || type == "NHANG" || type =="CHIHO")
                {
                    model.NPT = new ViewNoPhaiThu();
                    model.NPT.LoaiPhieuNo = type;
                    foreach (var item in result)
                    {
                        var obj = _phieuThuService.GetNoPhaiThu(item);
                        model.NPT.MaPhieuNo += obj.MaPhieuNo + ";";
                        model.NPT.SoTienNo += obj.SoTienNo;
                        model.NPT.SoTienConLai += obj.SoTienConLai;
                        model.NPT.DonViNo = obj.DonViNo;
                        if (type == "NHHBH")
                        {
                            obj.HoTenKH = obj.HoTenKH.Replace("\r\n", " ");
                            if (obj.HoTenKH != "" && obj.HoTenKH != null)
                            {
                                int vitri = obj.HoTenKH.LastIndexOf(";");
                                //string hoten = obj.HoTenKH.Substring(vitri);
                                model.NPT.KhachHang += obj.HoTenKH;
                            }
                            else
                            {
                                model.NPT.KhachHang += obj.KhachHang + ";";
                            }
                        }
                        else if (type == "NHHHB")
                        {

                            if (obj.HoTenKH != "" && obj.HoTenKH != null)
                            {
                                int vitri = obj.HoTenKH.LastIndexOf("\n");
                                string hoten = obj.HoTenKH.Substring(vitri);
                                model.NPT.KhachHang += hoten + ",";
                            }
                        }
                        else if (type == "NTKHA" || type=="CHIHO")
                        {
                            if (demNTHKA == 0)
                                model.NPT.KhachHang += obj.TenDoiTac;
                            demNTHKA++;
                        }
                        else
                        {
                            model.NPT.KhachHang += obj.KhachHang + "\n";
                            //if (string.IsNullOrEmpty(model.NPT.KhachHang))
                            //{
                            //    model.NPT.KhachHang = obj.KhachHang + "\n";
                            //}
                        }
                        if (type != "NTKHA" && type != "NHHGP")
                            model.NPT.KhachHang += obj.BienSo + ";";
                        //if (model.NPT.LoaiPhieuNo == "NTKHA")
                        //    model.NPT.KhachHang += obj.TenDoiTac;

                    }
                    if (type == "NHHHB")
                    {
                        model.NPT.KhachHang = model.NPT.DonViNo + " " + (model.NPT.MaPhieuNo.Length / 16) + " phiếu HHHB";
                    }
                    if (model.NPT.MaPhieuNo != "")
                        model.NPT.MaPhieuNo = model.NPT.MaPhieuNo.Substring(0, model.NPT.MaPhieuNo.Length - 1);
                    if (type == "NBHDV" || type == "NHHBH")
                    {
                        //model.Coc = _phieuThuService.GetTCOC(model.Item.MaPhieuThu, model.Item.BienSo, model.Item.HoTen, true);
                        model.CocCongNo = _phieuThuService.ListCongNo(model.Item.MaPhieuThu, model.NPT.DonViNo, true).Where(x => x.TongCong > 0).ToList();
                    }
                    return View(model);
                }
                else
                {
                    model.NPT = _phieuThuService.GetNoPhaiThu(id);
                    string MaPS = model.NPT == null ? "" : model.NPT.MaPhieuPhatSinh;
                    var PBAXEs = _phieuThuService.GetPhieuThu(MaPS);
                    string MaPT = PBAXEs == null ? "" : PBAXEs.MaPhieuThu;
                    model.ViewPhieuThu = _phieuThuService.GetViewPhieuThu(MaPT, "");
                    ViewBag.NoPhieuThu = _noPhaiThuService.GetNoPhaiThu(MaPT, "NHHGP");
                    return View(model);
                }
            }
            catch (Exception ex)
            {
                _logger.WriteLog("SoThuController:ThuNoCreate" + ex.ToString());
                TempData["Error"] = ex;
            }
            return View();

        }
        [HttpPost]
        public ActionResult ThuNoCreate(PhieuThu item, List<ChiTietPhieuThu> httt, List<ChiTietPhieuThu> Coc, string submit, string ids, string ChuoiUpdatedDate)
        {
            try
            {
                if (CurrentUser.ReadOnly == true)
                {
                    return Redirect("/Home/NoAccess");
                }
                ViewBag.Type = item.MaLoaiPhieu;
                ViewBag.Title = "Thu nợ ";
                string xml = "<Action>ThuNoEdit</Action>";
                if (item != null)
                    xml += TNK.Core.Common.ConvertObjectToXMLString(item);
                if (httt != null)
                {
                    xml += Environment.NewLine + "<ThanhToan>";
                    foreach (ChiTietPhieuThu ct in httt)
                        xml += TNK.Core.Common.ConvertObjectToXMLString(ct);
                    xml += Environment.NewLine + "</ThanhToan>";
                }
                //if (Coc != null)
                //{
                //    foreach (var c in Coc)
                //    {
                //        httt.Add(c);
                //    }
                //}
                xml = "<formdata>" + Environment.NewLine + xml + Environment.NewLine + "</formdata>";
                string chuoiUpdatedDateDatabase = _phieuThuService.LayNgayUpdateCuaCacPhieuNo(!string.IsNullOrEmpty(ids) ? ids : item.MaPhieuLienQuan);
                if (ChuoiUpdatedDate != chuoiUpdatedDateDatabase)
                {
                    TempData["Warning"] = "Không thể tạo phiếu thu nợ vì phiếu nợ gốc đã có người cập nhật trước đó.";
                    _logger.WriteLog("Warning ThuNoCreate:" + "Không thể tạo phiếu thu nợ vì phiếu nợ gốc đã có người cập nhật trước đó.");
                    return Redirect("/SoThu/ThuNo/" + item.MaLoaiPhieu);
                }
                else
                {
                    string message = "";
                    if (item.MaLoaiPhieu == "NBHDV")
                    {
                        if (item.MaPhieuLienQuan.Contains(";"))
                            item.ConLai = 0;
                        message = _phieuThuService.CreatePhieuThu_ThuNo(item, httt, Coc, false);
                    }
                    else
                    {
                        message = _phieuThuService.CreatePhieuThu(item, httt, false);
                    }
                    if (string.IsNullOrEmpty(message))
                    {
                        if (!string.IsNullOrEmpty(ids))
                        {
                            var result = ids.Split(new char[] { ';' }, StringSplitOptions.RemoveEmptyEntries);
                            foreach (var obj in result)
                            {
                                _noPhaiThuService.UpdateMaPhieuThu(obj, item.MaPhieuThu);
                            }
                        }
                        //xu ly sai khi insert phieu thu
                        string tempData = _phieuThuService.XuLySauKhiInsertPhieuThu(item.MaPhieuThu, xml);
                        if (string.IsNullOrEmpty(tempData))
                        {
                            TempData["Info"] = "Tạo mới thành công";
                        }
                        else
                        {
                            TempData["Info"] = tempData;
                        }
                        //TempData["Info"] = "Tạo mới thành công";
                        return Redirect("/SoThu/ThuNo/" + item.MaLoaiPhieu);
                    }
                    else
                    {
                        //ViewBag.Error = "Lỗi tạo phiếu";
                        TempData["Info"] = "Lỗi tạo phiếu:" + message;
                    }
                    SoThuModel model = GetModelCreate();
                    model.Item = item;
                    model.CTPT = httt;
                    if (model.CTPT.Count == 0)
                    {
                        model.CTPT = new List<ChiTietPhieuThu>();
                        model.CTPT.Add(new ChiTietPhieuThu());
                    }
                    return View(model);
                }
            }
            catch (Exception ex)
            {
                _logger.WriteLog("SoThuController:ThuNoCreate" + ex.ToString());
                TempData["Error"] = ex;
            }
            return View();


        }
