                    model.CTPT.Add(new ChiTietPhieuThu());
                }
                return View(model);
            }
            catch (Exception ex)
            {
                _logger.WriteLog("SoThuController:ThuNoEdit" + ex.ToString());
                TempData["Error"] = ex;
            }
            return View();

