        [HttpPost]
        public ActionResult TBATSEdit(PhieuThu item, List<ChiTietPhieuThu> httt, List<ChiTietBanTaiSan> ctbts)
        {
            try
            {
                if (CurrentUser.ReadOnly == true)
                {
                    return Redirect("/Home/NoAccess");
                }
                string xml = "<Action>TBATSEdit</Action>";
                if (item != null)
                    xml += TNK.Core.Common.ConvertObjectToXMLString(item);
                if (httt != null)
                {
                    xml += Environment.NewLine + "<ThanhToan>";
                    foreach (ChiTietPhieuThu ct in httt)
                        xml += TNK.Core.Common.ConvertObjectToXMLString(ct);
                    xml += Environment.NewLine + "</ThanhToan>";
                }
                xml = "<formdata>" + Environment.NewLine + xml + Environment.NewLine + "</formdata>";
                var uid = _authenticationService.GetAuthenticatedUser().UserId;
                string sessionId = "";
                string message = _phieuThuService.UpdatePhieuThu(item, httt, ref sessionId, false, xml);
                if (string.IsNullOrEmpty(message))
                {
                    foreach (var obj in ctbts)
                    {
                        if (obj.Id == Guid.Empty)
                        {
                            obj.Id = Guid.NewGuid();
                            obj.MaPhieuThu = item.MaPhieuThu;
                            obj.IsDeleted = false;
                            obj.CreatedBy = uid;
                            obj.CreatedDate = DateTime.Now;
                            obj.UpdatedDate = DateTime.Now;
                            obj.UpdatedBy = uid;
                            _phieuThuService.InsertCTBTS(obj);
                        }
                        else
                        {
                            var result = _phieuThuService.GetCTBTS(obj.Id);
                            result.MaTaiSan = obj.MaTaiSan;
                            result.GiaBan = obj.GiaBan;
                            result.IsDeleted = obj.IsDeleted;
                            _phieuThuService.UpdateCTBTS(result);
                        }
                    }
                    string notify = _phieuThuService.XuLySauKhiUpdatePhieuThu(item.MaPhieuThu, sessionId);
                    if (string.IsNullOrEmpty(notify))
                    {
                        TempData["Info"] = "Cập nhật thành công";
                    }
                    else
                    {
                        TempData["Info"] = notify;
                    }
                }
                else
                {
                    TempData["Error"] = message;
                    ViewBag.Error = "Cập nhật thất bại:" + message;
                    _logger.WriteLog("Error TBATSEdit:" + message);
                }

                return Redirect(Request.RawUrl);
            }
            catch (Exception ex)
            {
                _logger.WriteLog("SoThuController:TBATSEdit" + ex.ToString());
                TempData["Error"] = ex;
            }
            return View();

        }

