        {
            try
            {
                _auModel.Action = "TBATSCreate";
                _auModel.Controller = "SoThu";
                var user = _userRegistrationService.getCurrentUser();

                if (CurrentUser.ReadOnly == true && !_userRegistrationService.CheckRole(_auModel)) // neu user readonly va khong duoc phan quyen tao phieu ban xe
                {
                    return Redirect("/Home/NoAccess");
                }
                ViewBag.Title = "Tạo mới Thu bán tài sản";
                string xml = "<Action>TBATSCreate</Action>";
                if (item != null)
                    xml += TNK.Core.Common.ConvertObjectToXMLString(item);
                if (httt != null)
                {
                    xml += Environment.NewLine + "<ThanhToan>";
                    foreach (ChiTietPhieuThu ct in httt)
                        xml += TNK.Core.Common.ConvertObjectToXMLString(ct);
                    xml += Environment.NewLine + "</ThanhToan>";
                }
                if (ctbts != null)
                {
                    xml += Environment.NewLine + "<ChiTietBanTaiSan>";
                    foreach (ChiTietBanTaiSan ct in ctbts)
                        xml += TNK.Core.Common.ConvertObjectToXMLString(ct);
                    xml += Environment.NewLine + "</ChiTietBanTaiSan>";
                }
                xml = "<formdata>" + Environment.NewLine + xml + Environment.NewLine + "</formdata>";
                var uid = _authenticationService.GetAuthenticatedUser().UserId;
                string message = _phieuThuService.CreatePhieuThu(item, httt, false, xml);
                if (string.IsNullOrEmpty(message))
                {
                    foreach (var obj in ctbts)
                    {
                        if (obj.Id == Guid.Empty)
                        {
                            obj.Id = Guid.NewGuid();
                            obj.MaPhieuThu = item.MaPhieuThu;
                            obj.IsDeleted = false;
                            obj.CreatedBy = uid;
                            obj.CreatedDate = DateTime.Now;
                            obj.UpdatedDate = DateTime.Now;
                            obj.UpdatedBy = uid;
                            _phieuThuService.InsertCTBTS(obj);
                        }
                        else
                        {
                            var result = _phieuThuService.GetCTBTS(obj.Id);
                            result.MaTaiSan = obj.MaTaiSan;
                            result.GiaBan = obj.GiaBan;
                            result.IsDeleted = obj.IsDeleted;
                            _phieuThuService.UpdateCTBTS(result);
                        }
                    }
                    string tempData = _soThuService.XuLySauKhiInsertPhieuThu(item.MaPhieuThu, xml);
                    if (string.IsNullOrEmpty(tempData))
                    {
                        TempData["Info"] = "Tạo mới thành công";
                    }
                    else
                    {
                        TempData["Info"] = "Lỗi tạo phiếu:" + tempData;
                    }
                    return Redirect("/Sothu/TBATSIndex");
                }
                else
                {
                    TempData["Info"] = "Lỗi tạo phiếu:" + message;
                    TempData["Error"] = "Lỗi tạo phiếu";
                }
                SoThuModel model = GetModelCreate();
                model.Item = item;
                model.Users = _userService.get();
                model.HTTT = _soThuService.GetHTTT();
                model.CTPT = httt;
                model.CTBTS = ctbts;
                return View(model);
