            string DenNgay = $"{ToDate:dd/MM/yyyy}";

            // Map: Tên cột trong DB => Tên hiển thị trong Excel
            Dictionary<string, string> columnMap = new Dictionary<string, string>();

            if (MaLoaiPhieu == "NNHBX")
            {
                    columnMap = new Dictionary<string, string>()
                {
                    { "NgayNo", "Ngày nợ" },
                    { "MaPhieu", "Mã phiếu" },
                    { "KhachHang", "Ngân hàng" },
                    { "HotenKH", "Khách hàng" },
                    { "SoHopDong", "Số hợp đồng" },
                    { "NoiDung", "Nội dung" },
                    { "SoTienNo", "Số tiền nợ" },
                    { "SoTienDaTra", "Đã thanh toán" },
                    { "SoTienConLai", "Còn nợ" },
                    { "NguoiBaoLanh", "Người bảo lãnh" },
                    { "TinhTrang", "Tình trạng" },
                    { "Sales", "Sales" },
                    { "GhiChu", "Ghi chú" }
                };
            }
            else if (MaLoaiPhieu == "NVAMU")
            {
                columnMap = new Dictionary<string, string>()
                {
                    { "NgayNo", "Ngày nợ" },
                    { "MaPhieuNo", "Mã phiếu" },
                    { "KhachHang", "Người vay" },
                    { "NoiDung", "Nội dung" },
                    { "SoTienNo", "Số tiền nợ" },
                    { "SoTienDaTra", "Đã thanh toán" },
                    { "SoTienConLai", "Còn nợ" },
                    { "NguoiBaoLanh", "Người bảo lãnh" },
                    { "TinhTrang", "Tình trạng" }
                };
            }

            // Lấy dữ liệu từ service
            var model = _phieuThuService.GetNoPhaiThuBHDVs(MaLoaiPhieu, FromDate, ToDate, Query, 1, ref total, 10000, TinhTrang, loaiBH);
            var json = JsonConvert.SerializeObject(model);
            var rawData = (DataTable)JsonConvert.DeserializeObject(json, typeof(DataTable));

            // Lọc dữ liệu theo mapping (DB column -> Excel column)
            DataTable filteredData = new DataTable();
            filteredData.Columns.Add("STT", typeof(int)); // thêm cột STT

            foreach (var kvp in columnMap)
            {
                if (rawData.Columns.Contains(kvp.Key))
                    filteredData.Columns.Add(kvp.Value, rawData.Columns[kvp.Key].DataType);
            }

            // Copy data + gán STT
            int stt = 1;
            foreach (DataRow row in rawData.Rows)
            {
                DataRow newRow = filteredData.NewRow();
                newRow["STT"] = stt++;

                foreach (var kvp in columnMap)
                {
                    if (rawData.Columns.Contains(kvp.Key))
                        newRow[kvp.Value] = row[kvp.Key];
                }
                filteredData.Rows.Add(newRow);
            }


            // Xuất Excel với filteredData
            ExportDataTableToExcel(filteredData, sheet, TuNgay, DenNgay, format);
        }

        // Xuất DataTable ra Excel
        private void ExportDataTableToExcel(DataTable data, ExcelWorksheet sheet, string TuNgay, string DenNgay, string format)
        {
            // Header
            var cellTitle = sheet.Cells[$"A1:{GetExcelColumnName(data.Columns.Count)}1"];
            cellTitle.Value = "DANH SÁCH PHIẾU NỢ";
            cellTitle.Merge = true;
            cellTitle.Style.Font.Bold = true;
            cellTitle.Style.Fill.PatternType = ExcelFillStyle.Solid;
            cellTitle.Style.Fill.BackgroundColor.SetColor(System.Drawing.Color.BurlyWood);
            cellTitle.Style.HorizontalAlignment = ExcelHorizontalAlignment.Center;
            cellTitle.Style.VerticalAlignment = ExcelVerticalAlignment.Center;

            var cellDate = sheet.Cells[$"A2:{GetExcelColumnName(data.Columns.Count)}2"];
            cellDate.Value = $"Từ ngày {TuNgay} Đến ngày {DenNgay}";
            cellDate.Merge = true;
            cellDate.Style.Font.Bold = true;
            cellDate.Style.Fill.PatternType = ExcelFillStyle.Solid;
            cellDate.Style.Fill.BackgroundColor.SetColor(System.Drawing.Color.BurlyWood);
            cellDate.Style.HorizontalAlignment = ExcelHorizontalAlignment.Center;
            cellDate.Style.VerticalAlignment = ExcelVerticalAlignment.Center;

            // Header row
            for (int i = 0; i < data.Columns.Count; i++)
            {
                var cell = sheet.Cells[$"{GetExcelColumnName(i + 1)}3"];
                cell.Value = data.Columns[i].ColumnName;
                cell.Style.Font.Bold = true;
                cell.Style.Fill.PatternType = ExcelFillStyle.Solid;
                cell.Style.Fill.BackgroundColor.SetColor(System.Drawing.Color.BurlyWood);
                cell.Style.HorizontalAlignment = ExcelHorizontalAlignment.Center;
                cell.Style.VerticalAlignment = ExcelVerticalAlignment.Center;
            }

            // Data rows
            for (int r = 0; r < data.Rows.Count; r++)
            {
                // Xuất STT ở cột A
                var sttCell = sheet.Cells[$"A{r + 4}"];
                sttCell.Value = r + 1;
                sttCell.Style.HorizontalAlignment = ExcelHorizontalAlignment.Center;

                for (int c = 0; c < data.Columns.Count; c++)
                {
                    // +1 để dịch sang cột sau STT
                    var cell = sheet.Cells[$"{GetExcelColumnName(c + 1)}{r + 4}"];
                    cell.Value = data.Rows[r][c];

                    if (data.Columns[c].DataType == typeof(double) ||
                        data.Columns[c].DataType == typeof(decimal) ||
                        data.Columns[c].DataType == typeof(float))
                    {
                        cell.Style.Numberformat.Format = format;
                        cell.Style.HorizontalAlignment = ExcelHorizontalAlignment.Right;
                    }
                    else if (data.Columns[c].DataType == typeof(DateTime))
                    {
                        cell.Style.Numberformat.Format = "dd/MM/yyyy";
                        cell.Style.HorizontalAlignment = ExcelHorizontalAlignment.Center;
                    }
                    else
                    {
                        cell.Style.HorizontalAlignment = ExcelHorizontalAlignment.Left;
                    }
                }
            }


            // Auto fit
            sheet.Cells[sheet.Dimension.Address].AutoFitColumns();
        }

        // Helper: convert số thành tên cột Excel (1->A, 27->AA)
        private string GetExcelColumnName(int columnNumber)
        {
            var dividend = columnNumber;
            string columnName = string.Empty;
            while (dividend > 0)
            {
                var modulo = (dividend - 1) % 26;
                columnName = Convert.ToChar(65 + modulo) + columnName;
                dividend = (dividend - modulo) / 26;
            }
            return columnName;
        }


