        public ActionResult Export_Excel_GiaiTrinhNBHDV(DateTime FromDate, DateTime ToDate, string Query, string TinhTrang, string DaGiaiTrinh)
        {
            string str = Server.MapPath("~\\Views\\FileMau\\FileImportGiaiTrinhNBHDV.xlsx");
            FileInfo template = new FileInfo(str);
            var excel = new ExcelPackage(template);
            DataTable tbl = _phieuThuService.XuatExcel_GiaiTrinhNBHDV(FromDate, ToDate, Query, TinhTrang, DaGiaiTrinh);
            tbl.Columns.Add("STT");
            string strFileName = "Danh_Sach_GiaiTrinhNBHDV" + DateTime.Now.ToString("ddMMyyyyHHmm") + ".xls";
            List<string> lstCol = new List<string>();
            lstCol.Add("STT");
            lstCol.Add("MAPHIEUNO");
            lstCol.Add("KHACHHANG");
            lstCol.Add("HOTEN");
            lstCol.Add("BIENSO");
            lstCol.Add("SOHOPDONG");

            lstCol.Add("GIAITRINH");

            int stt = 0;
            //sap xep lai thu tu cot
            for (int i = 0; i < lstCol.Count; i++)
            {
                tbl.Columns[lstCol[i]].SetOrdinal(i);
            }
            for (int i = tbl.Columns.Count - 1; i >= lstCol.Count; i--)
            {
                tbl.Columns.RemoveAt(i);
            }

            foreach (DataRow row in tbl.Rows)
            {
                stt++;
                row["STT"] = stt;
            }

            excel.Workbook.Worksheets["Sheet1"].Cells["A4"].LoadFromDataTable(tbl, false);
            return new ExcelInsuranceDownload(excel, strFileName);
        }
