        [HttpPost]
        public ActionResult TCONOEdit(PhieuThu item, List<ChiTietPhieuThu> httt, string submit, string ChuoiUpdatedDate)
        {
            try
            {
                if (CurrentUser.ReadOnly == true)
                {
                    return Redirect("/Home/NoAccess");
                }
                ViewBag.Type = item.MaLoaiPhieu;
                string xml = "<Action>TCONOEdit</Action>";
                if (item != null)
                    xml += TNK.Core.Common.ConvertObjectToXMLString(item);
                if (httt != null)
                {
                    xml += Environment.NewLine + "<ThanhToan>";
                    foreach (ChiTietPhieuThu ct in httt)
                        xml += TNK.Core.Common.ConvertObjectToXMLString(ct);
                    xml += Environment.NewLine + "</ThanhToan>";
                }
                xml = "<formdata>" + Environment.NewLine + xml + Environment.NewLine + "</formdata>";
                //ViewBag.Alert = TempData["Alert"];
                ViewBag.Title = "Thu nợ";
                string sessionId = "";
                string message = _phieuThuService.UpdatePhieuThu(item, httt, ref sessionId, false);
                if (string.IsNullOrEmpty(message))
                {
                    //xu ly sai khi update phieu thu
                    string result = _phieuThuService.XuLySauKhiUpdatePhieuThu(item.MaPhieuThu, sessionId, xml);
                    if (string.IsNullOrEmpty(result))
                    {
                        TempData["Info"] = "Cập nhật thành công";
                    }
                    else
                    {
                        TempData["Info"] = result;
                    }
                    return Redirect("/SoThu/TCONOIndex");
                }
                else
                {
                    _logger.WriteLog("Error TCONOEdit:" + message);
                    ViewBag.Error = "Cập nhật thất bại:" + message;
                    TempData["Error"] = "Cập nhật thất bại: " + message;
                    return Redirect("/SoThu/TCONOIndex/" + item.MaPhieuThu);
                }
                //SoThuModel model = GetModelEdit(item.MaPhieuThu);
                //model.CTPT = httt;
                //if (model.CTPT.Count == 0)
                //{
                //    model.CTPT = new List<ChiTietPhieuThu>();
                //    model.CTPT.Add(new ChiTietPhieuThu());
                //}
                return View();
            }
            catch (Exception ex)
            {
                _logger.WriteLog("SoThuController:TCONOEdit" + ex.ToString());
                TempData["Error"] = ex;
            }
            return View();
        }
        public JsonResult DanhSachCongNo(string maPhieuThu, string Id)
        {
            var list = new List<PhieuThu>();
            if (Id != "")
            {
                List<PhieuThu> items = _phieuThuService.GetCongNo(maPhieuThu, Id);
                if (maPhieuThu == "")
                    list = items.Where(x => x.MaPhieuThu != null && x.TongCong > 0).ToList();
                else
                    list = items.Where(x => x.MaPhieuThu != null && (x.SoTienThu > 0 || x.TongCong > 0)).ToList();
            }
            return Json(list, JsonRequestBehavior.AllowGet);
        }
