        public ActionResult ExportFile_GHBH()
        {
            string strFileName = "FileImportGHBH.xlsx";
            //return File(strFileName, "application/vnd.ms-excel", "FileImportGHBH.xlsx");
            var httt = _soThuService.GetHTTT().Select(x => x.MaNganHang).Distinct().ToList();
            var doiTac = _soThuService.GetDoiTac("NCC");
            string str = Server.MapPath("~\\Views\\FileMau\\" + strFileName);
            FileInfo template = new FileInfo(str);
            ExcelPackage _pck = new ExcelPackage(new FileInfo(str));

            var sheet = _pck.Workbook.Worksheets["DanhMuc_NganHang"];
            sheet.Cells["A1"].LoadFromCollection(httt, false);

            sheet = _pck.Workbook.Worksheets["DanhMuc_CtyTH"];
            sheet.Cells["A1"].LoadFromCollection(doiTac.Select(s => s.MaDoiTac), false);
            return new ExcelInsuranceDownload(_pck, strFileName);
        }
