        public ActionResult ExportDataCyber(DateTime from, DateTime to, string query)
        {
            try
            {
                var httt = _soThuService.GetHTTT().Select(x => x.MaNganHang).Distinct().ToList();
                var NCC = _soThuService.GetDoiTac("BH").Select(x => x.MaDoiTac).Distinct().ToList();
                string strFileName = Server.MapPath("~\\Views\\FileMau\\FileImportDichVuCyber.xlsx");
                ExcelPackage pck = new ExcelPackage(new FileInfo(strFileName));
                var sheet = pck.Workbook.Worksheets["DanhMuc_NganHang"];
                sheet.Cells["A2"].LoadFromCollection(httt, false);
                var sheet2 = pck.Workbook.Worksheets["DanhMuc_CtyBH"];
                sheet2.Cells["A1"].LoadFromCollection(NCC, false);
                List<PhieuDVTamCyber> lstPhieuDVCyber = _phieuThuService.GetPDVT(from, to, 1, ref total, 1000, query);
                DataTable tblChiTietPhieuDVCyber = _phieuThuService.GetListCTPDVTCybers(from, to, query);
                DataTable tblImport = new DataTable("DataImport");
                tblImport.Columns.Add("STT");
                tblImport.Columns.Add("Soquyettoan");
                tblImport.Columns.Add("Ngayquyettoan");
                tblImport.Columns.Add("Ngaythutien");
                tblImport.Columns.Add("Bienso");
                tblImport.Columns.Add("TenKhachHang");
                tblImport.Columns.Add("Loaixe");
                tblImport.Columns.Add("SoKhung");
                tblImport.Columns.Add("Dienthoai");
                tblImport.Columns.Add("Diachi");
                tblImport.Columns.Add("Sohoadon");
                tblImport.Columns.Add("Chungtulienquan");
                tblImport.Columns.Add("SoTienPhaiTra", typeof(float));
                tblImport.Columns.Add("Hoahongtaixe", typeof(float));
                tblImport.Columns.Add("Nguoiduyethoahong");
                tblImport.Columns.Add("CongnoHonda", typeof(float));
                tblImport.Columns.Add("Congtybaohiem");
                tblImport.Columns.Add("Sotienthanhtoanbaohiem", typeof(float));
                tblImport.Columns.Add("Nganhang1");
                tblImport.Columns.Add("HTTT1");
                tblImport.Columns.Add("Sotien1", typeof(float));
                tblImport.Columns.Add("Sothamchieu1");
                tblImport.Columns.Add("Treotien1");
                tblImport.Columns.Add("Nganhang2");
                tblImport.Columns.Add("HTTT2");
                tblImport.Columns.Add("Sotien2", typeof(float));
                tblImport.Columns.Add("Sothamchieu2");
                tblImport.Columns.Add("Treotien2");
                tblImport.Columns.Add("Nganhang3");
                tblImport.Columns.Add("HTTT3");
                tblImport.Columns.Add("Sotien3", typeof(float));
                tblImport.Columns.Add("Sothamchieu3");
                tblImport.Columns.Add("Treotien");
                tblImport.Columns.Add("Nguoibaolanh");
                tblImport.Columns.Add("Ghichu");
                tblImport.Columns.Add("Nguoithutien");
                tblImport.Columns.Add("CyberId");
                tblImport.Columns.Add("Loi");
                for (int i = 0; i < lstPhieuDVCyber.Count; i++)
                {
                    DataRow r = tblImport.NewRow();
                    r["STT"] = i + 1;
                    r["SoQuyetToan"] = lstPhieuDVCyber[i].REPAIRORDERNO;
                    r["Ngayquyettoan"] = lstPhieuDVCyber[i].RO_DATE;
                    r["Ngaythutien"] = lstPhieuDVCyber[i].NgayThu;
                    r["Bienso"] = lstPhieuDVCyber[i].REGISTERNO;
                    r["TenKhachHang"] = lstPhieuDVCyber[i].CAROWNERNAME;
                    r["Loaixe"] = lstPhieuDVCyber[i].CM_NAME;
                    r["SoKhung"] = lstPhieuDVCyber[i].FRAMENO;
                    r["Dienthoai"] = lstPhieuDVCyber[i].CAROWNERTEL;
                    r["Diachi"] = lstPhieuDVCyber[i].CAROWNERADD;
                    r["Sohoadon"] = lstPhieuDVCyber[i].INVOICE;
                    r["Chungtulienquan"] = lstPhieuDVCyber[i].REPAIRORDERNO;
                    r["SoTienPhaiTra"] = lstPhieuDVCyber[i].TongCong;
                    r["Hoahongtaixe"] = lstPhieuDVCyber[i].DRIVERREMUNERATION;
                    r["Nguoiduyethoahong"] = "";
                    r["CongnoHonda"] = 0;
                    r["Congtybaohiem"] = lstPhieuDVCyber[i].InsuranceCompany;
                    r["Sotienthanhtoanbaohiem"] = lstPhieuDVCyber[i].PaymentInsurance;
                   
                    //KH thanh toan
                    /*
                        {CK,,2054000}{TM,QuyChinh,201}
                        {TM,QuyChinh,833250}
                      {CT,,1438320}

                     */

                    string paymentCustomer = lstPhieuDVCyber[i].PAYMENTCUSTOMERS;
                    string[] objectStrings = paymentCustomer.Split(new string[] { "}{" }, StringSplitOptions.None);
                    int countHttt = 1;
                    //dua vao toi da 3 hinh thuc thanh toan
                    foreach (string s in objectStrings)
                    {
                        string cleanString = s.Trim(new char[] { '{', '}' });
                        string[] fields = cleanString.Split(new char[] { ',' }, StringSplitOptions.None);
                        if (fields.Length >= 3)
                        {
                            try
                            {
                                // Split the object string into fields
                                if (countHttt <= 3)
                                {
                                    r["HTTT" + countHttt] = fields[0];
                                    r["Nganhang" + countHttt] = fields[1];
                                    r["Sotien" + countHttt] = float.Parse(fields[2]);
                                }
                                countHttt++;
                            }
                            catch (Exception ex)
                            {
                                _logger.WriteLog(ex.ToString());
                            }
                        }
                    }
                    if (r["Sotien1"].ToString() == "")
                        r["Sotien1"] = 0;
                    if (r["Sotien2"].ToString() == "")
                        r["Sotien2"] = 0;
                    if (r["Sotien3"].ToString() == "")
                        r["Sotien3"] = 0;
                    r["Nguoibaolanh"] = "";
                    r["Ghichu"] = "";
                    r["NguoiThuTien"] = CurrentUser.UserName;
                    r["CyberId"] = lstPhieuDVCyber[i].REPAIRORDERNO;
                    if (float.Parse(r["SoTienPhaiTra"].ToString())
                            - float.Parse(r["Sotienthanhtoanbaohiem"].ToString())
                            - float.Parse(r["Sotien1"].ToString())
                            - float.Parse(r["Sotien2"].ToString())
                            - float.Parse(r["Sotien3"].ToString())
                            < 0
                    )
                        r["Loi"] = "Số tiền thanh toán>Số tiền cần thu";
                    tblImport.Rows.Add(r);
                }
                if (tblImport.Rows.Count > 0)
                {
                    var sheet3 = pck.Workbook.Worksheets["TongHop"];
                    //sheet3.Cells["A2:AJ" + (tblImport.Rows.Count+1)].Style.Border.BorderAround(ExcelBorderStyle.Thin);
                    if (tblImport.Rows.Count > 1)//da co san 1 dong trong excel nen neu nhieu hon 1 dong thi moi insert them
                    {
                        sheet3.InsertRow(3, tblImport.Rows.Count - 1, 2);
                        sheet3.DeleteRow(3 + tblImport.Rows.Count, 1); //xoa dong cuoi cung de khi import khong bi dinh du lieu
                    }
                    sheet3.Cells["A2"].LoadFromDataTable(tblImport, false);
                    var sheet4 = pck.Workbook.Worksheets["ChiTietDichVu"];
                    if (tblChiTietPhieuDVCyber.Rows.Count > 1)//da co san 1 dong trong excel nen neu nhieu hon 1 dong thi moi insert them
                    {
                        sheet4.InsertRow(3, tblChiTietPhieuDVCyber.Rows.Count - 1, 2);
                        sheet4.DeleteRow(3 + tblChiTietPhieuDVCyber.Rows.Count, 1); //xoa dong cuoi cung de khi import khong bi dinh du lieu
                    }
                    if(tblChiTietPhieuDVCyber.Rows.Count>0)
                        sheet4.Cells["A2"].LoadFromDataTable(tblChiTietPhieuDVCyber, false);
                    // sheet4.Cells["A2:I" + (tblChiTietPhieuDVCyber.Rows.Count + 1)].Style.Border.Se
                   
                }
                return new ExcelInsuranceDownload(pck, "FileImportDichVu.xlsx");

            }
            catch (Exception ex)
            {
                log.Error(ex);
                return Json(new
                {
                    IsError = true,
                    Message = ex.Message
                }) ;
            }

        }
