        public ActionResult ImportData()
        {
            if (CurrentUser.ReadOnly == true)
            {
                return Redirect("/Home/NoAccess");
            }
            string error = "";

            try
            {
                Hashtable hshCol = new Hashtable();
                hshCol.Add("STT", 1);
                hshCol.Add("Số chứng từ", 0);
                hshCol.Add("Ngày thu", 0);
                hshCol.Add("Họ tên khách hàng", 0);
                hshCol.Add("Công ty BH", 0);
                hshCol.Add("Số hợp đồng", 0);
                hshCol.Add("Biển số/Số khung", 0);
                hshCol.Add("Thực bán", 0);
                hshCol.Add("Tiền trả BH", 0);
                hshCol.Add("Hoa hồng", 0);
                hshCol.Add("Nội dung", 0);
                hshCol.Add("Ghi chú", 0);
                hshCol.Add("Ngân hàng", 0);
                hshCol.Add("HTTT", 0);
                hshCol.Add("Số tiền", 0);
                hshCol.Add("Số tham chiếu", 0);
                hshCol.Add("Treo tiền", 0);
                hshCol.Add("Người thu tiền", 0);
                hshCol.Add("Tái tục", 0);
                List<PhieuThu> lstPhieuThu = new List<Core.Domain.PhieuThu>();
                List<ChiTietPhieuThu> lstChiTietPhieuThu = new List<ChiTietPhieuThu>();

                foreach (string file in Request.Files)
                {
                    var fileContent = Request.Files[file];
                    if (fileContent != null && fileContent.ContentLength > 0)
                    {
                        Stream stream = fileContent.InputStream;
                        using (var package = new ExcelPackage(stream))
                        {
                            var workBook = package.Workbook;
                            if (workBook != null)
                            {
                                if (workBook.Worksheets.Count > 0)
                                {
                                    var ws = workBook.Worksheets[1];
                                    if (ws.Dimension.End.Row < 2)
                                    {
                                        return Json(new { IsError = true, Message = "Không có dữ liệu để import" }, JsonRequestBehavior.AllowGet);
                                    }

                                    #region Kiểm tra file đúng định dạng
                                    bool IsFormat = true;
                                    int beginRowNum = 1;
                                    for (int ii = 1; ii <= 20; ii++)
                                    {
                                        if (ws.Cells[beginRowNum, ii].Value != null)
                                        {
                                            if (ws.Cells[beginRowNum, ii].Value.ToString().Trim().ToUpper().Equals("STT"))
                                                hshCol["STT"] = ii;
                                            if (ws.Cells[beginRowNum, ii].Value.ToString().Trim().Equals("Số chứng từ"))
                                                hshCol["Số chứng từ"] = ii;
                                            if (ws.Cells[beginRowNum, ii].Value.ToString().Trim().Equals("Ngày thu"))
                                                hshCol["Ngày thu"] = ii;
                                            if (ws.Cells[beginRowNum, ii].Value.ToString().Trim().Equals("Họ tên khách hàng"))
                                                hshCol["Họ tên khách hàng"] = ii;
                                            if (ws.Cells[beginRowNum, ii].Value.ToString().Trim().Equals("Công ty BH"))
                                                hshCol["Công ty BH"] = ii;
                                            if (ws.Cells[beginRowNum, ii].Value.ToString().Trim().Equals("Số hợp đồng"))
                                                hshCol["Số hợp đồng"] = ii;
                                            if (ws.Cells[beginRowNum, ii].Value.ToString().Trim().Equals("Biển số/Số khung"))
                                                hshCol["Biển số/Số khung"] = ii;
                                            if (ws.Cells[beginRowNum, ii].Value.ToString().Trim().Equals("Thực bán"))
                                                hshCol["Thực bán"] = ii;
                                            if (ws.Cells[beginRowNum, ii].Value.ToString().Trim().Equals("Tiền trả BH"))
                                                hshCol["Tiền trả BH"] = ii;
                                            if (ws.Cells[beginRowNum, ii].Value.ToString().Trim().Equals("Hoa hồng"))
                                                hshCol["Hoa hồng"] = ii;
                                            if (ws.Cells[beginRowNum, ii].Value.ToString().Trim().Equals("Nội dung"))
                                                hshCol["Nội dung"] = ii;
                                            if (ws.Cells[beginRowNum, ii].Value.ToString().Trim().Equals("Ghi chú"))
                                                hshCol["Ghi chú"] = ii;
                                            if (ws.Cells[beginRowNum, ii].Value.ToString().Trim().Equals("Ngân hàng"))
                                                hshCol["Ngân hàng"] = ii;
                                            if (ws.Cells[beginRowNum, ii].Value.ToString().Trim().Equals("HTTT"))
                                                hshCol["HTTT"] = ii;
                                            if (ws.Cells[beginRowNum, ii].Value.ToString().Trim().Equals("Số tiền"))
                                                hshCol["Số tiền"] = ii;
                                            if (ws.Cells[beginRowNum, ii].Value.ToString().Trim().Equals("Số tham chiếu"))
                                                hshCol["Số tham chiếu"] = ii;
                                            if (ws.Cells[beginRowNum, ii].Value.ToString().Trim().Equals("Treo tiền"))
                                                hshCol["Treo tiền"] = ii;
                                            if (ws.Cells[beginRowNum, ii].Value.ToString().Trim().Equals("Người thu tiền"))
                                                hshCol["Người thu tiền"] = ii;
                                            if (ws.Cells[beginRowNum, ii].Value.ToString().Trim().Equals("Tái tục"))
                                                hshCol["Tái tục"] = ii;
                                        }

                                    }
                                    //neu co cot khong ton tai trong danh sach cot can thiet thi canh bao sai dinh dang
                                    foreach (DictionaryEntry o in hshCol)
                                        if (o.Value.ToString() == "0")
                                        {
                                            return Json(new { IsError = true, Message = "File excel thiếu cột " + o.Key.ToString() + ". Vui lòng kiểm tra lại." }, JsonRequestBehavior.AllowGet);
                                        }
                                    #endregion

                                    #region Add dữ liệu
                                    int indexSTT = (int)hshCol["STT"];
                                    int indexSoChungTu = (int)hshCol["Số chứng từ"];
                                    int indexNgayThu = (int)hshCol["Ngày thu"];
                                    int indexHoTenKH = (int)hshCol["Họ tên khách hàng"];
                                    int indexCTYBH = (int)hshCol["Công ty BH"];
                                    int indexSHD = (int)hshCol["Số hợp đồng"];
                                    int indexBienSo = (int)hshCol["Biển số/Số khung"];
                                    int indexThucBan = (int)hshCol["Thực bán"];
                                    int indexTienTraBH = (int)hshCol["Tiền trả BH"];
                                    int indexHoaHong = (int)hshCol["Hoa hồng"];
                                    int indexNoiDung = (int)hshCol["Nội dung"];
                                    int indexGhiChu = (int)hshCol["Ghi chú"];
                                    int indexNganHang = (int)hshCol["Ngân hàng"];
                                    int indexHTTT = (int)hshCol["HTTT"];
                                    int indexSoTien = (int)hshCol["Số tiền"];
                                    int indexSoThamChieu = (int)hshCol["Số tham chiếu"];
                                    int indexTreoTien = (int)hshCol["Treo tiền"];
                                    int indexNguoiThuTien = (int)hshCol["Người thu tiền"];
                                    int indexTaiTuc = (int)hshCol["Tái tục"];
                                    //kiem tra rang buoc tien trong hang tren duong con du thi moi import
                                    double tongTien = 0;
                                    for (var rowNum = beginRowNum + 1; rowNum <= ws.Dimension.End.Row; rowNum++)
                                    {
                                        try
                                        {
                                            string STT = ws.Cells[rowNum, indexSTT].Value == null ? "" : ws.Cells[rowNum, indexSTT].Value.ToString();
                                            if (!string.IsNullOrEmpty(STT) && STT != "")
                                            {
                                                string THUCBAN = ws.Cells[rowNum, indexThucBan].Value == null ? "" : ws.Cells[rowNum, indexThucBan].Value.ToString();
                                                string TIENTRABAOHIEM = ws.Cells[rowNum, indexTienTraBH].Value == null ? "" : ws.Cells[rowNum, indexTienTraBH].Value.ToString();
                                                string HOAHONG = ws.Cells[rowNum, indexHoaHong].Value == null ? "" : ws.Cells[rowNum, indexHoaHong].Value.ToString();
                                                string SOTIEN = ws.Cells[rowNum, indexSoTien].Value == null ? "" : ws.Cells[rowNum, indexSoTien].Value.ToString();
                                                string TaiTuc = ws.Cells[rowNum, indexTaiTuc].Value == null ? "" : ws.Cells[rowNum, indexTaiTuc].Value.ToString();
                                                string SoHD = ws.Cells[rowNum, indexSHD].Value == null ? "" : ws.Cells[rowNum, indexSHD].Value.ToString();
                                                string SoKhung = ws.Cells[rowNum, indexBienSo].Value == null ? "" : ws.Cells[rowNum, indexBienSo].Value.ToString();
                                                if (string.IsNullOrEmpty(TaiTuc))
                                                    TaiTuc = "CXD";
                                                if (!string.IsNullOrEmpty(TaiTuc) && TaiTuc.ToUpper() != "CXD" && TaiTuc.ToUpper() != "TT" && TaiTuc.ToUpper() != "KM")
                                                {
                                                    error = "Dòng " + (rowNum - 1) + " cột tái tục phải là trống hoặc TT hoặc KM.";
                                                    break;
                                                }
                                                if (!string.IsNullOrEmpty(SoHD) && string.IsNullOrEmpty(SoKhung) && float.Parse(THUCBAN) == 0)
                                                {
                                                    error = "Dòng " + (rowNum - 1) + " bảo hiểm khuyến mãi không được để trống số khung khi đã có số hợp đồng.";
                                                    break;
                                                }
                                                if (!TNK.Core.Common.IsNumeric(THUCBAN))
                                                {
                                                    error = "Dòng " + (rowNum - 1) + " thực bán (" + THUCBAN + ") không phải là kiểu số.";
                                                    break;
                                                }
                                                if (!TNK.Core.Common.IsNumeric(TIENTRABAOHIEM))
                                                {
                                                    error = "Dòng " + (rowNum - 1) + " tiền trả bảo hiểm (" + TIENTRABAOHIEM + ") không phải là kiểu số.";
                                                    break;
                                                }
                                                if (!TNK.Core.Common.IsNumeric(HOAHONG))
                                                {
                                                    error = "Dòng " + (rowNum - 1) + " hoa hồng (" + HOAHONG + ") không phải là kiểu số.";
                                                    break;
                                                }
                                                if (!TNK.Core.Common.IsNumeric(SOTIEN))
                                                {
                                                    error = "Dòng " + (rowNum - 1) + " số tiền (" + SOTIEN + ") không phải là kiểu số.";
                                                    break;
                                                }

                                            }
                                        }
                                        catch (Exception e)
                                        {
                                            error += e;

                                        }
                                    }
                                    if (string.IsNullOrEmpty(error))
                                    {
                                        //TuiDinhKhoan tdk = new TuiDinhKhoan(); /*_tuiDinhKhoanService.GetTuiDinhKhoan(maTui);*/
                                        for (var rowNum = beginRowNum + 1; rowNum <= ws.Dimension.End.Row; rowNum++)
                                        {
                                            try
                                            {
                                                //DataRow row = dtb.NewRow();
                                                DateTime NGAYTHU = new DateTime();
                                                string ngayThu = ws.Cells[rowNum, indexNgayThu].Value == null ? "" : ws.Cells[rowNum, indexNgayThu].Value.ToString();
                                                if (TNK.Core.Common.IsDate(ngayThu) == false)
                                                {
                                                    if (TNK.Core.Common.IsNumeric(ngayThu))
                                                    {
                                                        double DATE = double.Parse(ngayThu);
                                                        NGAYTHU = DateTime.FromOADate(DATE);
                                                    }
                                                }
                                                else
                                                    NGAYTHU = Convert.ToDateTime(ngayThu);
                                                if (NGAYTHU.Year > 2000)
                                                {
                                                    string SoChungTu = ws.Cells[rowNum, indexSoChungTu].Value == null ? "" : ws.Cells[rowNum, indexSoChungTu].Value.ToString();
                                                    string NgayThu = ws.Cells[rowNum, indexNgayThu].Value == null ? "" : ws.Cells[rowNum, indexNgayThu].Value.ToString();
                                                    string HoTenKH = ws.Cells[rowNum, indexHoTenKH].Value == null ? "" : ws.Cells[rowNum, indexHoTenKH].Value.ToString();
                                                    string CTYBH = ws.Cells[rowNum, indexCTYBH].Value == null ? "" : ws.Cells[rowNum, indexCTYBH].Value.ToString();
                                                    string SHD = ws.Cells[rowNum, indexSHD].Value == null ? "" : ws.Cells[rowNum, indexSHD].Value.ToString();
                                                    string BienSo = ws.Cells[rowNum, indexBienSo].Value == null ? "" : ws.Cells[rowNum, indexBienSo].Value.ToString();
                                                    string ThucBan = ws.Cells[rowNum, indexThucBan].Value == null ? "" : ws.Cells[rowNum, indexThucBan].Value.ToString();
                                                    string TienTraBH = ws.Cells[rowNum, indexTienTraBH].Value == null ? "" : ws.Cells[rowNum, indexTienTraBH].Value.ToString();

                                                    string HoaHong = ws.Cells[rowNum, indexHoaHong].Value == null ? "" : ws.Cells[rowNum, indexHoaHong].Value.ToString();
                                                    string NoiDung = ws.Cells[rowNum, indexNoiDung].Value == null ? "" : ws.Cells[rowNum, indexNoiDung].Value.ToString();
                                                    string GhiChu = ws.Cells[rowNum, indexGhiChu].Value == null ? "" : ws.Cells[rowNum, indexGhiChu].Value.ToString();
                                                    string NganHang = ws.Cells[rowNum, indexNganHang].Value == null ? "" : ws.Cells[rowNum, indexNganHang].Value.ToString();
                                                    string HTTT = ws.Cells[rowNum, indexHTTT].Value == null ? "" : ws.Cells[rowNum, indexHTTT].Value.ToString();
                                                    string SoTien = ws.Cells[rowNum, indexSoTien].Value == null ? "" : ws.Cells[rowNum, indexSoTien].Value.ToString();
                                                    string SoThamChieu = ws.Cells[rowNum, indexSoThamChieu].Value == null ? "" : ws.Cells[rowNum, indexSoThamChieu].Value.ToString();
                                                    string TreoTien = ws.Cells[rowNum, indexTreoTien].Value == null ? "" : ws.Cells[rowNum, indexTreoTien].Value.ToString();
                                                    string NguoiThuTien = ws.Cells[rowNum, indexNguoiThuTien].Value == null ? "" : ws.Cells[rowNum, indexNguoiThuTien].Value.ToString();
                                                    string TaiTuc = ws.Cells[rowNum, indexTaiTuc].Value == null ? "" : ws.Cells[rowNum, indexTaiTuc].Value.ToString();
                                                    if (string.IsNullOrEmpty(TaiTuc))
                                                        TaiTuc = "CXD";
                                                    HTTT = HTTT.ToUpper();
                                                    if (string.IsNullOrEmpty(SoChungTu))
                                                    {
                                                        error += Environment.NewLine + "Dòng " + (rowNum - 1) + " không có số chứng từ.";
                                                        break;
                                                    }
                                                    if (string.IsNullOrEmpty(CTYBH))
                                                    {
                                                        error += Environment.NewLine + "Dòng " + (rowNum - 1) + " (" + SoChungTu + ")  không có công ty bảo hiểm.";
                                                        break;
                                                    }
                                                    else
                                                    {
                                                        bool flag = _doiTacService.getCTBHById(CTYBH);
                                                        if (flag == false)
                                                        {
                                                            error += Environment.NewLine + "Dòng " + (rowNum - 1) + " (" + SoChungTu + ") không có công ty bảo hiểm trong danh mục.";
                                                            break;
                                                        }
                                                    }
                                                    if (string.IsNullOrEmpty(NguoiThuTien))
                                                    {
                                                        error += Environment.NewLine + "Dòng " + (rowNum - 1) + " (" + SoChungTu + ") không có người thu tiền.";
                                                        break;
                                                    }
                                                    if (Convert.ToDouble(ThucBan) != Convert.ToDouble(SoTien))
                                                    {
                                                        error += Environment.NewLine + "Dòng " + (rowNum - 1) + " (" + SoChungTu + ") thực bán khác số tiền thanh toán.";
                                                        break;
                                                    }
                                                    if (HTTT == "TM" && NganHang != "QuyChinh" && NganHang != "QuyPhu")
                                                    {
                                                        error += Environment.NewLine + "Dòng " + (rowNum - 1) + " (" + SoChungTu + ") sai hình thức thanh toán ";
                                                        break;
                                                    }
                                                    if (HTTT != "TM" && (NganHang == "QuyChinh" || NganHang == "QuyPhu"))
                                                    {
                                                        error += Environment.NewLine + "Dòng " + (rowNum - 1) + " (" + SoChungTu + ") sai hình thức thanh toán";
                                                        break;
                                                    }
                                                    if (HTTT == "CK" && (NganHang == "QuyChinh" || NganHang == "QuyPhu"))
                                                    {
                                                        error += Environment.NewLine + "Dòng " + (rowNum - 1) + " (" + SoChungTu + ") sai hình thức thanh toán";
                                                        break;
                                                    }
                                                    if (Convert.ToDouble(ThucBan) > 0 && (string.IsNullOrEmpty(NganHang) || string.IsNullOrEmpty(HTTT)))
                                                    {
                                                        error += Environment.NewLine + "Dòng " + (rowNum - 1) + " (" + SoChungTu + ") vui lòng nhập đủ thông tin thanh toán(ngân hàng, HTTT,số tiền).";
                                                        break;
                                                    }
                                                    PhieuThu item = new PhieuThu();
                                                    item.SoChungTu = SoChungTu;
                                                    if (!_phieuThuService.KiemTraTonTaiChungTu(item.SoChungTu))
                                                    {
                                                        error += Environment.NewLine + "Dòng " + (rowNum - 1) + " (" + SoChungTu + ") bị trùng số chứng từ";
                                                        break;
                                                    }
                                                    item.NgayThu = Convert.ToDateTime(NgayThu);
                                                    item.HoTen = HoTenKH;
                                                    item.CTBH = CTYBH;
                                                    item.SoHopDong = SHD;
                                                    item.BienSo = BienSo;
                                                    item.TienTraBH = Convert.ToDouble(TienTraBH);
                                                    item.HoaHong = Convert.ToDouble(HoaHong);
                                                    item.NoiDung = NoiDung;
                                                    item.GhiChu = GhiChu;
                                                    item.TongCong = Convert.ToDouble(SoTien);
                                                    item.IsActive = true;
                                                    item.IsDeleted = false;
                                                    item.MaLoaiPhieu = "TBAHI";
                                                    item.GiaBan = item.TienTraBH + item.HoaHong;
                                                    item.GiaVon = item.TienTraBH + item.HoaHong;
                                                    item.GiamGia = item.GiaBan - Convert.ToDouble(ThucBan);
                                                    item.LoaiBaoHiem = TaiTuc;
                                                    User us = _userService.getByUserName(NguoiThuTien);
                                                    if (us != null)
                                                        item.NguoiThuTien = us.UserId;
                                                    else
                                                    {
                                                        error += Environment.NewLine + "Dòng " + (rowNum - 1) + " (" + SoChungTu + ") không tìm thấy người thu tiền " + NguoiThuTien;
                                                        break;
                                                    }
                                                    //phan httt
                                                    List<ChiTietPhieuThu> CTPT = new List<ChiTietPhieuThu>();
                                                    CTPT.Add(new ChiTietPhieuThu());
                                                    HTTT = HTTT.ToUpper();
                                                    if (!string.IsNullOrEmpty(HTTT) && HTTT != "CK" && HTTT != "CT" && HTTT != "TM")
                                                    {
                                                        error += Environment.NewLine + "Dòng " + (rowNum - 1) + " (" + SoChungTu + ") sai hình thức thanh toán";
                                                        break;
                                                    }
                                                    CTPT[0].HinhThucThanhToan = HTTT;
                                                    CTPT[0].MaNganHang = NganHang;
                                                    if (TreoTien == "1")
                                                        CTPT[0].TinhTrang = true;
                                                    else
                                                        CTPT[0].TinhTrang = false;
                                                    if (!_doiTacService.getDoiTacById(NganHang) && NganHang != "QuyChinh" && NganHang != "QuyPhu" && !string.IsNullOrEmpty(NganHang))
                                                    {
                                                        error += Environment.NewLine + "Dòng " + (rowNum - 1) + " (" + SoChungTu + ") không tìm thấy ngân hàng " + NganHang;
                                                        break;
                                                    }
                                                    CTPT[0].SoThamChieu = SoThamChieu;
                                                    CTPT[0].SoTienThanhToan = Convert.ToDouble(SoTien);
                                                    CTPT[0].Temp = NganHang + "-" + HTTT;

                                                    lstPhieuThu.Add(item);
                                                    lstChiTietPhieuThu.Add(CTPT[0]);

                                                    //string xml = "<Action>PhieuThu</Action>";
                                                    //xml += Environment.NewLine + "<submit>Import từ excel</submit>";
                                                    //if (item != null)
                                                    //    xml += TNK.Core.Common.ConvertObjectToXMLString(item);
                                                    //if (CTPT != null)
                                                    //{
                                                    //    xml += Environment.NewLine + "<ThanhToan>";
                                                    //    foreach (ChiTietPhieuThu ct in CTPT)
                                                    //        xml += TNK.Core.Common.ConvertObjectToXMLString(ct);
                                                    //    xml += Environment.NewLine + "</ThanhToan>";
                                                    //}
                                                    //string message = _phieuThuService.CreatePhieuThu(item, CTPT, true, xml);
                                                    //if (message != "")
                                                    //    error += Environment.NewLine + "Dòng " + (rowNum - 1) + "(" + SoChungTu + "):" + message;
                                                    //else
                                                    //{
                                                    //    error += Environment.NewLine + "Dòng " + (rowNum - 1) + ": Vui lòng nhập số chứng từ." ;
                                                    //}
                                                }
                                                else
                                                    error += Environment.NewLine + "Dòng " + (rowNum - 1) + ": Sai định dạng ngày thu. Vui lòng kiểm tra lại.";
                                            }
                                            catch (Exception exx)
                                            {
                                                error += Environment.NewLine + "Dòng " + (rowNum - 1) + ": " + exx;
                                            }
                                        }
                                    }

                                    if (string.IsNullOrEmpty(error))
                                    {
                                        for (int i = 0; i < lstPhieuThu.Count; i++)
                                        {
                                            PhieuThu item = lstPhieuThu[i];
                                            List<ChiTietPhieuThu> CTPT = new List<ChiTietPhieuThu>();
                                            CTPT.Add(lstChiTietPhieuThu[i]);
                                            string xml = "<formdata><Action>PhieuThu</Action>";
                                            xml += Environment.NewLine + "<submit>Import từ excel</submit>";
                                            if (item != null)
                                                xml += TNK.Core.Common.ConvertObjectToXMLString(item);
                                            if (CTPT != null)
                                            {
                                                xml += Environment.NewLine + "<ThanhToan>";
                                                foreach (ChiTietPhieuThu ct in CTPT)
                                                    xml += TNK.Core.Common.ConvertObjectToXMLString(ct);
                                                xml += Environment.NewLine + "</ThanhToan>";
                                            }
                                            xml += "</formdata>";
                                            string message = _phieuThuService.CreatePhieuThu(item, CTPT, false, xml);
                                            _phieuThuService.XuLySauKhiInsertPhieuThu(item.MaPhieuThu, xml);
                                            if (message != "")
                                                error += Environment.NewLine + "Dòng " + (i + 1) + "(" + item.SoChungTu + "):" + message;
                                        }
                                    }
                                    #endregion
                                }
                            }
                        }
                    }

                }
                if (!string.IsNullOrEmpty(error))
                    _logger.WriteLog(error);
                else
                    _logger.WriteLog("Đã import thành công " + lstPhieuThu.Count + " phiếu bảo hiểm.");
            }
            catch (Exception objEx)
            {
                _logger.WriteLog("SoThuController.ImportData:" + objEx);
                return Json(new { IsError = true, Message = "Lỗi import excel." });
            }
            if (string.IsNullOrEmpty(error))
            {
                return Json(new
                {
                    IsError = false,
                    Message = ""
                });
            }
            else
            {
                _logger.WriteLog("SoThuController.ImportData:" + error);
                return Json(new { IsError = true, Message = error });
            }

        }
        public ActionResult ImportUpdateDataThuBH()
        {
            if (CurrentUser.ReadOnly == true)
            {
                return Redirect("/Home/NoAccess");
            }
            string error = "";

            try
            {
                Hashtable hshCol = new Hashtable();
                hshCol.Add("STT", 1);
                hshCol.Add("Ngày thu", 0);
                hshCol.Add("Mã phiếu thu", 0);
                hshCol.Add("Họ tên khách hàng", 0);
                hshCol.Add("Số hợp đồng", 0);
                hshCol.Add("Biển số", 0);
                hshCol.Add("Công ty BH", 0);
                hshCol.Add("Tiền trả BH", 0);
                hshCol.Add("Hoa hồng", 0);


                List<PhieuThu> lstPhieuThu = new List<PhieuThu>();
                List<ChiTietPhieuThu> lstChiTietPhieuThu = new List<ChiTietPhieuThu>();

                foreach (string file in Request.Files)
                {
                    var fileContent = Request.Files[file];
                    if (fileContent != null && fileContent.ContentLength > 0)
                    {
                        Stream stream = fileContent.InputStream;
                        using (var package = new ExcelPackage(stream))
                        {
                            var workBook = package.Workbook;
                            if (workBook != null)
                            {
                                if (workBook.Worksheets.Count > 0)
                                {
                                    var ws = workBook.Worksheets[1];
                                    if (ws.Dimension.End.Row < 2)
                                    {
                                        return Json(new { IsError = true, Message = "Không có dữ liệu để import" }, JsonRequestBehavior.AllowGet);
                                    }

                                    #region Kiểm tra file đúng định dạng
                                    int beginRowNum = 1;
                                    for (int ii = 1; ii <= 20; ii++)
                                    {
                                        if (ws.Cells[beginRowNum, ii].Value != null)
                                        {
                                            if (ws.Cells[beginRowNum, ii].Value.ToString().Trim().ToUpper().Equals("STT"))
                                                hshCol["STT"] = ii;
                                            if (ws.Cells[beginRowNum, ii].Value.ToString().Trim().Equals("Ngày thu"))
                                                hshCol["Ngày thu"] = ii;
                                            if (ws.Cells[beginRowNum, ii].Value.ToString().Trim().Equals("Mã phiếu thu"))
                                                hshCol["Mã phiếu thu"] = ii;
                                            if (ws.Cells[beginRowNum, ii].Value.ToString().Trim().Equals("Họ tên khách hàng"))
                                                hshCol["Họ tên khách hàng"] = ii;
                                            if (ws.Cells[beginRowNum, ii].Value.ToString().Trim().Equals("Công ty BH"))
                                                hshCol["Công ty BH"] = ii;
                                            if (ws.Cells[beginRowNum, ii].Value.ToString().Trim().Equals("Số hợp đồng"))
                                                hshCol["Số hợp đồng"] = ii;
                                            if (ws.Cells[beginRowNum, ii].Value.ToString().Trim().Equals("Biển số"))
                                                hshCol["Biển số"] = ii;
                                            if (ws.Cells[beginRowNum, ii].Value.ToString().Trim().Equals("Thực bán"))
                                                hshCol["Thực bán"] = ii;
                                            if (ws.Cells[beginRowNum, ii].Value.ToString().Trim().Equals("Tiền trả BH"))
                                                hshCol["Tiền trả BH"] = ii;
                                            if (ws.Cells[beginRowNum, ii].Value.ToString().Trim().Equals("Hoa hồng"))
                                                hshCol["Hoa hồng"] = ii;
                                        }

                                    }
                                    //neu co cot khong ton tai trong danh sach cot can thiet thi canh bao sai dinh dang
                                    foreach (DictionaryEntry o in hshCol)
                                        if (o.Value.ToString() == "0")
                                        {
                                            return Json(new { IsError = true, Message = "File excel thiếu cột " + o.Key.ToString() + ". Vui lòng kiểm tra lại." }, JsonRequestBehavior.AllowGet);
                                        }
                                    #endregion

                                    #region Add dữ liệu
                                    int indexSTT = (int)hshCol["STT"];
                                    int indexNgayThu = (int)hshCol["Ngày thu"];
                                    int indexMaPhieuThu = (int)hshCol["Mã phiếu thu"];
                                    int indexHoTenKH = (int)hshCol["Họ tên khách hàng"];
                                    int indexSHD = (int)hshCol["Số hợp đồng"];
                                    int indexBienSo = (int)hshCol["Biển số"];
                                    int indexCTYBH = (int)hshCol["Công ty BH"];
                                    int indexTienTraBH = (int)hshCol["Tiền trả BH"];
                                    int indexHoaHong = (int)hshCol["Hoa hồng"];
                                    //kiem tra rang buoc tien trong hang tren duong con du thi moi import
                                    for (var rowNum = beginRowNum + 1; rowNum <= ws.Dimension.End.Row; rowNum++)
                                    {
                                        try
                                        {
                                            string STT = ws.Cells[rowNum, indexSTT].Value == null ? "" : ws.Cells[rowNum, indexSTT].Value.ToString();
                                            if (!string.IsNullOrEmpty(STT) && STT != "")
                                            {
                                                string TIENTRABAOHIEM = ws.Cells[rowNum, indexTienTraBH].Value == null ? "" : ws.Cells[rowNum, indexTienTraBH].Value.ToString();
                                                string HOAHONG = ws.Cells[rowNum, indexHoaHong].Value == null ? "" : ws.Cells[rowNum, indexHoaHong].Value.ToString();
                                                string SoHD = ws.Cells[rowNum, indexSHD].Value == null ? "" : ws.Cells[rowNum, indexSHD].Value.ToString();

                                                if (!TNK.Core.Common.IsNumeric(TIENTRABAOHIEM))
                                                {
                                                    error = "Dòng " + (rowNum - 1) + " tiền trả bảo hiểm (" + TIENTRABAOHIEM + ") không phải là kiểu số.";
                                                    break;
                                                }
                                                if (!TNK.Core.Common.IsNumeric(HOAHONG))
                                                {
                                                    error = "Dòng " + (rowNum - 1) + " hoa hồng (" + HOAHONG + ") không phải là kiểu số.";
                                                    break;
                                                }
                                            }
                                        }
                                        catch (Exception e)
                                        {
                                            error += e;

                                        }
                                    }
                                    if (string.IsNullOrEmpty(error))
                                    {
                                        //TuiDinhKhoan tdk = new TuiDinhKhoan(); /*_tuiDinhKhoanService.GetTuiDinhKhoan(maTui);*/
                                        for (var rowNum = beginRowNum + 1; rowNum <= ws.Dimension.End.Row; rowNum++)
                                        {
                                            try
                                            {
                                                //DataRow row = dtb.NewRow();
                                                DateTime NGAYTHU = new DateTime();
                                                string ngayThu = ws.Cells[rowNum, indexNgayThu].Value == null ? "" : ws.Cells[rowNum, indexNgayThu].Value.ToString();
                                                if (TNK.Core.Common.IsDate(ngayThu) == false)
                                                {
                                                    if (TNK.Core.Common.IsNumeric(ngayThu))
                                                    {
                                                        double DATE = double.Parse(ngayThu);
                                                        NGAYTHU = DateTime.FromOADate(DATE);
                                                    }
                                                }
                                                else
                                                    NGAYTHU = Convert.ToDateTime(ngayThu);
                                                if (NGAYTHU.Year > 2000)
                                                {
                                                    string MAPHIEUTHU = ws.Cells[rowNum, indexMaPhieuThu].Value == null ? "" : ws.Cells[rowNum, indexMaPhieuThu].Value.ToString();
                                                    string NgayThu = ws.Cells[rowNum, indexNgayThu].Value == null ? "" : ws.Cells[rowNum, indexNgayThu].Value.ToString();
                                                    string HoTenKH = ws.Cells[rowNum, indexHoTenKH].Value == null ? "" : ws.Cells[rowNum, indexHoTenKH].Value.ToString();
                                                    string CTYBH = ws.Cells[rowNum, indexCTYBH].Value == null ? "" : ws.Cells[rowNum, indexCTYBH].Value.ToString();
                                                    string SHD = ws.Cells[rowNum, indexSHD].Value == null ? "" : ws.Cells[rowNum, indexSHD].Value.ToString();
                                                    string BienSo = ws.Cells[rowNum, indexBienSo].Value == null ? "" : ws.Cells[rowNum, indexBienSo].Value.ToString();
                                                    string TienTraBH = ws.Cells[rowNum, indexTienTraBH].Value == null ? "" : ws.Cells[rowNum, indexTienTraBH].Value.ToString();
                                                    string HoaHong = ws.Cells[rowNum, indexHoaHong].Value == null ? "" : ws.Cells[rowNum, indexHoaHong].Value.ToString();

                                                    if (string.IsNullOrEmpty(CTYBH))
                                                    {
                                                        error += Environment.NewLine + "Dòng " + (rowNum - 1) + " không có công ty bảo hiểm.";
                                                        break;
                                                    }
                                                    else
                                                    {
                                                        bool flag = _doiTacService.getCTBHById(CTYBH);
                                                        if (flag == false)
                                                        {
                                                            error += Environment.NewLine + "Dòng " + (rowNum - 1) + " không có công ty bảo hiểm trong danh mục.";
                                                            break;
                                                        }
                                                    }
                                                    PhieuThu item = new PhieuThu();
                                                    item.NgayThu = Convert.ToDateTime(NgayThu);
                                                    item.HoTen = HoTenKH;
                                                    item.CTBH = CTYBH;
                                                    item.SoHopDong = SHD;
                                                    item.BienSo = BienSo;
                                                    item.TienTraBH = Convert.ToDouble(TienTraBH);
                                                    item.HoaHong = Convert.ToDouble(HoaHong);
                                                    item.MaPhieuThu = MAPHIEUTHU;
                                                    item.IsActive = true;
                                                    item.IsDeleted = false;
                                                    item.MaLoaiPhieu = "TBAHI";
                                                    item.GiaBan = item.TienTraBH + item.HoaHong;
                                                    item.GiaVon = item.TienTraBH + item.HoaHong;

                                                    //phan httt
                                                    lstPhieuThu.Add(item);
                                                }

                                                else
                                                    error += Environment.NewLine + "Dòng " + (rowNum - 1) + ": Sai định dạng ngày thu. Vui lòng kiểm tra lại.";
                                            }
                                            catch (Exception exx)
                                            {
                                                error += Environment.NewLine + "Dòng " + (rowNum - 1) + ": " + exx;
                                            }
                                        }
                                    }

                                    string xml = TNK.Core.Common.ConvertListToXMLString(lstPhieuThu.ToArray());
                                    if (string.IsNullOrEmpty(error))
                                    {
                                        var result = _phieuThuService.UpdatePhieuThuBH(xml);
                                        if (result != "")
                                            error = result;
                                        else
                                        {

                                            for (int i = 0; i < lstPhieuThu.Count; i++)
                                            {

                                                PhieuThu item = lstPhieuThu[i];
                                                string _xml = "<formdata><Action>PhieuThu</Action>";
                                                _xml += Environment.NewLine + "<submit>Update từ excel</submit>";
                                                if (item != null)
                                                    _xml += TNK.Core.Common.ConvertObjectToXMLString(item);
                                                _xml += "</formdata>";
                                                _phieuThuService.XuLySauKhiUpdatePhieuThu(item.MaPhieuThu,"", _xml);
                                            }
                                        }

                                    }
                                    #endregion
                                }
                            }
                        }
                    }

                }
                if (!string.IsNullOrEmpty(error))
                    _logger.WriteLog(error);
                else
                    _logger.WriteLog("Đã import thành công " + lstPhieuThu.Count + " phiếu bảo hiểm.");
            }
            catch (Exception objEx)
            {
                _logger.WriteLog("SoThuController.ImportData:" + objEx);
                return Json(new { IsError = true, Message = "Lỗi import excel." });
            }
            if (string.IsNullOrEmpty(error))
            {
                return Json(new
                {
                    IsError = false,
                    Message = ""
                });
            }
            else
            {
                _logger.WriteLog("SoThuController.ImportData:" + error);
                return Json(new { IsError = true, Message = error });
            }

        }

        public ActionResult ImportUpdateDataThuSK()
        {
            if (CurrentUser.ReadOnly == true)
            {
                return Redirect("/Home/NoAccess");
            }
            string error = "";

            try
            {
                Hashtable hshCol = new Hashtable();
                hshCol.Add("Mã phiếu thu", 0);
                hshCol.Add("Số Khung", 0);


                List<PhieuThu> lstPhieuThu = new List<PhieuThu>();
                foreach (string file in Request.Files)
                {
                    var fileContent = Request.Files[file];
                    if (fileContent != null && fileContent.ContentLength > 0)
                    {
                        Stream stream = fileContent.InputStream;
                        using (var package = new ExcelPackage(stream))
                        {
                            var workBook = package.Workbook;
                            if (workBook != null)
                            {
                                if (workBook.Worksheets.Count > 0)
                                {
                                    var ws = workBook.Worksheets[1];
                                    if (ws.Dimension.End.Row < 2)
                                    {
                                        return Json(new { IsError = true, Message = "Không có dữ liệu để import" }, JsonRequestBehavior.AllowGet);
                                    }

                                    #region Kiểm tra file đúng định dạng
                                    int beginRowNum = 1;
                                    for (int ii = 1; ii <= 20; ii++)
                                    {
                                        if (ws.Cells[beginRowNum, ii].Value != null)
                                        {
                                            if (ws.Cells[beginRowNum, ii].Value.ToString().Trim().Equals("Mã phiếu thu"))
                                                hshCol["Mã phiếu thu"] = ii;
                                            if (ws.Cells[beginRowNum, ii].Value.ToString().Trim().Equals("Số Khung"))
                                                hshCol["Số Khung"] = ii;
                                        }

                                    }
                                    //neu co cot khong ton tai trong danh sach cot can thiet thi canh bao sai dinh dang
                                    foreach (DictionaryEntry o in hshCol)
                                        if (o.Value.ToString() == "0")
                                        {
                                            return Json(new { IsError = true, Message = "File excel thiếu cột " + o.Key.ToString() + ". Vui lòng kiểm tra lại." }, JsonRequestBehavior.AllowGet);
                                        }
                                    #endregion

                                    #region Add dữ liệu
                                    int indexMaPhieuThu = (int)hshCol["Mã phiếu thu"];
                                    int indexSK = (int)hshCol["Số Khung"];
                                    //kiem tra rang buoc tien trong hang tren duong con du thi moi import
                                    for (var rowNum = beginRowNum + 1; rowNum <= ws.Dimension.End.Row; rowNum++)
                                    {
                                        try
                                        {
                                            string MPT = ws.Cells[rowNum, indexMaPhieuThu].Value == null ? "" : ws.Cells[rowNum, indexMaPhieuThu].Value.ToString();
                                            if (!string.IsNullOrEmpty(MPT) && MPT != "")
                                            {
                                                string SK = ws.Cells[rowNum, indexSK].Value == null ? "" : ws.Cells[rowNum, indexSK].Value.ToString();

                                                if (string.IsNullOrEmpty(SK))
                                                {
                                                    error = "Dòng " + (rowNum - 1) + "không có dữ liệu số khung";
                                                    break;
                                                }                                            
                                            }
                                        }
                                        catch (Exception e)
                                        {
                                            error += e;

                                        }
                                    }
                                    if (string.IsNullOrEmpty(error))
                                    {
                                        //TuiDinhKhoan tdk = new TuiDinhKhoan(); /*_tuiDinhKhoanService.GetTuiDinhKhoan(maTui);*/
                                        for (var rowNum = beginRowNum + 1; rowNum <= ws.Dimension.End.Row; rowNum++)
                                        {
                                            try
                                            {
                                                
                                                string MAPHIEUTHU = ws.Cells[rowNum, indexMaPhieuThu].Value == null ? "" : ws.Cells[rowNum, indexMaPhieuThu].Value.ToString();
                                                string SK = ws.Cells[rowNum, indexSK].Value == null ? "" : ws.Cells[rowNum, indexSK].Value.ToString();

                                                PhieuThu phieuThu = _phieuThuService.GetPhieuThu(MAPHIEUTHU);
