                                                            if ((temp.ROTYPE != "GJ" || temp.WTCODE != "J")
                                                                && !(temp.ROTYPE == "BP" && (temp.KPI_PART_TYPE == null))
                                                                && !ptt.Contains(temp.KPI_PART_TYPE) && !ptn.Contains(temp.KPI_PART_TYPE))
                                                            {
                                                                ct.MaKho = "KHO_PKIEN";
                                                                ct.PhanLoai = "KHO_PKDV";
                                                            }
                                                            tongGiaBan += temp.COST * VAT;
                                                            tongGiamGia += (double)temp.DISCOUNT * VAT;
                                                            item.TongCong += ((double)temp.COST - (double)temp.DISCOUNT);
                                                            //item.TongCong = item.TongCong * VAT;
                                                            ct.VAT = VAT;
                                                            ptdv.Add(ct);
                                                        }
                                                        item.TongCong = item.TongCong * 1.1;
                                                        double TongThanhToan = 0;
                                                        foreach (var thanhtoan in CTPT)
                                                        {
                                                            TongThanhToan += thanhtoan.SoTienThanhToan;
                                                        }
                                                        if (Math.Abs(item.TongCong - TongThanhToan) <= 1)
                                                        {
                                                            NPTra.SoTienNo = item.TongCong - TongThanhToan;
                                                            NPTra.NguoiBaoLanh = NguoiBaoLanh;
                                                            NPTra.LoaiPhieuNo = "NDIVU";


                                                        }
                                                        if (item.TongCong != TongThanhToan)
                                                        {
                                                            if (!string.IsNullOrEmpty(ctptTTNH.MaNganHang))
                                                            {
                                                                ctptTTNH.SoTienThanhToan += item.TongCong - TongThanhToan;
                                                            }
                                                            else if (!string.IsNullOrEmpty(ThanhToanBaoHiem.MaNganHang))
                                                                ctptTTNH.SoTienThanhToan += item.TongCong - TongThanhToan;
                                                        }
                                                        item.SoTienThu = TongThanhToan + (item.TongCong - TongThanhToan);
                                                        if (TongThanhToan > item.TongCong && Math.Abs(TongThanhToan - item.TongCong) > 1)
                                                        {
                                                            error += Environment.NewLine + "Dòng " + (rowNum - 1) + " số tiền thu phải nhỏ hơn số tiền cần thanh toán";
                                                            break;
                                                        }

                                                        #endregion
                                                    }
                                                    lstPhieuThu.Add(item);
                                                    lstChiTietPhieuThu.Add(CTPT);
                                                    lstChiTietPhieuThuDV.Add(ptdv);
                                                    LstNoPhaiTra.Add(NPTra);
                                                }
                                                else
                                                    error += Environment.NewLine + "Dòng " + (rowNum - 1) + ": Sai định dạng ngày thu. Vui lòng kiểm tra lại.";

                                            }
                                            catch (Exception exx)
                                            {
                                                error += Environment.NewLine + "Dòng " + (rowNum - 1) + ": " + exx;
                                            }
                                        }
                                    }
                                    if (string.IsNullOrEmpty(error))
                                    {
                                        for (int i = 0; i < lstPhieuThu.Count; i++)
                                        {

                                            string xml = "<formdata><Action>PhieuThu</Action>";
                                            xml += Environment.NewLine + "<submit>Import từ excel</submit>";
                                            if (lstPhieuThu[i] != null)
                                                xml += TNK.Core.Common.ConvertObjectToXMLString(lstPhieuThu[i]);
                                            if (lstChiTietPhieuThu[i] != null)
                                            {
                                                xml += Environment.NewLine + "<ThanhToan>";
                                                foreach (ChiTietPhieuThu ct in lstChiTietPhieuThu[i])
                                                    xml += TNK.Core.Common.ConvertObjectToXMLString(ct);
                                                xml += Environment.NewLine + "</ThanhToan>";
                                            }
                                            xml += "</formdata>";
                                            string messagePT = _phieuThuService.CreatePhieuThu(lstPhieuThu[i], lstChiTietPhieuThu[i], false);
                                            if (messagePT != "")
                                                error += Environment.NewLine + "Dòng " + (i + 1) + "(" + SoQuyetToan + "):" + messagePT;
                                            bool messageCTPDV = _soThuService.InsertChiTietPhieuDichVu(lstChiTietPhieuThuDV[i], lstPhieuThu[i].MaPhieuThu);
                                            if (messageCTPDV != true)
                                                error += Environment.NewLine + "Dòng " + (i + 1) + "(" + SoQuyetToan + "):" + messageCTPDV;
                                            _phieuThuService.XuLySauKhiInsertPhieuThu(lstPhieuThu[i].MaPhieuThu, xml);
                                            //if (LstNoPhaiTra[i].SoTienNo > 0)
                                            //{
                                            //    bool messageNPT = _noPhaiTraService.InsertNoPhaiTra(LstNoPhaiTra[i], lstPhieuThu[i].MaPhieuThu);
                                            //    if (messageNPT != true)
                                            //        error += Environment.NewLine + "Dòng " + (i + 1) + "(" + SoQuyetToan + "):" + messageNPT;
                                            //}
                                            //_noPhaiTraService.InsertNoPhaiTra(noPhaiTra, obj.MaPhieuThu);
                                        }
                                    }
                                    else
                                        log.Error(error);
                                    #endregion
                                }
                            }
                        }
                    }
                }
            }
            catch (Exception objEx)
            {
                _logger.WriteLog("SoThuController.ImportData_DV:" + objEx);
                return Json(new { IsError = true, Message = "Lỗi import excel." });
            }
            if (string.IsNullOrEmpty(error))
            {
                return Json(new
                {
                    IsError = false,
                    Message = ""
                });
            }
            else
            {
                _logger.WriteLog("SoThuController.ImportData_DV:" + error);
                return Json(new { IsError = true, Message = error });
            }

        }

