                                                    double VAT = Convert.ToInt32(dtsheet2.Rows[j]["%Thue"].ToString()) == 0 ? 1 : Convert.ToDouble(dtsheet2.Rows[j]["%Thue"].ToString()) / 100;
                                                    double ThucThu = Convert.ToDouble(dtsheet2.Rows[j]["ThucThu"].ToString());
                                                    TongCT += VAT == 1 ? ThucThu : (ThucThu * VAT) + ThucThu;
                                                }
                                                else
                                                    continue;
                                            }
                                            TongCT = Math.Round(TongCT);
                                            STPT = Math.Round(STPT);
                                            double ChenhLech = TongCT - STPT;
                                            if (Math.Abs(ChenhLech) > 1)
                                            {
                                                error = "Số phiếu quyết toán " + dtsheet1.Rows[i]["SoQuyetToan"].ToString() + " của sheet tổng hợp có tổng tiền phải trả không bằng số tiền ở sheet chi tiết";
                                                break;
                                            }
                                        }
                                    }
                                    #endregion
                                    #region Chi tiet dich vu
                                    if (dtsheet1.Rows.Count > 0)
                                    {
                                        for (int i = 0; i < dtsheet1.Rows.Count; i++)
                                        {
                                            if (dtsheet2.Rows.Count > 0)
                                            {
                                                List<ChiTietPhieuDichVu> ptdv = new List<ChiTietPhieuDichVu>();
                                                for (int z = 0; z < dtsheet2.Rows.Count; z++)
                                                {
                                                    if (dtsheet1.Rows[i]["SoQuyetToan"].ToString().Trim() == dtsheet2.Rows[z]["SoQuyetToan"].ToString().Trim())
                                                    {
                                                        ChiTietPhieuDichVu ct = new ChiTietPhieuDichVu();
                                                        ct.REPAIRORDERNO = dtsheet2.Rows[z]["SoQuyetToan"].ToString();
                                                        ct.JOBSNAME = dtsheet2.Rows[z]["TenCongViec"].ToString();
                                                        ct.COST = Math.Round(Convert.ToDouble(dtsheet2.Rows[z]["GiaBan"].ToString()));
                                                        ct.DISCOUNT = Math.Round(ct.COST - Convert.ToDouble(dtsheet2.Rows[z]["ThucThu"].ToString()));
                                                        ct.GCN = Convert.ToDouble(dtsheet2.Rows[z]["ChiGCN"].ToString());
                                                        ct.VAT = Convert.ToDouble(dtsheet2.Rows[z]["%Thue"].ToString()) / 100;
                                                        string maKho = dtsheet2.Rows[z]["PhanLoaiCV"].ToString().TrimEnd().ToUpper();
                                                        switch (maKho)
                                                        {
                                                            case "SC":
                                                                ct.MaKho = "SUACHUA";
                                                                ct.PhanLoai = "SUACHUA";
                                                                break;
                                                            case "CĐ":
                                                                ct.MaKho = "SUACHUA";
                                                                ct.PhanLoai = "CĐ";
                                                                break;
                                                            case "DTS":
                                                                ct.MaKho = "KHO_DS";
                                                                ct.PhanLoai = "KHO_DTS";
                                                                break;
                                                            case "PTT":
                                                                ct.MaKho = "KHO_PTT";
                                                                ct.PhanLoai = "KHO_PTT";
                                                                break;
                                                            case "PKT":
                                                                ct.MaKho = "KHO_PTT";
                                                                ct.PhanLoai = "KHO_PKT";
                                                                break;
                                                            case "PKN":
                                                                ct.MaKho = "KHO_PKIEN";
                                                                ct.PhanLoai = "KHO_PKN";
                                                                break;
                                                            case "VTN":
                                                                ct.MaKho = "KHO_PKIEN";
                                                                ct.PhanLoai = "KHO_VTN";
                                                                break;
                                                            case "VTGTGT":
                                                                ct.MaKho = "KHO_PKIEN";
                                                                ct.PhanLoai = "KHO_VTGTGT";
                                                                break;
                                                            case "QT":
                                                                ct.MaKho = "KHO_QTKM";
                                                                ct.PhanLoai = "KHO_QTKM";
                                                                break;
                                                            default:
                                                                break;
                                                        }
                                                        ptdv.Add(ct);
                                                    }
                                                }
                                                lstChiTietPhieuThuDV.Add(ptdv);
                                                //index = index + 1;
                                                //for (int index = 0; index < ptdv.Count; index++)
                                                //{
                                                //    ptdv.RemoveAt(index);
                                                //}
                                            }
                                            else
                                            {
                                                error = "Sheet Chi tiết dịch vụ không có dữ liệu";
                                            }
                                        }

                                    }
                                    else
                                    {
                                        error = "Sheet tổng hợp không có dữ liệu";
                                    }
                                    #endregion
                                    #endregion
                                    #region Add dữ liệu
                                    if (error != "")
                                    {
                                        log.Error(error);
                                        return error;
                                    }
                                    if (string.IsNullOrEmpty(error))
                                    {
                                        for (int i = 0; i < lstPhieuThu.Count; i++)
                                        {

                                            string xml = "<formdata><Action>PhieuThu</Action>";
                                            xml += Environment.NewLine + "<submit>Import từ excel</submit>";
                                            if (lstPhieuThu[i] != null)
                                                xml += TNK.Core.Common.ConvertObjectToXMLString(lstPhieuThu[i]);
                                            if (lstChiTietPhieuThu[i] != null)
                                            {
                                                xml += Environment.NewLine + "<ThanhToan>";
                                                foreach (ChiTietPhieuThu ct in lstChiTietPhieuThu[i])
                                                    xml += TNK.Core.Common.ConvertObjectToXMLString(ct);
                                                xml += Environment.NewLine + "</ThanhToan>";
                                            }
                                            xml += "</formdata>";
                                            string messagePT = _phieuThuService.CreatePhieuThu(lstPhieuThu[i], lstChiTietPhieuThu[i], false);
                                            if (messagePT != "")
                                            {
                                                if (messagePT == "Mã phiếu này đã tồn tại.")
                                                    error += Environment.NewLine + "Dòng " + (i + 1) + "(" + lstPhieuThu[i].SoHopDong + "):" + messagePT;
                                                else //if(messagePT == "Lỗi tạo mới phiếu thu")
                                                    error += Environment.NewLine + "Dòng " + (i + 1) + "(" + lstPhieuThu[i].SoHopDong + "):" + messagePT;
                                                log.Error(error);
                                                return error;
                                            }
                                            if (Convert.ToDouble(ListCNHonda[i]) > 0)
                                            {
                                                PhieuThu pt = new PhieuThu();
                                                pt.MaLoaiPhieu = "TKHAC";
                                                pt.DoiTac = "HVN";
                                                pt.TongCong = Convert.ToDouble(ListCNHonda[i]);
                                                pt.NoiDung = "BẢO HÀNH THEO QT: (" + lstPhieuThu[i].SoHopDong + "), BSX: (" + lstPhieuThu[i].BienSo + ")";
                                                pt.BienSo = lstPhieuThu[i].BienSo;
                                                pt.MaPhieuLienQuan = lstPhieuThu[i].MaPhieuThu;
                                                pt.ThongTinKhac = lstPhieuThu[i].HoTen;
                                                pt.SoChungTu = "CNHONDA";
                                                pt.ConLai = Convert.ToDouble(ListCNHonda[i]);
                                                pt.NguoiThuTien = lstPhieuThu[i].NguoiThuTien;
                                                pt.NgayThu = lstPhieuThu[i].NgayThu;
                                                List<ChiTietPhieuThu> ctpt = new List<ChiTietPhieuThu>();
                                                List<ChiTietBanPhuKien> ctbpk = new List<ChiTietBanPhuKien>();
                                                List<ChiTietBaoDuongTietKiem> ctbdtk = new List<ChiTietBaoDuongTietKiem>();

                                                ActionResult A = PhieuThu(pt, ctpt, "", "Create", "", ctpt, ctbpk, ctbdtk, ctpt);
                                                string a = A.ToString();
                                            }
                                            bool messageCTPDV = _soThuService.InsertChiTietPhieuDichVu_Import(lstChiTietPhieuThuDV[i], lstPhieuThu[i].MaPhieuThu);
                                            if (messageCTPDV != true)
                                            {
                                                error += Environment.NewLine + "Dòng " + (i + 1) + "(" + SoQuyetToan + "):" + messageCTPDV;
                                                log.Error(error);
                                                return error;
                                            }
                                            _phieuThuService.XuLySauKhiInsertPhieuThu(lstPhieuThu[i].MaPhieuThu, xml);
                                        }
                                    }
                                    #endregion
                                }
                            }
                        }
                    }
                }
            }
            catch (Exception objEx)
            {
                _logger.WriteLog("SoThuController.ImportData_DV:" + objEx);
                return "Lỗi import excel.";
            }
            if (string.IsNullOrEmpty(error))
            {
                return "Import thành công";
            }
            else
            {
                _logger.WriteLog("SoThuController.ImportData_DV:" + error);
                return error;
            }

        }
        
