                                    if (ws.Dimension.End.Row < 2)
                                    {
                                        return Json(new { IsError = true, Message = "Không có dữ liệu để import" }, JsonRequestBehavior.AllowGet);
                                    }

                                    #region Kiểm tra file đúng định dạng
                                    for (int ii = 1; ii <= 21; ii++)
                                    {
                                        if (ws.Cells[beginRowNum, ii].Value != null)
                                        {
                                            if (ws.Cells[beginRowNum, ii].Value.ToString().Trim().ToUpper().Equals("STT"))
                                                hshCol["STT"] = ii;
                                            if (ws.Cells[beginRowNum, ii].Value.ToString().Trim().Equals("Số hợp đồng"))
                                                hshCol["Số hợp đồng"] = ii;
                                            if (ws.Cells[beginRowNum, ii].Value.ToString().Trim().Equals("Ngày hợp đồng"))
                                                hshCol["Ngày hợp đồng"] = ii;
                                            if (ws.Cells[beginRowNum, ii].Value.ToString().Trim().Equals("Ngày thu"))
                                                hshCol["Ngày thu"] = ii;
                                            if (ws.Cells[beginRowNum, ii].Value.ToString().Trim().Equals("Điện thoại"))
                                                hshCol["Điện thoại"] = ii;
                                            if (ws.Cells[beginRowNum, ii].Value.ToString().Trim().Equals("Địa chỉ"))
                                                hshCol["Địa chỉ"] = ii;
                                            if (ws.Cells[beginRowNum, ii].Value.ToString().Trim().Equals("Họ tên"))
                                                hshCol["Họ tên"] = ii;
                                            if (ws.Cells[beginRowNum, ii].Value.ToString().Trim().Equals("Số hóa đơn"))
                                                hshCol["Số hóa đơn"] = ii;
                                            if (ws.Cells[beginRowNum, ii].Value.ToString().Trim().Equals("Chứng từ liên quan"))
                                                hshCol["Chứng từ liên quan"] = ii;
                                            if (ws.Cells[beginRowNum, ii].Value.ToString().Trim().Equals("Số Khung"))
                                                hshCol["Số Khung"] = ii;
                                            if (ws.Cells[beginRowNum, ii].Value.ToString().Trim().Equals("Thực bán"))
                                                hshCol["Thực bán"] = ii;
                                            if (ws.Cells[beginRowNum, ii].Value.ToString().Trim().Equals("Ngân Hàng Cho Vay"))
                                                hshCol["Ngân Hàng Cho Vay"] = ii;
                                            if (ws.Cells[beginRowNum, ii].Value.ToString().Trim().Equals("Số tiền vay"))
                                                hshCol["Số tiền vay"] = ii;
                                            if (ws.Cells[beginRowNum, ii].Value.ToString().Trim().Equals("Ngân hàng"))
                                                hshCol["Ngân hàng"] = ii;
                                            if (ws.Cells[beginRowNum, ii].Value.ToString().Trim().Equals("HTTT"))
                                                hshCol["HTTT"] = ii;
                                            if (ws.Cells[beginRowNum, ii].Value.ToString().Trim().Equals("Số tiền"))
                                                hshCol["Số tiền"] = ii;
                                            if (ws.Cells[beginRowNum, ii].Value.ToString().Trim().Equals("Số tham chiếu"))
                                                hshCol["Số tham chiếu"] = ii;
                                            if (ws.Cells[beginRowNum, ii].Value.ToString().Trim().Equals("Treo tiền"))
                                                hshCol["Treo tiền"] = ii;
                                            if (ws.Cells[beginRowNum, ii].Value.ToString().Trim().Equals("Người bảo lãnh"))
                                                hshCol["Người bảo lãnh"] = ii;
                                            if (ws.Cells[beginRowNum, ii].Value.ToString().Trim().Equals("Ghi chú"))
                                                hshCol["Ghi chú"] = ii;
                                            if (ws.Cells[beginRowNum, ii].Value.ToString().Trim().Equals("Người thu tiền"))
                                                hshCol["Người thu tiền"] = ii;
                                        }

                                    }
                                    //neu co cot khong ton tai trong danh sach cot can thiet thi canh bao sai dinh dang
                                    foreach (DictionaryEntry o in hshCol)
                                        if (o.Value.ToString() == "0")
                                        {
                                            return Json(new { IsError = true, Message = "File excel thiếu cột " + o.Key.ToString() + ". Vui lòng kiểm tra lại." }, JsonRequestBehavior.AllowGet);
                                        }
                                    #endregion

                                    #region Add dữ liệu
                                    int indexSoHopDong = (int)hshCol["Số hợp đồng"];
                                    int indexNgayHopDong = (int)hshCol["Ngày hợp đồng"];
                                    int indexNgayThu = (int)hshCol["Ngày thu"];
                                    int indexDienThoai = (int)hshCol["Điện thoại"];
                                    int indexDiaChi = (int)hshCol["Địa chỉ"];
                                    int indexHoTen = (int)hshCol["Họ tên"];
                                    int indexSoHoaDon = (int)hshCol["Số hóa đơn"];
                                    int indexChungTuLienQuan = (int)hshCol["Chứng từ liên quan"];
                                    int indexSoKhung = (int)hshCol["Số Khung"];
                                    int indexThucBan = (int)hshCol["Thực bán"];
                                    int indexNHCV = (int)hshCol["Ngân Hàng Cho Vay"];
                                    int indexSoTienVay = (int)hshCol["Số tiền vay"];
                                    int indexNganHang = (int)hshCol["Ngân hàng"];
                                    int indexHTTT = (int)hshCol["HTTT"];
                                    int indexSoTien = (int)hshCol["Số tiền"];
                                    int indexSoThamChieu = (int)hshCol["Số tham chiếu"];
                                    int indexTreoTien = (int)hshCol["Treo tiền"];
                                    int indexNguoiBaoLanh = (int)hshCol["Người bảo lãnh"];
                                    int indexGhiChu = (int)hshCol["Ghi chú"];
                                    int indexNguoiThuTien = (int)hshCol["Người thu tiền"];
                                    //kiem tra rang buoc tien trong hang tren duong con du thi moi import
                                    if (string.IsNullOrEmpty(error))
                                    {
                                        for (var rowNum = beginRowNum + 1; rowNum <= ws.Dimension.End.Row; rowNum++)
                                        {
                                            try
                                            {

                                                //DataRow row = dtb.NewRow();
                                                DateTime NGAYTHU = new DateTime();
                                                DateTime NGAYHOPDONG = new DateTime();
                                                string NgayHopDong = ws.Cells[rowNum, indexNgayHopDong].Value == null ? "" : ws.Cells[rowNum, indexNgayHopDong].Value.ToString();
                                                SoHopDong = ws.Cells[rowNum, indexSoHopDong].Value == null ? "" : ws.Cells[rowNum, indexSoHopDong].Value.ToString();
                                                string NgayThu = ws.Cells[rowNum, indexNgayThu].Value == null ? "" : ws.Cells[rowNum, indexNgayThu].Value.ToString();
                                                string DienThoai = ws.Cells[rowNum, indexDienThoai].Value == null ? "" : ws.Cells[rowNum, indexDienThoai].Value.ToString();
                                                string DiaChi = ws.Cells[rowNum, indexDiaChi].Value == null ? "" : ws.Cells[rowNum, indexDiaChi].Value.ToString();
                                                string HoTen = ws.Cells[rowNum, indexHoTen].Value == null ? "" : ws.Cells[rowNum, indexHoTen].Value.ToString();
                                                string SoHoaDon = ws.Cells[rowNum, indexSoHoaDon].Value == null ? "" : ws.Cells[rowNum, indexSoHoaDon].Value.ToString();


                                                string CTLQ = ws.Cells[rowNum, indexChungTuLienQuan].Value == null ? "" : ws.Cells[rowNum, indexChungTuLienQuan].Value.ToString();
                                                string SoKhung = ws.Cells[rowNum, indexSoKhung].Value == null ? "" : ws.Cells[rowNum, indexSoKhung].Value.ToString();
                                                string ThucBan = ws.Cells[rowNum, indexThucBan].Value == null ? "" : ws.Cells[rowNum, indexThucBan].Value.ToString();
                                                string NHCV = ws.Cells[rowNum, indexNHCV].Value == null ? "" : ws.Cells[rowNum, indexNHCV].Value.ToString();
                                                string SoTienVay = ws.Cells[rowNum, indexSoTienVay].Value == null ? "" : ws.Cells[rowNum, indexSoTienVay].Value.ToString();

                                                string NganHang = ws.Cells[rowNum, indexNganHang].Value == null ? "" : ws.Cells[rowNum, indexNganHang].Value.ToString();
                                                string HTTT = ws.Cells[rowNum, indexHTTT].Value == null ? "" : ws.Cells[rowNum, indexHTTT].Value.ToString();
                                                string SoTien = ws.Cells[rowNum, indexSoTien].Value == null ? "" : ws.Cells[rowNum, indexSoTien].Value.ToString();
                                                string GhiChu = ws.Cells[rowNum, indexGhiChu].Value == null ? "" : ws.Cells[rowNum, indexGhiChu].Value.ToString();
                                                string TreoTien = ws.Cells[rowNum, indexTreoTien].Value == null ? "" : ws.Cells[rowNum, indexTreoTien].Value.ToString();
                                                string NguoiBaoLanh = ws.Cells[rowNum, indexNguoiBaoLanh].Value == null ? "" : ws.Cells[rowNum, indexNguoiBaoLanh].Value.ToString();
                                                string STC = ws.Cells[rowNum, indexSoThamChieu].Value == null ? "" : ws.Cells[rowNum, indexSoThamChieu].Value.ToString();
                                                string NguoiThuTien = ws.Cells[rowNum, indexNguoiThuTien].Value == null ? "" : ws.Cells[rowNum, indexNguoiThuTien].Value.ToString();
                                                HTTT = HTTT.ToUpper();
                                                if (string.IsNullOrEmpty(ThucBan))
                                                    ThucBan = "0";
                                                if (string.IsNullOrEmpty(SoTienVay))
                                                    SoTienVay = "0";
                                                if (string.IsNullOrEmpty(SoTien))
                                                    SoTien = "0";
                                                if (!string.IsNullOrEmpty(NHCV))
                                                    NHCV = NHCV.Trim();
                                                if (ThucBan == "0")
                                                {
                                                    if (SoTienVay != "0" || SoTien != "0")
                                                    {
                                                        error = "Dòng " + (rowNum - 1) + " số tiền vay và số tiền phải bằng không";
                                                        break;
                                                    }
                                                }
                                                if (Convert.ToDouble(SoTien) + Convert.ToDouble(SoTienVay) > Convert.ToDouble(ThucBan))
                                                {
                                                    error = "Dòng " + (rowNum - 1) + " thực bán phải lớn hơn bằng tổng số tiền thanh toán và số tiền vay.";
                                                    break;
                                                }
                                                if (!TNK.Core.Common.IsNumeric(ThucBan))
                                                {
                                                    error = "Dòng " + (rowNum - 1) + " thực bán (" + ThucBan + ") không phải là kiểu số.";
                                                    break;
                                                }
                                                if (!string.IsNullOrEmpty(NHCV) && !TNK.Core.Common.IsNumeric(SoTienVay))
                                                {
                                                    error = "Dòng " + (rowNum - 1) + " số tiền vay (" + SoTienVay + ") không phải là kiểu số.";
                                                    break;
                                                }
                                                if (string.IsNullOrEmpty(NHCV) && !string.IsNullOrEmpty(SoTienVay) && SoTienVay != "0")
                                                {
                                                    error = "Dòng " + (rowNum - 1) + " vui lòng nhập ngân hàng cho vay.";
                                                    break;
                                                }
                                                if (!string.IsNullOrEmpty(NHCV) && Convert.ToDouble(SoTienVay) <= 0)
                                                {
                                                    error = "Dòng " + (rowNum - 1) + " vui lòng nhập số tiền vay.";
                                                    break;
                                                }
                                                if (!string.IsNullOrEmpty(NganHang) && !TNK.Core.Common.IsNumeric(SoTien))
                                                {
                                                    error = "Dòng " + (rowNum - 1) + " số tiền (" + SoTien + ") không phải là kiểu số.";
                                                    break;
                                                }
                                                if (!string.IsNullOrEmpty(NganHang) && Convert.ToDouble(SoTien) <= 0 && !string.IsNullOrEmpty(HTTT))
                                                {
                                                    error = "Dòng " + (rowNum - 1) + " số tiền không được nhỏ hơn bằng 0.";
                                                    break;
                                                }
                                                if (!string.IsNullOrEmpty(HTTT) && HTTT != "CK" && HTTT != "CT" && HTTT != "TM")
                                                {
                                                    error = "Dòng " + (rowNum - 1) + " sai hình thức thanh toán.";
                                                    break;
                                                }
                                                if (!string.IsNullOrEmpty(NganHang) && !_doiTacService.getDoiTacById(NganHang) && NganHang != "QuyChinh" && NganHang != "QuyPhu")
                                                {
                                                    error += Environment.NewLine + "Dòng " + (rowNum - 1) + " không tìm thấy ngân hàng " + NganHang;
                                                    break;
                                                }
                                                if (!string.IsNullOrEmpty(NHCV) && !_doiTacService.getDoiTacById(NHCV) && NHCV != "QuyChinh" && NHCV != "QuyPhu")
                                                {
                                                    error += Environment.NewLine + "Dòng " + (rowNum - 1) + " không tìm thấy ngân hàng cho vay " + NHCV;
                                                    break;
                                                }
                                                if (!string.IsNullOrEmpty(NHCV) && _doiTacService.getDoiTacById(NHCV) && Convert.ToDouble(SoTienVay) <= 0)
                                                {
                                                    error += Environment.NewLine + "Dòng " + (rowNum - 1) + " vui lòng nhập số tiền vay cho ngân hàng " + NHCV;
                                                    break;
                                                }
                                                if (!string.IsNullOrEmpty(NganHang) && !_doiTacService.getDoiTacById(NganHang) && Convert.ToDouble(SoTien) <= 0)
                                                {
                                                    error += Environment.NewLine + "Dòng " + (rowNum - 1) + " vui lòng nhập số tiền  " + SoTien;
                                                    break;
                                                }
                                                if (string.IsNullOrEmpty(SoHopDong))
                                                {
                                                    error += Environment.NewLine + "Dòng " + (rowNum - 1) + ": Vui lòng nhập số hợp đồng.";
                                                    break;
                                                }
                                                User us = _userService.getByUserName(NguoiThuTien);
                                                if (us == null)
                                                {
                                                    error += Environment.NewLine + "Dòng " + (rowNum - 1) + " không tìm thấy người thu tiền " + NguoiThuTien;
                                                    break;
                                                }
                                                if (HTTT == "TM" && NganHang != "QuyChinh" && NganHang != "QuyPhu")
                                                {
                                                    error += Environment.NewLine + "Dòng " + (rowNum - 1) + " sai hình thức thanh toán";
                                                    break;
                                                }
                                                if (HTTT != "TM" && (NganHang == "QuyChinh" || NganHang == "QuyPhu"))
                                                {
                                                    error += Environment.NewLine + "Dòng " + (rowNum - 1) + " sai hình thức thanh toán";
                                                    break;
                                                }

                                                if ((Convert.ToDouble(SoTien) > 0 && (string.IsNullOrEmpty(NganHang) || string.IsNullOrEmpty(HTTT)))
                                                    || (!string.IsNullOrEmpty(NganHang) && (string.IsNullOrEmpty(SoTien) || string.IsNullOrEmpty(HTTT)))
                                                    || (!string.IsNullOrEmpty(HTTT) && (string.IsNullOrEmpty(NganHang) || string.IsNullOrEmpty(SoTien)))
                                                    )
                                                {
                                                    error += Environment.NewLine + "Dòng " + (rowNum - 1) + " vui lòng nhập đủ thông tin thanh toán(ngân hàng, HTTT,số tiền).";
                                                    break;
                                                }
                                                if (Convert.ToDouble(SoTien) <= 0 || Convert.ToDouble(SoTienVay) < 0 || Convert.ToDouble(ThucBan) < 0)
                                                {
                                                    error += Environment.NewLine + "Dòng " + (rowNum - 1) + " số tiền hoặc số tiền vay hoặc thực bán phải lớn hơn 0.";
                                                    break;
                                                }
                                                if (string.IsNullOrEmpty(SoKhung))
                                                {
                                                    error += Environment.NewLine + "Dòng " + (rowNum - 1) + " vui lòng nhập số khung";
                                                    break;
                                                }
                                                if (!_phieuThuService.CheckSoKhung(SoKhung) && !string.IsNullOrEmpty(SoKhung))
                                                {
                                                    error += Environment.NewLine + "Dòng " + (rowNum - 1) + " không tìm thấy số khung " + SoKhung;
                                                    break;
                                                }
                                                if (TNK.Core.Common.IsDate(NgayThu) == false)
                                                {
                                                    if (TNK.Core.Common.IsNumeric(NgayThu))
                                                    {
                                                        double DATE = double.Parse(NgayThu);
                                                        NGAYTHU = DateTime.FromOADate(DATE);
                                                    }
                                                }
                                                else
                                                    NGAYTHU = Convert.ToDateTime(NgayThu);
                                                if (TNK.Core.Common.IsDate(NgayHopDong) == false)
                                                {
                                                    if (TNK.Core.Common.IsNumeric(NgayHopDong))
                                                    {
                                                        double DATE = double.Parse(NgayHopDong);
                                                        NGAYHOPDONG = DateTime.FromOADate(DATE);
                                                    }
                                                }
                                                else
                                                    NGAYHOPDONG = Convert.ToDateTime(NgayHopDong);
                                                if (NGAYTHU.Year > 2000)
                                                {
                                                    PhieuThu item = new PhieuThu();
                                                    List<ChiTietPhieuThu> CTPT = new List<ChiTietPhieuThu>();
                                                    List<ChiTietPhieuDichVu> ptdv = new List<ChiTietPhieuDichVu>();
                                                    item.MaLoaiPhieu = "TBAXE";
                                                    item.SoHopDong = SoHopDong;
                                                    item.NgayThu = Convert.ToDateTime(NgayThu);
                                                    if (NgayHopDong != "")
                                                    {
                                                        item.NgayHopDong = Convert.ToDateTime(NgayHopDong);
                                                    }
                                                    item.NguoiThuTien = us.UserId;
                                                    item.SoHoaDon = SoHoaDon;
                                                    item.DienThoai = DienThoai;
                                                    item.HoTen = HoTen;
                                                    item.DiaChi = DiaChi;
                                                    item.GhiChu = GhiChu;
                                                    item.SoChungTu = CTLQ;
                                                    item.NguoiBaoLanh = NguoiBaoLanh;
                                                    item.SoKhung = SoKhung;
                                                    item.GiaBan = Convert.ToDouble(ThucBan);
                                                    ViewKhoXe Xe = _phieuThuService.GetXe(SoKhung);
                                                    item.MauXe = Xe.CodeMau;
                                                    item.MaXe = Xe.CodeModel;
                                                    item.GiaNiemYet = Xe.GiaNiemYet;
                                                    item.GiamGia = item.GiaNiemYet - item.GiaBan;
                                                    item.GiaVon = item.GiaNiemYet;
                                                    item.Flag = true;
                                                    item.TongCong = Convert.ToDouble(ThucBan);
                                                    if (item.GiaBan > item.GiaNiemYet)
                                                    {
                                                        error += Environment.NewLine + "Dòng " + (rowNum - 1) + " thực bán không được lớn hơn giá niêm yết.";
                                                        break;
                                                    }
                                                    //phan httt : phần kh thanh toán

                                                    CTPT.Add(new ChiTietPhieuThu());
                                                    CTPT[0].HinhThucThanhToan = HTTT;
                                                    NganHang = NganHang.ToUpper();
                                                    CTPT[0].MaNganHang = NganHang;
                                                    CTPT[0].SoTienThanhToan = Convert.ToDouble(SoTien);
                                                    CTPT[0].Temp = NganHang + "-" + HTTT;
                                                    CTPT[0].SoThamChieu = STC;
                                                    if (TreoTien == "1")
                                                        CTPT[0].TinhTrang = true;
                                                    else
                                                        CTPT[0].TinhTrang = false;

                                                    double TongThanhToan = 0;
                                                    foreach (var thanhtoan in CTPT)
                                                    {
                                                        TongThanhToan += thanhtoan.SoTienThanhToan;
                                                    }
                                                    item.SoTienThu = TongThanhToan;
                                                    //phan khoan vay ngan hang
                                                    if (Convert.ToDouble(SoTienVay) > 0)
                                                    {
                                                        CTPT.Add(new ChiTietPhieuThu());
                                                        CTPT[1].HinhThucThanhToan = "NH";
                                                        NHCV = NHCV.ToUpper();
                                                        CTPT[1].MaNganHang = NHCV;
                                                        CTPT[1].SoTienThanhToan = Convert.ToDouble(SoTienVay);
                                                        CTPT[1].Temp = NHCV + "-NH";
                                                        CTPT[1].SoThamChieu = STC;
                                                        if (TreoTien == "1")
                                                            CTPT[1].TinhTrang = true;
                                                        else
                                                            CTPT[1].TinhTrang = false;

                                                        double TongTienVay = 0;
                                                        foreach (var thanhtoan in CTPT)
                                                        {
                                                            TongTienVay += thanhtoan.SoTienThanhToan;
                                                        }
                                                        item.SoTienThu = TongTienVay;
                                                    }
                                                    lstPhieuThu.Add(item);
                                                    lstChiTietPhieuThu.Add(CTPT);
                                                }
                                                else
                                                    error += Environment.NewLine + "Dòng " + (rowNum - 1) + ": Sai định dạng ngày thu. Vui lòng kiểm tra lại.";

                                            }
                                            catch (Exception exx)
                                            {
                                                error += Environment.NewLine + "Dòng " + (rowNum - 1) + ": " + exx;
                                            }
                                        }
                                    }
                                    if (string.IsNullOrEmpty(error))
                                    {
                                        for (int i = 0; i < lstPhieuThu.Count; i++)
                                        {

                                            string xml = "<formdata><Action>PhieuThu</Action>";
                                            xml += Environment.NewLine + "<submit>Import từ excel</submit>";
                                            if (lstPhieuThu[i] != null)
                                                xml += TNK.Core.Common.ConvertObjectToXMLString(lstPhieuThu[i]);
                                            if (lstChiTietPhieuThu[i] != null)
                                            {
                                                xml += Environment.NewLine + "<ThanhToan>";
                                                foreach (ChiTietPhieuThu ct in lstChiTietPhieuThu[i])
                                                    xml += TNK.Core.Common.ConvertObjectToXMLString(ct);
                                                xml += Environment.NewLine + "</ThanhToan>";
                                            }
                                            xml += "</formdata>";
                                            // string message = _phieuThuService.CreatePhieuThu(obj, httt, false);
                                            string messagePT = _phieuThuService.CreatePhieuThu(lstPhieuThu[i], lstChiTietPhieuThu[i], false);
                                            if (messagePT != "")
                                                error += Environment.NewLine + "Dòng " + (i + 1) + "(" + SoHopDong + "):" + messagePT;
                                            _phieuThuService.XuLySauKhiInsertPhieuThu(lstPhieuThu[i].MaPhieuThu, xml);
                                            //string result = _phieuThuService.XuLySauKhiInsertPhieuThu(obj.MaPhieuThu, xml);
                                        }
                                    }
                                    #endregion
                                }
                            }
                        }
                    }
                }
            }
            catch (Exception objEx)
            {
                _logger.WriteLog("SoThuController.ImportData_ThuBanXe:" + objEx);
                return Json(new { IsError = true, Message = "Lỗi import excel." });
            }
            if (string.IsNullOrEmpty(error))
            {
                return Json(new
                {
                    IsError = false,
                    Message = ""
                });
            }
            else
            {
                _logger.WriteLog("SoThuController.ImportData_ThuBanXe:" + error);
                return Json(new { IsError = true, Message = error });
            }

        }
