        [HttpPost]
        public ActionResult DeleteKMBX(string id)
        {
            if (CurrentUser.ReadOnly == true)
            {
                return Content("Bạn không có quyền xóa!");
            }
            if (string.IsNullOrEmpty(id))
                return Content("success");
            NoPhaiTra npt = _noPhaiTraService.Get(id);
            if (npt == null || npt.SoTienDaTra > 0)
            {
                return Content("Không thể xóa do khuyến mãi đã bị xóa trước đó hoặc đã được chi trả");
            }
            else
                return Content("success");

        }

