        #region Cập nhật hóa đơn xác nhận công nợ
        public ActionResult CNHDCNIndex(string submit, string from = "", string to = "", string type = "", string query = "", int p = 1, int tab = 1, string tinhtrang = "")
        {
            DateTime start = DateTime.Now;
            try
            {
                switch (submit)
                {
                    case "Tìm kiếm giải trình":
                        submit = "SearchGiaiTrinh";
                        break;
                    default:
                        submit = "Search";
                        break;

                }
                ViewBag.Submit = submit;
                ViewBag.Title = "Cập nhật hóa đơn, xác nhận công nợ";
                DateTime f = new DateTime(), t = new DateTime();
                SetSearch(ref from, ref to, ref f, ref t, p, ref query, "CNHDCNIndex");
                var model = _phieuThuService.GetListHDXNCN(f, t, query, type, p, ref total, pageSize, tinhtrang);
                ViewBag.Tab = tab;
                ViewBag.Total = total;
                ViewBag.Type = type;
                DateTime end = DateTime.Now;
                this.AddActionLog(CurrentUser.UserName,"SoThu", "CNHDCNIndex", start, end, "");
                return View(model);
            }
            catch (Exception ex)
            {
                _logger.WriteLog("SoThuController:T2THKIndex" + ex.ToString());
                DateTime end = DateTime.Now;
                this.AddActionLog(CurrentUser.UserName,"SoThu", "T2THKIndex", start, end, ex);
                TempData["Error"] = ex;
            }
            return View();
        }
