        //Đồng bộ Cyber
        public ActionResult CyberIndex(string From = "", string To = "", string type="", string typeSearch = "", int p = 1, string query = "", int pageSize = 30)
        {
            ViewBag.Title = "Phiếu thu Cyber";
            DateTime from = DateTime.Now, to = DateTime.Now;
            _cacheManager.Remove("PhieuThuCyber" + CurrentUser.UserName);
            SetSearch(ref From, ref To, ref from, ref to, p, ref query, "CyberIndex");
            var model = _phieuThuService.GetListViewPhieuThuCyber(from, to, p, ref total, pageSize, query, typeSearch);
            _cacheManager.Set("PhieuThuCyber" + CurrentUser.UserName, model, 120);
            ViewBag.Total = total;
            ViewBag.TypeSearch = typeSearch;
            ViewBag.SearchHolder = "Họ tên, Biển số, Nội dung, Mã tài khoản , Số chứng từ,...";
            return View(model);
        }
        public JsonResult GetModelPhieuThuCyber(string Type)
