                    listBH.Add(new DropDownListItem("Hỗ trợ xe xuất", "HTXX"));
                    listBH.Add(new DropDownListItem("Khác", "KHAC"));
                    model.LoaiBH = listBH;
                    break;
                case "THHHB":
                    model.DoiTac = _soThuService.GetDoiTac("HHHB");
                    break;
                case "TVAMU":
                    model.DoiTac = _soThuService.GetDoiTac("VM");
                    break;
                case "TLADT":
                    model.DoiTac = _soThuService.GetDoiTac("DTU");
                    break;
                case "TBHXH":
                    model.DoiTac = _soThuService.GetDoiTac("NCC");
                    break;
                case "T2THK":
                    model.DoiTac = _soThuService.GetDoiTac("NCC");
                    break;
                case "T2GTX":
                    model.DoiTac = _soThuService.GetDoiTac("NCC");
                    break;
                case "TCONO":
                    model.DoiTac = _soThuService.GetDoiTac("BH");
                    break;
              /*  case "TBDTK":
                    model.MauXe = _categoryService.GetCategoryItem("COLOR");
                    model.MaXe = _categoryService.GetCategoryItem("MODEL");
                    model.GoiBDTK = _phieuThuService.GetListGBDTK();
                    model.CTBDTK = _phieuThuService.GetListCTBDTK(model.Item.MaPhieuThu);
                    if (model.CTBDTK.Count == 0)
                        model.CTBDTK.Add(new ChiTietBaoDuongTietKiem());
                    break;
                case "TBDTKKM":
                    model.MauXe = _categoryService.GetCategoryItem("COLOR");
                    model.MaXe = _categoryService.GetCategoryItem("MODEL");
                    model.GoiBDTK = _phieuThuService.GetListGBDTK();
                    model.CTBDTK = _phieuThuService.GetListCTBDTK(model.Item.MaPhieuThu);
                    if (model.CTBDTK.Count == 0)
                        model.CTBDTK.Add(new ChiTietBaoDuongTietKiem());
                    break;
            */
                default:
                    break;

            }
            return Json(new { model, JsonRequestBehavior.AllowGet });
        }
        public ActionResult DongBoPhieuThuCyber(string type, string TaiTuc, string DoiTac, string Loai, string MaLoaiXe, string MauXe, string From = "", string To = "", string query = "")
        {

            string ids = "";
            string error = "";
            var cookie = Request.Cookies.Get("link");
            if (cookie != null)
            {
                ids = cookie.Value;

                List<string> list = ids.Split(',').ToList();
                if (list.Count <= 0)
                    return Json(new { IsError = true, Message = "Vui lòng chọn phiếu thu" });
                switch (type)
                {

                    case "TBAXE":
                        error += DongBoPhieuBanXeCyber(list);
                        break;
                    case "TDIVU":
                        error += DongBoPhieuThuDVuCyber(ids);
                        break;
                    case "TKHAC":
                        error += DongBoPhieuThuKhacCyber(list, DoiTac, Loai, From, To, query);
                        break;
                    case "TCODV":
                        error += DongBoPhieuThuCocDV(list, MaLoaiXe, MauXe, From, To, query);
                        break;
                    case "TCOBX":
                        error += DongBoPhieuThuCocBX(list, MaLoaiXe, MauXe, From, To, query);
                        break;
                    //case "TBAHI":
                    //    error += DongBoPhieuThuBaoHiem(list, TaiTuc, DoiTac, From, To, query);
                    //    break;
                    case "THHHB":
                        error += DongBoTHHHB(list, DoiTac, From, To, query);
                        break;
                    case "TCONO":
                        error += DongBoTCONO(list, DoiTac, From, To, query);
                        break;
                    case "T2THK":
                        error += DongBoT2THK(list, DoiTac, From, To, query);
                        break;
                    case "TBHXH":
                        error += DongBoTBHXH(list, DoiTac, From, To, query);
                        break;
                    case "T2GTX":
                        error += DongBoT2GTX(list, DoiTac, From, To, query);
                        break;
                    case "TVAMU":
                        error += DongBoTVAMU(list, DoiTac, From, To, query);
                        break;
                    case "TLADT":
                        error += DongBoTLADT(list, DoiTac, From, To, query);
                        break;
                }

            }
            else
            {
                return Json(new { IsError = true, Message = "Vui lòng chọn phiếu thu" });
            }
            if (error == "")
                return Json(new { IsError = false, Message = "Đồng bộ phiếu thu từ Cyber thành công." });
            return Json(new { IsError = true, Message = error });
        }
        public ActionResult DongBoPhieuThuDVuCyber(string ids)
        {
            string error = ""; //string ids = "";
            //var cookie = Request.Cookies.Get("link");
            int idx = 1;
            if (ids != null)
            {
                //ids = cookie.Value;
                ids = ids.Replace(".", "");

                List<string> list = ids.Split(',').ToList();

                foreach (string id in list)
                {

                    PhieuThu obj = new PhieuThu();
                    var phieuthu = _phieuThuService.GetPDVTCybers(id);//get phieuthu
                    List<CTPDVTamCyber> lst = _phieuThuService.GetCTPDVTCybers(id);//get chitietphieu
                    if (phieuthu != null)
                    {
                        #region Phiếu thu
                        obj.SoHopDong = phieuthu.REPAIRORDERNO;
                        if (!string.IsNullOrEmpty(phieuthu.REGISTERNO))
                        {
                            obj.BienSo = phieuthu.REGISTERNO.Replace(".", "").Replace(" ", "");
                        }
                        obj.MaLoaiPhieu = "TDIVU";
                        obj.NgayThu = phieuthu.NgayThu;
                        obj.SoKhung = phieuthu.FRAMENO;
                        obj.HoTen = phieuthu.CAROWNERNAME;
                        obj.MaXe = phieuthu.CF_TYPE;
                        obj.DienThoai = phieuthu.CAROWNERTEL;
                        obj.NgayQuyetToan = (DateTime)phieuthu.RO_DATE;
                        obj.TenXe = phieuthu.CM_NAME;
                        obj.DiaChi = phieuthu.CAROWNERADD;
                        obj.YeuCauKH = phieuthu.REQUEST_DESC;
                        obj.SoHoaDon = phieuthu.INVOICE;
                        obj.SoChungTu = phieuthu.R_Documents;
                        obj.HoaHongTaiXe = phieuthu.DRIVERREMUNERATION;
                        obj.NguoiDuyetHHTX = phieuthu.APPROVEDREMUNERATION;
                        obj.NguoiThuTien = _authenticationService.GetAuthenticatedUser().UserId;
                        #endregion
                        List<ChiTietPhieuThu> httt = new List<ChiTietPhieuThu>();
                        if (phieuthu.PAYMENTCUSTOMERS != null)
                        {
                            var kh_TT = phieuthu.PAYMENTCUSTOMERS.Split('{', '}').Where(s => !string.IsNullOrEmpty(s));
                            foreach (var i in kh_TT)
                            {
                                var ct = i.Split(',');
                                ChiTietPhieuThu chiTiet = new ChiTietPhieuThu();
                                chiTiet.Temp = ct[1] + "-" + ct[0];
                                chiTiet.HinhThucThanhToan = ct[0];
                                chiTiet.MaNganHang = ct[1];
                                chiTiet.SoTienThanhToan = double.Parse(ct[2]);
                                httt.Add(chiTiet);
                            }
                        }
                        //add bao hiểm thanh toán
                        if (!string.IsNullOrEmpty(phieuthu.InsuranceCompany))
                        {
                            ChiTietPhieuThu chiTiet = new ChiTietPhieuThu();
                            chiTiet.MaNganHang = phieuthu.InsuranceCompany;
                            chiTiet.SoTienThanhToan = phieuthu.PaymentInsurance;
                            chiTiet.HinhThucThanhToan = "BH";
                            chiTiet.Temp = chiTiet.MaNganHang + "-BH";
                            httt.Add(chiTiet);
                        }
                        //Cọc
                        if (obj.BienSo != "")
                        {
                            var Cocs = _phieuThuService.GetTCODVByBienSo(obj.BienSo, true);
                            var coc = Cocs.Where(s => s.MaPhieuThu == phieuthu.DEPOSITDOCUMENTS).FirstOrDefault();//Cọc đã dùng
                            if (coc != null)
                            {
                                ChiTietPhieuThu chiTiet = new ChiTietPhieuThu();
                                chiTiet.MaNganHang = "COCDV";
                                chiTiet.SoTienThanhToan = phieuthu.PaymentInsurance;
                                chiTiet.HinhThucThanhToan = "DC";
                                chiTiet.SoThamChieu = coc.MaPhieuThu;
                                chiTiet.Temp = "COCDV-DC";
                                httt.Add(chiTiet);
                            }

                        }
                        //Chi tiết phiếu dịch vụ
                        List<ChiTietPhieuDichVu> CTDV = new List<ChiTietPhieuDichVu>();
                        foreach (var i in lst)
                        {
                            ChiTietPhieuDichVu ctdv = new ChiTietPhieuDichVu();
                            ctdv.REPAIRORDERNO = phieuthu.REPAIRORDERNO;
                            ctdv.JOBSNAME = i.JOBSNAME;
                            ctdv.QUANTITY = 0;
                            ctdv.COST = (double)i.COST;
                            ctdv.DISCOUNT = (double)i.DISCOUNT;
                            ctdv.VAT = (double)i.THUE;
                            switch (i.JOBTYPE)
                            {
                                case "SCC":
                                    ctdv.MaKho = "SCC";
                                    ctdv.PhanLoai = "SUACHUA";
                                    break;
                                case "DS":
                                    ctdv.MaKho = "KHO_DS";
                                    ctdv.PhanLoai = "KHO_DS";
                                    break;
                                case "PTT":
                                    ctdv.MaKho = "KHO_PTT";
                                    ctdv.PhanLoai = "KHO_PTT";
                                    break;
                                case "PTN":
                                    ctdv.MaKho = "KHO_PTN";
                                    ctdv.PhanLoai = "KHO_PTN";
                                    break;
                                case "PKDV":
                                    ctdv.MaKho = "KHO_PKDV";
                                    ctdv.PhanLoai = "KHO_PKDV";
                                    break;
                            }
                            CTDV.Add(ctdv);
                            obj.SoTienThu += ((double)i.COST - (double)i.DISCOUNT) * (1 + i.THUE);
                            obj.TongCong += ((double)i.COST - (double)i.DISCOUNT) * (1 + i.THUE);
                        }

                        //obj.SoTienThu = Math.Round(obj.SoTienThu * 1.1);
                        //obj.TongCong = Math.Round(obj.TongCong * 1.1);
                        string xml = "<Action>DVCreate</Action>";
                        if (obj != null)
                            xml += TNK.Core.Common.ConvertObjectToXMLString(obj);
                        if (httt != null)
                        {
                            xml += Environment.NewLine + "<ThanhToan>";
                            foreach (ChiTietPhieuThu ct in httt)
                                xml += TNK.Core.Common.ConvertObjectToXMLString(ct);
                            xml += Environment.NewLine + "</ThanhToan>";
                        }
                        //if (coc != null)
                        //{
                        //    xml += Environment.NewLine + "<Coc>";
                        //    foreach (ChiTietPhieuThu ct in coc)
                        //        xml += TNK.Core.Common.ConvertObjectToXMLString(ct);
                        //    xml += Environment.NewLine + "</Coc>";
                        //}
                        if (CTDV != null)
                        {
                            xml += Environment.NewLine + "<ChiTietPhieuDichVu>";
                            foreach (ChiTietPhieuDichVu ct in CTDV)
                                xml += TNK.Core.Common.ConvertObjectToXMLString(ct);
                            xml += Environment.NewLine + "</ChiTietPhieuDichVu>";
                        }
                        //if (ctbh != null)
                        //    xml += TNK.Core.Common.ConvertObjectToXMLString(ctbh);
                        //if (NPT != null)
                        //    xml += TNK.Core.Common.ConvertObjectToXMLString(NPT);
                        //if (GCN != null)
                        //{
                        //    foreach (string ct in GCN)
                        //        xml += TNK.Core.Common.ConvertObjectToXMLString(ct);
                        //}
                        //if (noPhaiTra != null)
                        //    xml += TNK.Core.Common.ConvertObjectToXMLString(noPhaiTra);

                        xml = "<formdata>" + Environment.NewLine + xml + Environment.NewLine + "</formdata>";



                        string message = _phieuThuService.CreatePhieuThu(obj, httt, false, "");

                        if (string.IsNullOrEmpty(message))
                        {
                            bool bl = _soThuService.InsertChiTietPhieuDichVu(CTDV, obj.MaPhieuThu);
                            if (bl == false)
                                error = error + "Lỗi tạo chi tiết phiếu dịch vụ";
                            //neu co no thi mmoi insert no phai tra HHTX
                            //if (noPhaiTra.SoTienNo > 0)
                            //    _noPhaiTraService.InsertNoPhaiTra(noPhaiTra, obj.MaPhieuThu);
                            //xu ly sau khi insert phieu thu
                            if (idx != list.Count)
                            {
                                _phieuThuService.XuLySauKhiInsertPhieuThu(obj.MaPhieuThu, xml, false);
                            }
                            else
                            {
                                _phieuThuService.XuLySauKhiInsertPhieuThu(obj.MaPhieuThu, xml, true);
                            }
                            // string result = _phieuThuService.XuLySauKhiInsertPhieuThu(obj.MaPhieuThu, xml);

                        }
                        else
                        {
                            error = error + ";" + message;
                        }

                    }
                    else
                        error += "Không tìm thấy phiếu thu tổng hợp hoặc đã có phiếu thu trên pmtc cho phiếu thu có số hợp đông " + id + "\n";
                    idx++;
                }
            }
            else
            {
                return Json(new { IsError = true, Message = "Vui lòng chọn phiếu thu" });
            }
            if (error == "")
                return Json(new { IsError = false, Message = "Đồng bộ phiếu thu từ Cyber thành công." });
            return Json(new { IsError = true, Message = error });
        }
