        public string DongBoPhieuThuCocDV(List<string> list, string MaLoaiXe, string MauXe, string From = "", string To = "", string query = "", string type = "")
        {
            string error = "";
            DateTime from = DateTime.Now, to = DateTime.Now;
            SetSearch(ref From, ref To, ref from, ref to, 1, ref query, "CyberIndex");
            // List<ViewPhieuThuCyber> lstPhieuThu = _phieuThuService.GetListViewPhieuThuCyber(from, to, 1, ref total, 100000, query);
            List<ViewPhieuThuCyber> lstPhieuThu = _cacheManager.Get("PhieuThuCyber" + CurrentUser.UserName, () => _phieuThuService.GetListViewPhieuThuCyber(from, to, 1, ref total, 100000, query, type));
            foreach (string id in list)
            {

                PhieuThu obj = new PhieuThu();
                var phieuthu = lstPhieuThu.FirstOrDefault(x => x.SttRec == id);
                if (phieuthu != null)
                {
                    #region Phiếu thu
                    obj.SoChungTu = phieuthu.SoChungTu;
                    obj.MaLoaiPhieu = "TCODV";
                    obj.NgayThu = phieuthu.NgayThu;
                    obj.BienSo = phieuthu.BienSo;
                    obj.DienThoai = phieuthu.Dien_Thoai;
                    obj.DiaChi = phieuthu.Dia_Chi;
                    obj.HoTen = phieuthu.HoTen;
                    obj.GiaBan = phieuthu.GiaVon;
                    obj.NoiDung = phieuthu.NoiDung;
                    obj.MaXe = MaLoaiXe;
                    obj.MauXe = MauXe;
                    obj.LoaiXe = MaLoaiXe;
                    obj.NguoiThuTien = CurrentUser.UserId;
                    #endregion
                    List<ChiTietPhieuThu> httt = new List<ChiTietPhieuThu>();
                    if (phieuthu.ThanhToan != null)
                    {
                        var kh_TT = phieuthu.ThanhToan.Split('{', '}').Where(s => !string.IsNullOrEmpty(s));
                        foreach (var i in kh_TT)
                        {
                            var ct = i.Split(',');
                            ChiTietPhieuThu chiTiet = new ChiTietPhieuThu();
                            chiTiet.Temp = ct[1] + "-" + ct[0];
                            chiTiet.HinhThucThanhToan = ct[0];
                            chiTiet.MaNganHang = ct[1];
                            chiTiet.SoTienThanhToan = double.Parse(ct[2]);
                            httt.Add(chiTiet);
                        }
                    }
                    obj.SoTienThu = Math.Round(obj.SoTienThu * 1.1);
                    obj.TongCong = Math.Round(obj.SoTienThu * 1.1);

                    obj.GhiChu = phieuthu.GhiChu;
                    obj.IsDeleted = false;
                    obj.CreatedBy = CurrentUser.UserId;
                    obj.CreatedDate = DateTime.Now;
                    obj.CyberId = phieuthu.SttRec;
                    string xml = "<Action>DVCreate</Action>";
                    if (obj != null)
                        xml += TNK.Core.Common.ConvertObjectToXMLString(obj);
                    if (httt != null)
                    {
                        xml += Environment.NewLine + "<ThanhToan>";
                        foreach (ChiTietPhieuThu ct in httt)
                            xml += TNK.Core.Common.ConvertObjectToXMLString(ct);
                        xml += Environment.NewLine + "</ThanhToan>";
                    }

                    xml = "<formdata>" + Environment.NewLine + xml + Environment.NewLine + "</formdata>";
                    string message = _phieuThuService.CreatePhieuThu(obj, httt, false);

                    if (string.IsNullOrEmpty(message))
                    {
                        string result = _phieuThuService.XuLySauKhiInsertPhieuThu(obj.MaPhieuThu, xml);
                    }
                    else
                    {
                        error = error + ";" + message;
                    }

                }
                else
                    error += "Không tìm thấy phiếu thu tổng hợp hoặc đã có phiếu thu trên pmtc cho phiếu thu có số hợp đông " + id + "\n";
            }
            return error;
        }
